RC2_VERSION <- "rc2_domains_v6_one_run_20260924"
rc2_source_path <- function() {
  z <- unlist(lapply(sys.frames(), function(e) {
    f <- e$ofile; if (is.null(f)) character() else as.character(f)
  }), use.names=FALSE)
  z <- z[file.exists(z)]
  if (length(z)) normalizePath(tail(z,1),winslash="/",mustWork=TRUE) else ""
}
RC2_SCRIPT_PATH <- rc2_source_path()
RC2_ACTIVE_OUTPUT <- ""
RC2_ACTIVE_ROOT <- ""
RC2_LOG <- ""
rc2_num <- function(x) {
  if (is.factor(x)) x <- as.character(x)
  if (inherits(x,"haven_labelled")) x <- unclass(x)
  suppressWarnings(as.numeric(x))
}
rc2_chr <- function(x) {
  if (inherits(x,"haven_labelled")) x <- unclass(x)
  y <- as.character(x); y[is.na(x)] <- NA_character_; trimws(y)
}
rc2_norm <- function(p) normalizePath(p,winslash="/",mustWork=FALSE)
# Sanitize only the timestamp, never the Windows drive/UNC/directory prefix.
rc2_previous_path <- function(p) {
  stamp<-gsub('[^0-9_]','',format(Sys.time(),'%Y%m%d_%H%M%OS6'))
  base<-paste0(p,'.previous_',stamp);prior<-base;i<-0L
  while(file.exists(prior)){i<-i+1L;prior<-paste0(base,'_',i)}
  prior
}
rc2_bind <- function(xs) {
  xs <- Filter(function(x) is.data.frame(x) && nrow(x)>0L,xs)
  if (!length(xs)) return(data.frame())
  nn <- unique(unlist(lapply(xs,names),use.names=FALSE))
  xs <- lapply(xs,function(x) {
    for (n in setdiff(nn,names(x))) x[[n]] <- NA
    x <- x[,nn,drop=FALSE]; rownames(x) <- NULL; x
  })
  ans <- do.call(rbind,xs); rownames(ans) <- NULL; ans
}
rc2_csv <- function(x,p) {
  dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE)
  write.csv(x,p,row.names=FALSE,na="",fileEncoding="UTF-8")
}
rc2_sha <- function(p) unname(digest::digest(file=p,algo="sha256"))
rc2_save <- function(x,p) {
  dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE)
  tmp <- tempfile("write_",tmpdir=dirname(p),fileext=".rds")
  on.exit(if(file.exists(tmp))unlink(tmp),add=TRUE)
  saveRDS(x,tmp,compress=FALSE)
  y <- readRDS(tmp)
  if (!identical(x,y)) stop("RDS roundtrip failed: ",p)
  rm(y)
  if (file.exists(p)) {
    old <- rc2_previous_path(p)
    if (!file.rename(p,old)) stop("Could not preserve old RC2 cache: ",p)
  }
  if (!file.rename(tmp,p)) stop("Atomic RC2 cache save failed: ",p)
  invisible(p)
}
rc2_weighted_mean <- function(x,w) {
  ok <- is.finite(x)&is.finite(w)&w>0
  if (!any(ok)) return(NA_real_)
  sum(x[ok]*w[ok])/sum(w[ok])
}
rc2_quantile <- function(y,w,p) {
  ok <- is.finite(y)&is.finite(w)&w>0
  if (!any(ok)) return(rep(NA_real_,length(p)))
  y <- y[ok]; w <- w[ok]; o <- order(y)
  y <- y[o]; cw <- cumsum(w[o])/sum(w)
  vapply(p,function(pr) y[which(cw>=pr)[1]],numeric(1))
}
rc2_between <- function(y,cl,w) {
  ok <- is.finite(y)&is.finite(w)&w>0&!is.na(cl)&nzchar(cl)
  if (sum(ok)<10L) return(NA_real_)
  y <- y[ok]; cl <- cl[ok]; w <- w[ok]
  mu <- sum(w*y)/sum(w); tv <- sum(w*(y-mu)^2)/sum(w)
  if (!is.finite(tv)||tv<=0) return(NA_real_)
  sw <- as.numeric(rowsum(w,cl,reorder=FALSE))
  sy <- as.numeric(rowsum(w*y,cl,reorder=FALSE))
  100*sum(sw*(sy/sw-mu)^2)/sum(w)/tv
}
rc2_tails_rank <- function(x,w,target=.25) {
  q1 <- q4 <- rep(0,length(x)); rank <- rep(NA_real_,length(x))
  ok <- is.finite(x)&is.finite(w)&w>0
  if (!any(ok)) return(list(q1=q1,q4=q4,rank=rank,share1=NA,share4=NA))
  vals <- sort(unique(x[ok])); ix <- match(x[ok],vals)
  gw <- as.numeric(rowsum(w[ok],ix,reorder=TRUE)); W <- sum(gw)
  before <- c(0,head(cumsum(gw),-1)); after <- before+gw
  lo <- pmax(0,pmin(gw,target*W-before))/gw
  hi <- pmax(0,pmin(gw,after-(1-target)*W))/gw
  q1[ok] <- lo[ix]; q4[ok] <- hi[ix]
  rank[ok] <- ((before+.5*gw)/W)[ix]
  s1 <- sum(w[ok]*q1[ok])/W; s4 <- sum(w[ok]*q4[ok])/W
  if (abs(s1-target)>1e-9||abs(s4-target)>1e-9) stop("Fractional quartile check failed")
  list(q1=q1,q4=q4,rank=rank,share1=s1,share4=s4)
}
rc2_replicate_design <- function(d,survey,year) {
  w <- d$W; base <- is.finite(w)&w>0
  if (any(!is.finite(w))||any(w<0)) stop("Missing/negative final weights")
  if (survey=="PISA") {
    rw <- paste0("RW",1:80)
    if (!all(rw %in% names(d))) stop("PISA: complete RW1:RW80 required")
    if (any(!vapply(d[rw],function(x) all(is.finite(x)&x>=0),logical(1))))
      stop("PISA: missing/negative replicate weights")
    return(list(survey=survey,year=year,w=w,rw=as.matrix(d[rw]),
                n=80L,factor=1/20,method="PISA_BRR_FAY_80_fay0.5",single_zones=0L))
  }
  z <- d$JKZONE; r <- d$JKREP
  if (any(base & (!is.finite(z)|!is.finite(r)|!r %in% c(0,1))))
    stop("TIMSS: positive-weight record with invalid/missing JKZONE/JKREP")
  zones <- sort(unique(z[base])); if (!length(zones)) stop("No JRR zones")
  single <- sum(vapply(zones,function(h) length(unique(r[base&z==h]))==1L,logical(1)))
  keep <- if (year<2015L) 1 else c(0,1)
  list(survey=survey,year=year,w=w,zone=z,repc=r,zones=rep(zones,each=length(keep)),
       keep=rep(keep,times=length(zones)),n=length(zones)*length(keep),
       factor=if(year<2015L)1 else .5,
       method=if(year<2015L)"TIMSS_JRR_ONE_PER_ZONE" else "TIMSS_JRR_TWO_PER_ZONE",
       single_zones=single)
}
rc2_repweight <- function(des,r) {
  if (des$survey=="PISA") return(des$rw[,r])
  w <- des$w; j <- is.finite(des$zone)&des$zone==des$zones[r]
  w[j] <- ifelse(des$repc[j]==des$keep[r],2*w[j],0); w
}
rc2_pool <- function(full,rep_est,factor) {
  # full: M x K; rep_est: R x M x K. No incomplete-PV pooling.
  M <- nrow(full); K <- ncol(full); R <- dim(rep_est)[1]
  ans <- vector("list",K)
  for (k in seq_len(K)) {
    th <- full[,k]; finite_by_pv <- integer(M); U <- rep(NA_real_,M)
    for (m in seq_len(M)) {
      rr <- rep_est[,m,k]; finite_by_pv[m] <- sum(is.finite(rr))
      if (is.finite(th[m])&&finite_by_pv[m]==R)
        U[m] <- factor*sum((rr-th[m])^2)
    }
    point_ok <- all(is.finite(th)); inference_ok <- point_ok&&all(is.finite(U))
    point <- if(point_ok)mean(th) else NA_real_
    b <- if(point_ok&&M>1L)(1+1/M)*var(th) else if(point_ok)0 else NA_real_
    u <- if(inference_ok)mean(U) else NA_real_; v <- u+b
    ans[[k]] <- data.frame(statistic=colnames(full)[k],estimate=point,
      se=if(inference_ok)sqrt(v) else NA_real_,
      ci_low=if(inference_ok)point-1.96*sqrt(v) else NA_real_,
      ci_high=if(inference_ok)point+1.96*sqrt(v) else NA_real_,
      sampling_variance=u,pv_imputation_variance=b,total_variance=v,
      expected_pvs=M,finite_full_pvs=sum(is.finite(th)),expected_replicates=R,
      finite_replicates_min=min(finite_by_pv),finite_replicates_max=max(finite_by_pv),
      complete_replication=inference_ok,
      inference_status=if(inference_ok)"COMPLETE_REPLICATION_PENDING_EXTERNAL_VALIDATION" else
        if(point_ok)"HOLD_INCOMPLETE_REPLICATION" else "OUTCOME_UNAVAILABLE",
      stringsAsFactors=FALSE)
  }
  rc2_bind(ans)
}
rc2_isced <- function(x) {
  v <- rc2_num(x); out <- rep(NA_real_,length(v))
  direct <- is.finite(v)&v %in% 0:8; out[direct] <- v[direct]
  programme <- is.finite(v)&v>=100&v<=899; out[programme] <- floor(v[programme]/100)
  out[is.na(out)&v %in% c(10,20)] <- 0
  out
}
rc2_modal_mask <- function(isced,school) {
  valid <- is.finite(isced)&isced %in% 0:8
  if(sum(valid)<100L)return(list(mask=rep(FALSE,length(isced)),levels="",status="ISCED_SUPPORT_UNAVAILABLE"))
  t <- table(isced[valid]); selected <- as.numeric(names(t)[as.numeric(t)/sum(t)>=1/3])
  if(!length(selected))selected <- as.numeric(names(t)[which.max(t)])
  schools <- unique(school[valid&isced %in% selected&!is.na(school)&nzchar(school)])
  mask <- !is.na(school)&nzchar(school)&school %in% schools
  if(sum(mask)<100L)return(list(mask=rep(FALSE,length(isced)),levels=paste(selected,collapse=";"),status="MODAL_SUPPORT_UNAVAILABLE"))
  list(mask=mask,levels=paste(selected,collapse=";"),status="RC1_ALIGNED_MODAL_SCHOOL_SENSITIVITY")
}

rc2_pv_stats <- function(y,d,w,tails,thresholds) {
  q <- rc2_quantile(y,w,c(.1,.5,.9)); mu <- rc2_weighted_mean(y,w)
  out <- c(overall_mean=mu,p10=q[1],p50=q[2],p90=q[3],p90_p10=q[3]-q[1],
    variance=rc2_weighted_mean((y-mu)^2,w),
    q1_mean=rc2_weighted_mean(y,w*tails$q1),
    q4_mean=rc2_weighted_mean(y,w*tails$q4),
    score_gap=rc2_weighted_mean(y,w*tails$q4)-rc2_weighted_mean(y,w*tails$q1),
    academic_school_sorting_share=rc2_between(y,d$SCHOOL,w),
    academic_classroom_sorting_share=rc2_between(y,d$CLASS,w),
    academic_modal_school_sorting_share=rc2_between(y,d$SCHOOL,w*as.numeric(d$MODAL)))
  for (nm in names(thresholds)) {
    z <- ifelse(is.finite(y),as.numeric(y>=thresholds[nm]),NA_real_)
    a <- rc2_weighted_mean(z,w*tails$q1); b <- rc2_weighted_mean(z,w*tails$q4)
    out[paste0("overall_",nm)] <- rc2_weighted_mean(z,w)
    out[paste0("q1_",nm)] <- a; out[paste0("q4_",nm)] <- b
    out[paste0("gap_",nm)] <- b-a
  }
  if (isTRUE(d$HAS_BOOKS_CATEGORIES[1])) {
    for (g in 1:5) out[paste0("books",g,"_mean")] <-
      rc2_weighted_mean(y,w*as.numeric(!is.na(d$SES)&d$SES==g))
  }
  out
}
rc2_stat_unit <- function(x) {
  ifelse(grepl("sorting_share",x),"percent_of_variance",
    ifelse(grepl("prof|baseline|top|ge400|ge475|ge550|ge625|level2|level5",x),"proportion_or_proportion_difference",
      ifelse(x=="variance","score_points_squared","score_points")))
}
rc2_selftest <- function() {
  results <- list(); add <- function(n,ok) {
    results[[length(results)+1L]] <<- data.frame(check=n,pass=isTRUE(ok))
    if (!isTRUE(ok)) stop("SELF-TEST FAILED: ",n)
  }
  x <- rep(1:5,c(2,4,6,8,10)); w <- seq_along(x)/10
  t <- rc2_tails_rank(x,w)
  add("fractional_q1_exact25",abs(sum(w*t$q1)/sum(w)-.25)<1e-12)
  add("fractional_q4_exact25",abs(sum(w*t$q4)/sum(w)-.25)<1e-12)
  add("midranks_in_unit_interval",all(t$rank>0&t$rank<1))
  add("tails_scale_invariant",isTRUE(all.equal(t,rc2_tails_rank(x,7*w),tolerance=1e-12)))
  d <- data.frame(W=rep(1,8),JKZONE=rep(1:2,each=4),JKREP=rep(c(0,0,1,1),2))
  a <- rc2_replicate_design(d,"TIMSS",2011); b <- rc2_replicate_design(d,"TIMSS",2015)
  add("TIMSS2011_one",a$n==2&&a$factor==1)
  add("TIMSS2015_two",b$n==4&&b$factor==.5)
  add("legacy_keeps_JKREP1",identical(rc2_repweight(a,1),c(0,0,2,2,1,1,1,1)))
  add("complementary_weights",all(rc2_repweight(b,1)+rc2_repweight(b,2)==2*d$W))
  s <- d; s$JKREP[1:4] <- 1
  add("single_half_not_deleted",rc2_replicate_design(s,"TIMSS",2023)$n==4)
  bad <- d; bad$JKREP[1] <- 9
  add("invalid_repcode_rejected",inherits(try(rc2_replicate_design(bad,"TIMSS",2023),silent=TRUE),"try-error"))
  y <- c(rep(0,10),rep(1,10)); cl <- rep(c("a","b"),each=10)
  add("between_perfect_sorting",abs(rc2_between(y,cl,rep(1,20))-100)<1e-10)
  add("between_zero_sorting",abs(rc2_between(rep(c(0,1),10),cl,rep(1,20)))<1e-10)
  full <- matrix(c(2,4),ncol=1,dimnames=list(NULL,"test"))
  reps <- array(c(1,3,3,5),dim=c(2,2,1))
  p <- rc2_pool(full,reps,.5)
  add("PV_pool_point",p$estimate==3)
  add("PV_pool_U",p$sampling_variance==1)
  add("PV_pool_MI",p$pv_imputation_variance==3)
  add("PV_pool_SE",p$se==2)
  reps[1,1,1] <- NA; p <- rc2_pool(full,reps,.5)
  add("missing_rep_blocks_inference",p$estimate==3&&is.na(p$se)&&!p$complete_replication)
  full[1,1] <- NA; p <- rc2_pool(full,reps,.5)
  add("missing_PV_blocks_point",is.na(p$estimate))
  dp <- data.frame(W=rep(1,20)); for (j in 1:80) dp[[paste0("RW",j)]] <- rep(1,20)
  pd <- rc2_replicate_design(dp,"PISA",2025)
  add("PISA80_Fayfactor",pd$n==80&&pd$factor==1/20)
  dp$RW80 <- NULL
  add("PISA79_rejected",inherits(try(rc2_replicate_design(dp,"PISA",2025),silent=TRUE),"try-error"))
  add("bind_handles_empty",nrow(rc2_bind(list(data.frame(),data.frame(x=1),data.frame(y=2))))==2)
  add("ISCED_244_is_2",identical(rc2_isced(c(244,254,344,354)),c(2,2,3,3)))
  ml <- rc2_modal_mask(rep(c(2,3),each=60),rep(c("a","b"),each=60))
  add("modal_two_levels_retained",all(ml$mask)&&ml$levels=="2;3")
  add("modal_missing_not_full_sample",!any(rc2_modal_mask(rep(NA_real_,120),rep("a",120))$mask))
  rc2_bind(results)
}

# =============================================================================
# INPUTS: inspected headers, exact file identities and safe extraction.
# =============================================================================
rc2_log <- function(...) {
  s <- paste0(...,collapse=""); cat(s,"\n",sep="")
  if (exists("RC2_LOG",inherits=TRUE)&&nzchar(RC2_LOG)) cat(s,"\n",file=RC2_LOG,append=TRUE,sep="")
}
rc2_package <- function(p) {
  if (!requireNamespace(p,quietly=TRUE)) {
    rc2_log("Installing required R package: ",p)
    install.packages(p,repos="https://cloud.r-project.org")
  }
  if (!requireNamespace(p,quietly=TRUE)) stop("Package unavailable: ",p)
}
rc2_zip_index <- function(p) {
  x <- suppressWarnings(utils::unzip(p,list=TRUE))
  if (!is.data.frame(x)||!nrow(x)) stop("Invalid/empty ZIP: ",p)
  if (any(grepl("(^|[/\\\\])\\.\\.([/\\\\]|$)|^[/\\\\]|^[A-Za-z]:",x$Name)))
    stop("Unsafe ZIP member path: ",p)
  x
}
rc2_extract <- function(p,member,dir,bytes) {
  dir.create(dir,recursive=TRUE,showWarnings=FALSE)
  dest <- file.path(dir,basename(member))
  valid <- function() file.exists(dest)&&is.finite(file.info(dest)$size)&&
    file.info(dest)$size==bytes&&bytes>0
  if (valid()) return(dest)
  # Only these newly generated scratch files may be replaced. Source ZIPs remain unchanged.
  if (file.exists(dest)) file.rename(dest,paste0(dest,".incomplete_",format(Sys.time(),"%H%M%S")))
  try(suppressWarnings(utils::unzip(p,files=member,exdir=dir,junkpaths=TRUE)),silent=TRUE)
  if (valid()) return(dest)
  tar <- Sys.which("tar")
  if (nzchar(tar)) {
    tmp <- tempfile("tar_",tmpdir=dir); dir.create(tmp)
    try(suppressWarnings(system2(tar,c("-xf",shQuote(p),"-C",shQuote(tmp),shQuote(member)),
      stdout=TRUE,stderr=TRUE)),silent=TRUE)
    hits <- list.files(tmp,recursive=TRUE,full.names=TRUE)
    hits <- hits[tolower(basename(hits))==tolower(basename(member))]
    hits <- hits[file.info(hits)$size==bytes]
    if (length(hits)) file.copy(hits[1],dest,overwrite=TRUE)
    unlink(tmp,recursive=TRUE)
    if (valid()) return(dest)
  }
  if (!requireNamespace("archive",quietly=TRUE)) try(rc2_package("archive"),silent=TRUE)
  if (requireNamespace("archive",quietly=TRUE)) {
    tmp <- tempfile("archive_",tmpdir=dir); dir.create(tmp)
    try(archive::archive_extract(p,dir=tmp,files=member),silent=TRUE)
    hits <- list.files(tmp,recursive=TRUE,full.names=TRUE)
    hits <- hits[tolower(basename(hits))==tolower(basename(member))]
    hits <- hits[file.info(hits)$size==bytes]
    if (length(hits)) file.copy(hits[1],dest,overwrite=TRUE)
    unlink(tmp,recursive=TRUE)
    if (valid()) return(dest)
  }
  stop("Could not extract exact nonempty member: ",basename(p)," / ",member,
       ". The other years will still be processed; see input status.")
}
rc2_download <- function(url,dest,is_zip=TRUE) {
  if (file.exists(dest)) {
    if (!is_zip || !inherits(try(rc2_zip_index(dest),silent=TRUE),"try-error")) return(dest)
    stop("Existing source fails integrity check; not overwritten: ",dest)
  }
  dir.create(dirname(dest),recursive=TRUE,showWarnings=FALSE)
  tmp <- paste0(dest,".partial"); timeout_old <- getOption("timeout")
  on.exit(options(timeout=timeout_old),add=TRUE); options(timeout=max(3600,timeout_old))
  utils::download.file(url,tmp,mode="wb",quiet=FALSE,method="libcurl")
  if (!file.exists(tmp)||file.info(tmp)$size<50) stop("Empty download: ",url)
  if (is_zip) rc2_zip_index(tmp)
  if (!file.rename(tmp,dest)) stop("Could not finalize new source: ",dest)
  dest
}
rc2_header <- function(p) {
  ext <- tolower(tools::file_ext(p))
  d <- if(ext %in% c("sav","zsav")) haven::read_sav(p,n_max=1,user_na=FALSE) else
    if(ext=="sas7bdat") haven::read_sas(p,n_max=1) else stop("Header type unsupported: ",p)
  n <- names(d)
  data.frame(variable=n,upper=toupper(n),label=vapply(d,function(x) {
    a <- attr(x,"label",exact=TRUE); if(is.null(a))"" else as.character(a)[1]
  },character(1)),stringsAsFactors=FALSE)
}
rc2_read_selected <- function(p,vars) {
  if (!length(vars)) stop("No selected columns: ",p)
  ext <- tolower(tools::file_ext(p))
  d <- if(ext %in% c("sav","zsav")) haven::read_sav(p,col_select=tidyselect::any_of(vars),user_na=FALSE) else
    haven::read_sas(p,col_select=tidyselect::any_of(vars))
  d <- as.data.frame(d); names(d) <- toupper(names(d)); d
}
rc2_choose <- function(n,candidates,required=TRUE) {
  z <- candidates[candidates %in% n]
  if (!length(z)) { if(required)stop("Missing column: ",paste(candidates,collapse="/")); return(NA_character_) }
  z[1]
}
rc2_pv_names <- function(n,survey,domain,year) {
  suf <- switch(domain,mathematics="MATH",science="SCIE",reading="READ",stop("Unknown domain"))
  pat <- if(survey=="PISA")paste0("^PV[0-9]+",suf,"$") else
    if(domain=="mathematics")"^ASMMAT0[1-5]$" else "^ASSSCI0[1-5]$"
  z <- grep(pat,n,value=TRUE)
  expected <- if(survey=="PISA"&&year>=2015L)10L else 5L
  if (length(z)!=expected) return(character())
  # Explicit numeric ordering, not the historical suffix-only READ detector.
  k <- if(survey=="PISA")as.integer(sub("^PV([0-9]+).*$","\\1",z)) else
    as.integer(sub(".*0([1-5])$","\\1",z))
  if (!identical(sort(k),seq_len(expected))) return(character())
  z[order(k)]
}
rc2_books_var <- function(h) {
  # A name is not enough: check the variable label before assuming books-at-home.
  j <- grepl("BOOKS.*(HOME|HOUSE)|HOW MANY BOOKS",toupper(h$label)) &
    !grepl("ELECTRONIC|DIGITAL|E-BOOK|CHILDREN.S|CHILD.S|OWN BOOK",toupper(h$label))
  hit <- h$upper[j]
  prefer <- intersect(c("ASBGBOOK","ASBG04","ASBG05","ASBG06"),hit)
  if(length(prefer)==1L)return(prefer)
  if(length(hit)==1L)return(hit)
  NA_character_
}
rc2_books <- function(x) {
  v <- rc2_num(x); labs <- attr(x,"labels",exact=TRUE)
  if (is.null(labs)||!length(labs))
    stop("Books-at-home value labels absent; do not guess category ordering")
  t <- toupper(names(labs)); t <- gsub("[\u2013\u2014\u2212]","-",t)
  g <- rep(NA_integer_,length(t))
  g[grepl("0[ -]*10|0 TO 10|NONE OR VERY FEW",t)] <- 1L
  g[grepl("11[ -]*25|11 TO 25",t)] <- 2L
  g[grepl("26[ -]*100|26 TO 100",t)] <- 3L
  g[grepl("101[ -]*200|101 TO 200",t)] <- 4L
  g[grepl("MORE THAN 200|OVER 200|> *200|201 OR MORE|200[[:space:]]*\\+",t)] <- 5L
  good <- !is.na(g)
  if (sum(good)!=5L||length(unique(g[good]))!=5L)
    stop("Books-at-home labels do not establish the common five categories")
  mp <- setNames(g[good],as.character(unname(labs[good])))
  as.numeric(mp[as.character(v)])
}
rc2_dictionary <- function(d) {
  rc2_bind(lapply(names(d),function(n) {
    x <- d[[n]]; a <- attr(x,"label",exact=TRUE); b <- attr(x,"labels",exact=TRUE)
    data.frame(variable=n,label=if(is.null(a))"" else as.character(a)[1],
      value_labels=if(is.null(b))"" else paste(names(b),unname(b),sep="=",collapse=" | "))
  }))
}
rc2_pair_plan <- function() {
  data.frame(pair_id=c("T2003_P2009","T2007_P2012","T2011_P2015","T2011_P2018_ROBUST",
    "T2015_P2022_WIDE","T2019_P2025","T2023_P2025_CURRENT"),
    timss_year=c(2003L,2007L,2011L,2011L,2015L,2019L,2023L),
    pisa_year=c(2009L,2012L,2015L,2018L,2022L,2025L,2025L),
    role=c("main_timing_candidate","main_timing_candidate","main_timing_candidate",
           "robustness","wide_timing_robustness","main_timing_candidate","current_system_only"),
    include_fixed_main=c(TRUE,TRUE,TRUE,FALSE,FALSE,TRUE,FALSE),
    note=c(rep("Repeated cross-sections; empirical age-distance must be reviewed",3),
      "Pre-specified alternative for TIMSS 2011; not selected by outcomes",
      "Seven-year spacing after pandemic-related PISA postponement; not a close-cohort claim",
      "Six-year spacing; empirical ages required",
      "Two-year spacing; never a cohort comparison"),stringsAsFactors=FALSE)
}

# FWF import: retain original character IDs; never rename columns by position.
rc2_fwf <- function(datafile,control,vars_pattern) {
  # Reuse the fixed-width strategy that already produced the validated RC1
  # 2006/2012 extracts. Unselected fields remain signed skip-widths, so column
  # positions cannot drift when the OECD SAS INPUT file contains gap rows.
  rc2_package("SAScii")
  setup <- tryCatch(SAScii::parse.SAScii(control),error=function(e) {
    ln <- readLines(control,warn=FALSE,encoding="UTF-8")
    k <- which(grepl("^\\s*INPUT\\s*$",toupper(ln)))
    if(!length(k))stop(e)
    SAScii::parse.SAScii(control,beginline=k[1])
  })
  if(!is.data.frame(setup)||!all(c("varname","width","char","divisor") %in% names(setup)))
    stop("Unrecognized SAS setup schema: ",control)
  nm <- toupper(as.character(setup$varname))
  force_char <- grepl("^(CNT|COUNTRY|SCHOOLID|STIDSTD|CNTSCHID|CNTSTUID|SCHOOL_ID|STUDENT_ID)$",nm)
  ch <- as.logical(setup$char); ch[is.na(ch)] <- FALSE; ch[force_char] <- TRUE
  widths <- abs(as.numeric(setup$width))
  named <- !is.na(nm)&nzchar(nm)
  keep <- named&grepl(vars_pattern,nm)
  if(!any(keep))stop("No requested columns found in SAS setup")
  widths[!keep] <- -widths[!keep]
  if(any(!is.finite(widths))||any(widths==0))stop("Invalid fixed-width structure")
  kept <- which(keep)
  rules <- rc2_control_rules(control,nm[kept])
  d <- utils::read.fwf(file=datafile,widths=widths,col.names=nm[kept],
    colClasses="character",comment.char="",strip.white=FALSE,buffersize=2000)
  for(j in seq_along(kept)) {
    rr <- kept[j]
    raw <- trimws(as.character(d[[j]]))
    rule <- rules[[nm[rr]]]
    if(ch[rr]) {
      raw[raw %in% c("",".")] <- NA_character_
      d[[j]] <- raw
    } else {
      div <- suppressWarnings(as.numeric(setup$divisor[rr]))
      d[[j]] <- rc2_decode_field(raw,div,rule$missing)
    }
    if(length(rule$labels))attr(d[[j]],"labels") <- rule$labels
  }
  names(d) <- toupper(names(d))
  d
}

# =============================================================================
# SOURCE DISCOVERY. Existing inputs first; only new RC2 paths are written.
# =============================================================================
rc2_inventory <- function(downloads,root) {
  ff <- unique(c(list.files(downloads,recursive=TRUE,full.names=TRUE),
                 if(!startsWith(rc2_norm(root),paste0(rc2_norm(downloads),"/")))
                   list.files(root,recursive=TRUE,full.names=TRUE) else character()))
  fi <- file.info(ff); ff <- ff[!is.na(fi$isdir)&!fi$isdir]
  # Do not reuse derived caches, extracted handoff copies, or partial downloads as raw sources.
  excluded <- grepl("/RUNNER/|/99_archive/|/20_rc2_domains/(runs|cache|extracts)/|/rc2_work/|\\.partial$|\\.crdownload$",
    gsub("\\\\","/",ff),ignore.case=TRUE)
  ff <- ff[!excluded]
  data.frame(path=rc2_norm(ff),basename=basename(ff),bytes=as.numeric(file.info(ff)$size),
    extension=tolower(tools::file_ext(ff)),stringsAsFactors=FALSE)
}
rc2_pick_file <- function(inv,pattern) {
  z <- inv[grepl(pattern,inv$basename,ignore.case=TRUE,perl=TRUE)&inv$bytes>0,,drop=FALSE]
  if(!nrow(z))return("")
  # Duplicate filenames with identical payloads are interchangeable; divergent sources are not.
  z <- z[order(z$path),,drop=FALSE]
  hh <- vapply(z$path,rc2_sha,character(1))
  if(length(unique(hh))>1L)stop("Multiple different sources match ",pattern,"; see source inventory")
  z$path[1]
}
rc2_pisa_official <- function(year) {
  # Keep both the long-standing OECD /pisa/pisaproducts URL and the newer
  # content/dam location. The old filenames are independently documented by
  # OECD/EdSurvey workflows and are the same files used by prior PISA code.
  if(year==2003L)return(list(
    data_name="INT_stui_2003_v2.zip",
    data_urls=c(
      "https://www.oecd.org/pisa/pisaproducts/INT_stui_2003_v2.zip",
      "https://www.oecd.org/content/dam/oecd/en/data/datasets/pisa/pisa-2003-datasets/data-sets-in-txt-formats/INT_stui_2003_v2.zip"),
    control_name="PISA2003_SAS_student.sas",
    control_urls=c(
      "https://www.oecd.org/pisa/pisaproducts/PISA2003_SAS_student.sas",
      "https://www.oecd.org/content/dam/oecd/en/data/datasets/pisa/pisa-2003-datasets/sas-and-spss-control-files/PISA2003_SAS_student.sas")))
  if(year==2009L)return(list(
    data_name="INT_STQ09_DEC11.zip",
    data_urls=c(
      "https://www.oecd.org/pisa/pisaproducts/INT_STQ09_DEC11.zip",
      "https://www.oecd.org/content/dam/oecd/en/data/datasets/pisa/pisa-2009-datasets/data-sets-in-txt-format/INT_STQ09_DEC11.zip"),
    control_name="PISA2009_SAS_student.sas",
    control_urls=c(
      "https://www.oecd.org/pisa/pisaproducts/PISA2009_SAS_student.sas",
      "https://www.oecd.org/content/dam/oecd/en/data/datasets/pisa/pisa-2009-datasets/sas-and-spss-control-files/PISA2009_SAS_student.sas")))
  NULL
}
rc2_download_any <- function(urls,dest,is_zip=TRUE) {
  if(file.exists(dest))return(rc2_download(urls[1],dest,is_zip))
  errs <- character()
  for(u in unique(urls)) {
    z <- tryCatch({rc2_download(u,dest,is_zip); TRUE},error=function(e) {
      errs <<- c(errs,paste0(u," => ",conditionMessage(e)))
      tmp <- paste0(dest,".partial"); if(file.exists(tmp))unlink(tmp,force=TRUE)
      FALSE
    })
    if(isTRUE(z))return(dest)
  }
  stop("All official download locations failed for ",basename(dest),": ",paste(errs,collapse=" | "))
}
rc2_pisa_member_scores <- function(year,zl) {
  nm <- toupper(gsub("\\\\","/",as.character(zl$Name)))
  bn <- basename(nm); len <- suppressWarnings(as.numeric(zl$Length))
  score <- rep(-Inf,length(nm))
  if(year<=2012L) {
    ok <- grepl("\\.(TXT|DAT)$",bn)
    score[ok] <- log1p(pmax(0,len[ok]))
    tag <- switch(as.character(year),
      `2003`="INT_STUI_2003",`2006`="INT_STU06",`2009`="INT_STQ09",`2012`="INT_STU12")
    score[ok&grepl(tag,bn,fixed=TRUE)] <- score[ok&grepl(tag,bn,fixed=TRUE)] + 10000
  } else {
    ok <- grepl("\\.(SAV|SAS7BDAT)$",bn)&grepl("STU",bn)&
      !grepl("COG|TIM|TTM|QMC|VNM|TCH|SCH|FLT|CPS",bn)
    score[ok] <- log1p(pmax(0,len[ok])) + 1000
    score[ok&grepl("STU_QQQ",bn,fixed=TRUE)] <- score[ok&grepl("STU_QQQ",bn,fixed=TRUE)] + 10000
    score[ok&grepl("CMB_STU_QQQ",bn,fixed=TRUE)] <- score[ok&grepl("CMB_STU_QQQ",bn,fixed=TRUE)] + 10000
    score[ok&grepl("QQ2",bn,fixed=TRUE)] <- score[ok&grepl("QQ2",bn,fixed=TRUE)] - 20000
  }
  score
}
rc2_pick_pisa_member <- function(year,zl) {
  sc <- rc2_pisa_member_scores(year,zl)
  if(!length(sc)||!any(is.finite(sc)))stop("PISA ",year,": no usable student member in archive")
  k <- which.max(sc)
  if(!is.finite(sc[k]))stop("PISA ",year,": no usable student member in archive")
  zl[k,,drop=FALSE]
}
rc2_pisa_source <- function(year,inv,extract_root) {
  suffix <- "(?:\\s*\\(\\d+\\))?"
  patterns <- switch(as.character(year),
    `2003`=c(paste0("^INT_STUI_2003_V2",suffix,"\\.zip$"),
      "^INT_STUI_2003.*\\.(zip|txt)$","^PISA.?2003.*STU.*\\.(sav|sas7bdat|zip)$"),
    `2006`=c("^INT_STU06.*\\.(zip|txt)$","^PISA.?2006.*STU.*\\.(sav|sas7bdat|zip)$"),
    `2009`=c(paste0("^INT_STQ09_DEC11",suffix,"\\.zip$"),
      "^INT_STQ09.*\\.(zip|txt)$","^PISA.?2009.*STU.*\\.(sav|sas7bdat|zip)$"),
    `2012`=c("^INT_STU12.*\\.(zip|txt)$","^PISA.?2012.*STU.*\\.(sav|sas7bdat|zip)$"),
    `2015`=c(paste0("^(PUF_)?SPSS_COMBINED_CMB_STU_QQQ",suffix,"\\.zip$"),
      "^CY6.*CMB_STU_QQQ\\.sav$",paste0("^(PUF_)?SAS_COMBINED_CMB_STU_QQQ",suffix,"\\.zip$")),
    `2018`=c(paste0("^SPSS_STU_QQQ",suffix,"\\.zip$"),"^CY07.*STU_QQQ\\.sav$",
      paste0("^SAS_STU_QQQ",suffix,"\\.zip$")),
    `2022`=c(paste0("^STU_QQQ_SPSS",suffix,"\\.zip$"),"^CY08.*STU_QQQ\\.sav$",
      paste0("^STU_QQQ_SAS",suffix,"\\.zip$")),
    `2025`=c(paste0("^CY09_MS_STU_PUF",suffix,"\\.sav$"),
      paste0("^CY09_MS_STU_PUF",suffix,"\\.zip$")))
  p <- ""
  for(pat in patterns){p <- rc2_pick_file(inv,pat); if(nzchar(p))break}
  allow <- isTRUE(getOption("pisa.rc2.download",TRUE))
  off <- rc2_pisa_official(year)
  sources_dir <- file.path(dirname(extract_root),"sources")
  if(!nzchar(p)&&!is.null(off)&&allow) {
    dir.create(sources_dir,recursive=TRUE,showWarnings=FALSE)
    p <- file.path(sources_dir,off$data_name)
    rc2_log("PISA ",year,": exact local student PUF absent; downloading official OECD archive ",off$data_name)
    rc2_download_any(off$data_urls,p,TRUE)
  }
  if(!nzchar(p))stop("PISA ",year,": no full local student source found. Official source: ",
    "https://www.oecd.org/en/data/datasets/pisa-",year,"-database.html")
  source <- p; member <- ""; hash <- rc2_sha(source)
  if(tolower(tools::file_ext(p))=="zip") {
    zl <- rc2_zip_index(p)
    z <- rc2_pick_pisa_member(year,zl)
    member <- z$Name[1]
    p <- rc2_extract(source,member,file.path(extract_root,paste0("PISA_",year,"_",substr(hash,1,12))),z$Length[1])
  }
  control <- ""
  if(tolower(tools::file_ext(p)) %in% c("txt","dat")) {
    control <- rc2_pick_file(inv,paste0("^PISA",year,".*SAS.*STUDENT.*\\.sas$"))
    if(!nzchar(control))control <- rc2_pick_file(inv,paste0("^PISA",year,".*STUDENT.*\\.sas$"))
    if(!nzchar(control)&&!is.null(off)&&allow) {
      dir.create(sources_dir,recursive=TRUE,showWarnings=FALSE)
      control <- file.path(sources_dir,off$control_name)
      rc2_log("PISA ",year,": SAS control file absent; downloading official OECD control ",off$control_name)
      rc2_download_any(off$control_urls,control,FALSE)
    }
    if(!nzchar(control)||!file.exists(control))
      stop("PISA ",year,": SAS INPUT control file missing for historical ASCII source")
  }
  list(path=p,source_path=source,member=member,source_sha256=hash,control=control,
       input_key=digest::digest(c(hash,if(nzchar(control))rc2_sha(control) else "",RC2_VERSION,rc2_compute_sha),algo="sha256"))
}
rc2_timss_sources <- function(year,inv,sources_dir,extract_root,allow_download) {
  cyc <- c(`1995`=1L,`2003`=3L,`2007`=4L,`2011`=5L,`2015`=6L,`2019`=7L,`2023`=8L)[as.character(year)]
  pat <- paste0("^AS[GA][A-Z0-9]{3}M",cyc,"\\.SAV$")
  direct <- inv[inv$extension=="sav" & grepl(pat,toupper(inv$basename)),,drop=FALSE]
  records <- list()
  if(nrow(direct)) for(i in seq_len(nrow(direct))) records[[length(records)+1L]] <- data.frame(
    year=year,source_country_code=substr(toupper(direct$basename[i]),4,6),
    role=substr(toupper(direct$basename[i]),3,3),path=direct$path[i],
    source_path=direct$path[i],member="",source_sha256=rc2_sha(direct$path[i]),stringsAsFactors=FALSE)
  zz <- inv$path[inv$extension=="zip" &
    (grepl(paste0("TIMSS.?",year),inv$basename,ignore.case=TRUE)|
     grepl(paste0("^T",substr(year,3,4),"_.*SPSS"),inv$basename,ignore.case=TRUE)) &
    !grepl("G8|GRADE.?8|LONGITUDINAL|HANDOFF|RC1|RC2|ADVANCED",inv$basename,ignore.case=TRUE)]
  for(zp in zz) {
    idx <- tryCatch(rc2_zip_index(zp),error=function(e)NULL); if(is.null(idx))next
    idx <- idx[grepl(pat,toupper(basename(idx$Name))),,drop=FALSE]
    if(!nrow(idx))next
    sha <- rc2_sha(zp)
    for(i in seq_len(nrow(idx))) {
      f <- rc2_extract(zp,idx$Name[i],file.path(extract_root,paste0("TIMSS_",year,"_",substr(sha,1,12))),idx$Length[i])
      b <- toupper(basename(f))
      records[[length(records)+1L]] <- data.frame(year=year,source_country_code=substr(b,4,6),
        role=substr(b,3,3),path=f,source_path=zp,member=idx$Name[i],source_sha256=sha,stringsAsFactors=FALSE)
    }
  }
  rec <- rc2_bind(records)
  if((!nrow(rec)||!any(rec$role=="G"))&&allow_download) {
    url <- paste0("https://www.iea.nl/sites/default/files/data-repository/TIMSS/TIMSS",year,
      "/TIMSS",year,"_IDB_SPSS_G4.zip")
    rc2_log("No usable local TIMSS ",year," G4 source; downloading only this archive from IEA.")
    dest <- file.path(sources_dir,basename(url)); rc2_download(url,dest)
    extra <- data.frame(path=dest,basename=basename(dest),bytes=file.info(dest)$size,extension="zip")
    return(rc2_timss_sources(year,rc2_bind(list(inv,extra)),sources_dir,extract_root,FALSE))
  }
  if(!nrow(rec))stop("No TIMSS ",year," Grade-4 main files available")
  rec$payload_sha256 <- vapply(rec$path,rc2_sha,character(1))
  # No extraction-order or latest-mtime selection of conflicting versions.
  k <- paste(rec$source_country_code,rec$role)
  bad <- names(Filter(function(x)length(unique(x))>1L,split(rec$payload_sha256,k)))
  rec$source_conflict <- k %in% bad
  rec <- rec[!duplicated(paste(k,rec$payload_sha256)),,drop=FALSE]
  rec
}

# =============================================================================
# CANONICAL RC2 EXTRACTS -- private, source-hash keyed, never exported as microdata.
# =============================================================================
rc2_canonical <- function(raw,survey,year,code) {
  n <- names(raw); N <- nrow(raw)
  getnum <- function(cands) {v <- rc2_choose(n,cands,FALSE); if(is.na(v))rep(NA_real_,N) else rc2_num(raw[[v]])}
  getchr <- function(cands) {v <- rc2_choose(n,cands,FALSE); if(is.na(v))rep(NA_character_,N) else rc2_chr(raw[[v]])}
  out <- data.frame(SCHOOL=getchr(if(survey=="PISA")c("SCHOOL_ID","CNTSCHID","SCHOOLID") else "IDSCHOOL"),
    STUDENT=getchr(if(survey=="PISA")c("STUDENT_ID","CNTSTUID","STIDSTD","STUDENTID") else c("IDSTUD","IDSTUDS")),
    W=getnum(if(survey=="PISA")"W_FSTUWT" else "TOTWGT"),
    AGE=getnum(if(survey=="PISA")"AGE" else c("ASDAGE","ASDGAGE","ASBGAGE","AGE")),
    GRADE=getnum(c("IDGRADE","GRADE")),stringsAsFactors=FALSE)
  gender <- rc2_gender_decode(raw,survey,year)
  out$GENDER <- gender$value
  cls <- getchr("IDCLASS"); validcl <- !is.na(out$SCHOOL)&nzchar(out$SCHOOL)&!is.na(cls)&nzchar(cls)
  out$CLASS <- NA_character_; out$CLASS[validcl] <- paste(out$SCHOOL[validcl],cls[validcl],sep="::")
  out$HAS_BOOKS_CATEGORIES <- survey=="TIMSS"
  isc_name <- rc2_choose(n,c("ISCEDL","ISCEDP"),FALSE)
  out$ISCED <- if(survey=="PISA"&&!is.na(isc_name))rc2_isced(raw[[isc_name]]) else NA_real_
  modal <- if(survey=="PISA")rc2_modal_mask(out$ISCED,out$SCHOOL) else
    list(mask=rep(FALSE,N),levels="",status="NOT_APPLICABLE_TIMSS")
  out$MODAL <- modal$mask
  ses_var <- "ESCS"; ses_status <- "AVAILABLE_ESCS"
  if(survey=="PISA") {
    out$SES <- getnum("ESCS")
    # Refuse rather than quietly using numeric nonresponse codes as high ESCS.
    if(any(is.finite(out$SES)&abs(out$SES)>10))stop("ESCS outside integrity range [-10,10]; coding review required")
    if(!any(is.finite(out$SES)))ses_status <- "ESCS_UNAVAILABLE"
    for(j in 1:80)out[[paste0("RW",j)]] <- getnum(c(paste0("RW",j),paste0("W_FSTR",j),paste0("W_FSTURWT",j)))
  } else {
    out$JKZONE <- getnum("JKZONE"); out$JKREP <- getnum("JKREP")
    h <- rc2_dictionary(raw); h$upper <- h$variable
    ses_var <- rc2_books_var(h)
    books <- if(is.na(ses_var))structure("Books variable unresolved",class="try-error") else
      try(rc2_books(raw[[ses_var]]),silent=TRUE)
    if(inherits(books,"try-error")) {
      out$SES <- NA_real_; ses_status <- paste0("HOLD_BOOKS_DEFINITION: ",as.character(books)[1])
      out$HAS_BOOKS_CATEGORIES <- FALSE
    } else {out$SES <- books; ses_status <- "LABEL_VERIFIED_FIVE_BOOK_CATEGORIES"}
  }
  for(dom in c(if(year==2003L&&survey=="PISA")"mathematics" else c("mathematics","science"),
                if(survey=="PISA"&&year>=2003L)"reading")) {
    pp <- rc2_pv_names(n,survey,dom,year)
    for(j in seq_along(pp))out[[paste0(switch(dom,mathematics="PV_MATH_",science="PV_SCIE_",reading="PV_READ_"),j)]] <- rc2_num(raw[[pp[j]]])
  }
  # Original rows are not overwritten. Any 1995 population selection is explicit.
  excluded <- 0L; rule <- "entire_source_reporting_unit"
  finite_grades <- sort(unique(out$GRADE[is.finite(out$GRADE)]))
  if(survey=="TIMSS"&&year==1995L&&identical(finite_grades,c(3,4))) {
    keep <- is.finite(out$GRADE)&out$GRADE==4; excluded <- sum(!keep)
    out <- out[keep,,drop=FALSE]; rule <- "1995_explicit_grade4_not_grade3"
  }
  finite_grades <- sort(unique(out$GRADE[is.finite(out$GRADE)]))
  age <- out$AGE[is.finite(out$AGE)]
  if(survey=="PISA") {
    pop <- "PISA_AGE_TARGET_UNRESTRICTED"
    if(length(age)&&mean(age>=14&age<=18)<.9)stop("PISA age integrity failed; no source-position remapping permitted")
  } else {
    pop <- if(length(finite_grades)==1L&&finite_grades==4)"G4_EXPLICIT" else
      if(!length(finite_grades))"G4_DATABASE_GRADE_UNVERIFIED" else "G4_DATABASE_NON4_OR_MIXED_REVIEW"
  }
  studentkey <- paste(out$SCHOOL,out$STUDENT,sep="::")
  validkey <- !is.na(out$SCHOOL)&nzchar(out$SCHOOL)&!is.na(out$STUDENT)&nzchar(out$STUDENT)
  if(anyDuplicated(studentkey[validkey]))stop("Duplicate school/student identifiers; cannot assume independent student rows")
  if(!all(validkey)) {
    # PISA population statistics use supplied replicate weights, not school IDs.
    # Permit no school IDs only with a verified country-wide CNTSTUID.
    b <- if("CNTSTUID" %in% names(raw))rc2_id_normalize(raw$CNTSTUID) else character()
    student_only <- survey=="PISA"&&all(is.na(out$SCHOOL)|!nzchar(out$SCHOOL))&&
      length(b)==nrow(out)&&all(!is.na(b)&nzchar(b))&&!anyDuplicated(b)&&
      identical(rc2_id_normalize(out$STUDENT),b)
    if(!student_only)stop("Incomplete or invalid school/student identifiers")
  }
  list(data=out,meta=list(survey=survey,year=year,source_country_code=code,
    n_original=N,n_selected=nrow(out),n_excluded_population=excluded,population_rule=rule,
    population_status=pop,observed_grades=paste(finite_grades,collapse=";"),
    ses_variable=if(is.na(ses_var))"" else ses_var,ses_status=ses_status,
    school_id_status=if(all(validkey))"SCHOOL_IDS_COMPLETE" else "SCHOOL_IDS_UNAVAILABLE_IN_SOURCE",
    age_status=if(length(age))"AGE_OBSERVED" else "AGE_UNAVAILABLE_IN_SOURCE",
    modal_levels=modal$levels,modal_status=modal$status,
    gender_variable=gender$variable,gender_status=gender$status,gender_map=gender$map))
}
rc2_id_text <- function(x) {
  if(inherits(x,"haven_labelled"))x <- unclass(x)
  if(is.numeric(x)) {
    y <- format(x,scientific=FALSE,trim=TRUE,digits=22)
    y[is.na(x)] <- NA_character_
  } else {
    y <- trimws(as.character(x)); y[is.na(x)] <- NA_character_
  }
  y
}
rc2_best_column <- function(d,candidates,required=TRUE) {
  hit <- candidates[candidates %in% names(d)]
  if(!length(hit)) {
    if(required)stop("Missing candidate column: ",paste(candidates,collapse="/"))
    return(NA_character_)
  }
  sc <- vapply(hit,function(n) {
    v <- rc2_id_text(d[[n]])
    sum(!is.na(v)&nzchar(v))
  },numeric(1))
  hit[which.max(sc)]
}
rc2_rc1_design_cache <- function(root,year) {
  p <- file.path(root,"15_rc1_pisa_normalised","standardised_extracts",
    paste0("PISA_",year,"_RC1_STANDARDISED.rds"))
  if(file.exists(p))p else ""
}
# V3 import rules: obtain missing codes from the actual local OECD SAS control.
# No numeric range is silently recoded as missing. Unknown outliers stay a HOLD.
rc2_missing_label <- function(labels) {
  z <- toupper(trimws(labels))
  grepl("MISSING|NOT APPLICABLE|NOT ADMINISTERED|INVALID|NO RESPONSE|OMITTED|VALID SKIP",z) |
    z %in% c("N/A","N.A.","N.A","NA","NOT AVAILABLE","MISS")
}
# This is a deliberately narrow reader of the numeric ARRAY/DO missing-value
# idiom in the actual OECD controls, not an interpreter of arbitrary SAS code.
# A rule is accepted only for a declared list, its full 1..dimension loop, and
# an unconditional equality/OR-of-equalities mapping to SAS numeric missing.
# Conditional, partial-loop, range/list expansion and character recodes refuse
# interpretation when they concern a selected variable.
rc2_sas_array_rules <- function(txt,variables) {
  matches <- function(p,s)regmatches(s,gregexpr(p,s,perl=TRUE))[[1]]
  captures <- function(p,s)regmatches(s,regexec(p,s,perl=TRUE))[[1]]
  ans <- setNames(vector("list",length(variables)),variables)
  declarations <- matches("(?is)\\bARRAY\\s+[A-Z_][A-Z0-9_]*\\s*\\(\\s*[0-9]+\\s*\\)\\s*[^;]+;",txt)
  for(b in declarations) {
    g <- captures("(?is)^ARRAY\\s+([A-Z_][A-Z0-9_]*)\\s*\\(\\s*([0-9]+)\\s*\\)\\s*(.*);$",trimws(b))
    if(length(g)!=4L)next
    body <- trimws(g[4]); vv <- toupper(strsplit(body,"[[:space:]]+")[[1]])
    selected <- intersect(variables,vv)
    if(!length(selected))next
    # The supplied 2009 syntax repeats three entries in miss4(48). Mapping to
    # missing is idempotent, so repeated variable names do not alter the rule.
    if(any(!grepl("^[A-Z_][A-Z0-9_]*$",vv))||length(vv)!=as.integer(g[3]))
      stop("Unsupported SAS ARRAY declaration for selected variables: ",g[2])
    # The source controls put the full DO loop immediately after the declaration.
    pos <- regexpr(b,txt,fixed=TRUE)[1]; after <- substring(txt,pos+nchar(b))
    loop <- captures("(?is)^\\s*DO\\s+([A-Z_][A-Z0-9_]*)\\s*=\\s*1\\s+TO\\s+([0-9]+)\\s*;(.*?)\\bEND\\s*;",after)
    if(length(loop)!=4L||as.integer(loop[3])!=as.integer(g[3]))
      stop("No complete SAS ARRAY loop for selected variables: ",g[2])
    ref <- paste0(toupper(g[2]),"\\s*\\{\\s*",toupper(loop[2]),"\\s*\\}")
    rules <- numeric()
    statements <- strsplit(loop[4],";",fixed=TRUE)[[1]]
    for(st in statements) {
      st <- trimws(st);if(!nzchar(st))next
      pat <- paste0("(?is)^IF\\s+(.*?)\\s+THEN\\s+",ref,"\\s*=\\s*\\.[A-Z_]?\\s*$")
      q <- captures(pat,st)
      if(length(q)!=2L)stop("Unsupported SAS ARRAY rule: ",g[2],"; review source metadata")
      condition <- trimws(q[2])
      if(startsWith(condition,"(")&&endsWith(condition,")"))
        condition <- trimws(substring(condition,2,nchar(condition)-1))
      clauses <- strsplit(condition,"(?i)\\s+OR\\s+",perl=TRUE)[[1]]
      for(clause in clauses) {
        eq <- captures(paste0("(?is)^",ref,"\\s*(?:=|EQ)\\s*([-+]?[0-9]+(?:\\.[0-9]+)?|\\.[A-Z_]?)\\s*$"),trimws(clause))
        if(length(eq)!=2L)stop("Unsupported conditional SAS ARRAY rule: ",g[2])
        value <- suppressWarnings(as.numeric(eq[2]))
        if(is.finite(value))rules <- c(rules,value)
      }
    }
    for(n in selected)ans[[n]] <- unique(c(ans[[n]],rules))
  }
  ans
}
rc2_control_rules <- function(control, variables) {
  txt <- paste(readLines(control,warn=FALSE,encoding="UTF-8"),collapse="\n")
  txt <- gsub("(?s)/\\*.*?\\*/"," ",txt,perl=TRUE)
  matches <- function(pattern,text) regmatches(text,gregexpr(pattern,text,perl=TRUE))[[1]]
  captures <- function(pattern,text) regmatches(text,regexec(pattern,text,perl=TRUE))[[1]]
  formats <- list(); mappings <- list()
  for(b in matches("(?is)\\bVALUE\\s+\\$?[A-Z_][A-Z0-9_]*\\s+[^;]*;",txt)) {
    g <- captures("(?is)^VALUE\\s+(\\$?[A-Z_][A-Z0-9_]*)\\s+(.*);$",trimws(b))
    if(length(g)!=3L)next
    labs <- numeric()
    for(e in matches("[-+]?[0-9]+(?:\\.[0-9]+)?\\s*=\\s*(?:'[^']*'|\"[^\"]*\")",g[3])) {
      v <- captures("(?s)^([-+]?[0-9]+(?:\\.[0-9]+)?)\\s*=\\s*['\"](.*)['\"]$",e)
      if(length(v)==3L)labs <- c(labs,setNames(as.numeric(v[2]),v[3]))
    }
    formats[[toupper(g[2])]] <- labs
  }
  for(b in matches("(?is)\\bFORMAT\\s+[^;]*;",txt)) {
    b <- sub("(?is)^FORMAT\\s+","",b,perl=TRUE)
    for(e in matches("(?i)\\b[A-Z_][A-Z0-9_]*\\s+\\$?[A-Z_][A-Z0-9_]*\\.",b)) {
      v <- captures("(?i)^([A-Z_][A-Z0-9_]*)\\s+(\\$?[A-Z_][A-Z0-9_]*)\\.$",e)
      if(length(v)==3L)mappings[[toupper(v[2])]] <- toupper(v[3])
    }
  }
  arrays <- rc2_sas_array_rules(txt,variables)
  ans <- setNames(vector("list",length(variables)),variables)
  for(n in variables) {
    fmt <- mappings[[n]]; labs <- if(is.null(fmt))numeric() else formats[[fmt]]
    if(is.null(labs))labs <- numeric()
    missing <- c(unname(labs[rc2_missing_label(names(labs))]),arrays[[n]])
    # Explicit scalar SAS recodes, e.g. IF ESCS=9999 THEN ESCS=.;
    pat <- paste0("(?i)\\bIF\\s+",n,"\\s*(?:=|EQ)\\s*([-+]?[0-9]+(?:\\.[0-9]+)?)\\s+THEN\\s+",n,"\\s*=\\s*\\.[A-Z_]?\\s*;")
    for(e in matches(pat,txt)) {
      v <- captures(pat,e); if(length(v)==2L)missing <- c(missing,as.numeric(v[2]))
    }
    patin <- paste0("(?i)\\bIF\\s+",n,"\\s+IN\\s*\\(([^)]*)\\)\\s+THEN\\s+",n,"\\s*=\\s*\\.[A-Z_]?\\s*;")
    for(e in matches(patin,txt)) {
      v <- captures(patin,e)
      if(length(v)==2L&&grepl("^[0-9.,+ \\t\\r\\n-]+$",v[2]))
        missing <- c(missing,suppressWarnings(as.numeric(strsplit(trimws(v[2]),"[,[:space:]]+")[[1]])))
    }
    ans[[n]] <- list(labels=labs,missing=unique(missing[is.finite(missing)]),format=if(is.null(fmt))"" else fmt,
      array_missing=arrays[[n]])
  }
  ans
}
rc2_decode_field <- function(raw,divisor=1,missing=numeric()) {
  raw <- trimws(as.character(raw)); value <- suppressWarnings(as.numeric(raw))
  # SAS implied decimal applies per field, not to a whole mixed column.
  implicit <- !is.na(raw)&nzchar(raw)&!grepl("[.Ee]",raw)
  if(is.finite(divisor)&&divisor!=1)value[implicit] <- value[implicit]*divisor
  value[is.finite(value)&value %in% missing] <- NA_real_
  value
}
rc2_clean_labeled <- function(x) {
  labs <- attr(x,"labels",exact=TRUE)
  if(!is.null(labs)&&length(labs)) {
    miss <- unname(labs[rc2_missing_label(names(labs))])
    if(length(miss))x[!is.na(x)&x %in% miss] <- NA
  }
  x
}
rc2_id_normalize <- function(x) {
  y <- rc2_id_text(rc2_clean_labeled(x)); y[y %in% c("","NA","NaN",".")] <- NA_character_
  digits <- !is.na(y)&grepl("^[0-9]+(?:\\.0+)?$",y,perl=TRUE)
  y[digits] <- sub("\\.0+$","",y[digits])
  y[digits] <- sub("^0+(?=[0-9])","",y[digits],perl=TRUE)
  y
}
rc2_pisa_ids <- function(d,code) {
  sch <- intersect(c("CNTSCHID","SCHOOLID","SCHOOL_ID"),names(d))
  stu <- intersect(c("CNTSTUID","STIDSTD","STUDENTID","STUDENT_ID"),names(d))
  choices <- list(); best <- NULL; bestn <- -1L
  for(s in sch)for(t in stu) {
    a <- rc2_id_normalize(d[[s]]); b <- rc2_id_normalize(d[[t]])
    ok <- !is.na(a)&nzchar(a)&!is.na(b)&nzchar(b)
    key <- paste(a,b,sep="::"); dup <- sum(duplicated(key[ok]))
    choices[[length(choices)+1L]] <- data.frame(source_country_code=code,school_column=s,
      student_column=t,rows=nrow(d),valid_pairs=sum(ok),duplicate_pairs=dup)
    if(dup==0L&&sum(ok)>bestn){best <- list(school=a,student=b,school_column=s,student_column=t);bestn <- sum(ok)}
  }
  audit <- rc2_bind(choices)
  all_school_missing <- !length(sch)||all(vapply(sch,function(n)
    all(is.na(rc2_id_normalize(d[[n]]))),logical(1)))
  if(all_school_missing && "CNTSTUID" %in% names(d)) {
    b <- rc2_id_normalize(d$CNTSTUID)
    if(length(b)>0L&&all(!is.na(b)&nzchar(b))&&!anyDuplicated(b)) {
      audit <- rc2_bind(list(audit,data.frame(source_country_code=code,
        school_column="UNAVAILABLE",student_column="CNTSTUID",rows=nrow(d),
        valid_pairs=0L,duplicate_pairs=0L)))
      return(list(school=rep(NA_character_,nrow(d)),student=b,school_column="UNAVAILABLE",
        student_column="CNTSTUID",audit=audit,
        school_status="SCHOOL_IDS_UNAVAILABLE_IN_SOURCE",
        identity_rule="COUNTRY_WIDE_UNIQUE_CNTSTUID; NO_SCHOOL_IDS_CREATED"))
    }
  }
  if(is.null(best)||bestn==0L)stop("No nonempty unique school/student ID pair for ",code,
    "; inspect PISA variable profiles and ID candidates")
  best$audit <- audit
  best$school_status <- "SCHOOL_IDS_COMPLETE"
  best$identity_rule <- "UNIQUE_SCHOOL_STUDENT_PAIR"
  # Do not invent IDs or silently delete incomplete records.
  if(bestn<nrow(d))stop("Incomplete school/student IDs for ",code,": ",nrow(d)-bestn," of ",nrow(d)," rows; see profiles")
  best
}
rc2_pisa_profiles <- function(d,year) {
  cc <- rc2_choose(names(d),c("CNT","COUNTRY")); country <- toupper(rc2_chr(d[[cc]]))
  want <- intersect(c("CNTSCHID","SCHOOLID","SCHOOL_ID","CNTSTUID","STIDSTD","STUDENTID","STUDENT_ID","AGE","ESCS","W_FSTUWT"),names(d))
  rc2_bind(lapply(sort(unique(country)),function(code) {
    ii <- which(country==code)
    rc2_bind(lapply(want,function(n) {
      x <- d[[n]][ii]; v <- rc2_num(x); s <- rc2_chr(x); ok <- !is.na(s)&nzchar(s)
      isid <- grepl("ID",n); ff <- v[is.finite(v)]
      data.frame(year=year,source_country_code=code,variable=n,rows=length(ii),
        nonmissing=sum(ok),distinct=length(unique(s[ok])),
        minimum=if(length(ff)&&!isid)min(ff) else NA_real_,
        maximum=if(length(ff)&&!isid)max(ff) else NA_real_,
        outside_escs_range=if(n=="ESCS")sum(is.finite(v)&abs(v)>10) else NA_integer_,
        # Only SES outlier codes are exported, never individual IDs.
        escs_outlier_codes=if(n=="ESCS")paste(head(sort(unique(v[is.finite(v)&abs(v)>10])),20),collapse=";") else "")
    }))
  }))
}
rc2_prepare_pisa <- function(year,src,cache_root,outdir,root) {
  directory <- file.path(cache_root,"PISA",paste0(year,"_",substr(src$input_key,1,16)))
  index_path <- file.path(directory,"_INDEX.rds")
  if(file.exists(index_path)) {
    ix <- readRDS(index_path)
    if(identical(ix$input_key,src$input_key)&&all(file.exists(ix$tasks$path))&&rc2_pisa_index_valid(ix)) {
      for(n in names(ix$audits))rc2_csv(ix$audits[[n]],file.path(outdir,paste0("PISA_",year,"_",n,".csv")))
      return(list(tasks=ix$tasks,errors=ix$errors))
    }
  }
  # The original official source now supplies design and PVs together. Historical
  # RC1 caches are retained read-only; their names are not a validation certificate.
  pattern <- "^(CNT|COUNTRY|CNTSCHID|SCHOOLID|SCHOOL_ID|CNTSTUID|STIDSTD|STUDENTID|STUDENT_ID|AGE|ISCEDL|ISCEDP|ESCS|W_FSTUWT|W_FSTR[0-9]+|W_FSTURWT[0-9]+|PV[0-9]+MATH|PV[0-9]+SCIE|PV[0-9]+READ|ST004[A-Z0-9]*|ST03Q01|ST04Q01|IMMIG|ST022Q01TA|LANGTEST_COG|LANGTEST_QQQ|LANGTEST|LANGN|STLANG|COBN_[A-Z0-9]+)$"
  rc2_log("PISA ",year,": reading original official design, ESCS, IDs and domain PVs together")
  raw <- if(nzchar(src$control))rc2_fwf(src$path,src$control,pattern) else {
    h <- rc2_header(src$path);rc2_csv(h,file.path(outdir,paste0("PISA_",year,"_FULL_HEADER.csv")));rc2_read_selected(src$path,h$variable[grepl(pattern,h$upper)|h$variable%in%rc2_demo_candidates(h)])
  }
  raw <- as.data.frame(lapply(raw,rc2_clean_labeled),stringsAsFactors=FALSE)
  ccvar <- rc2_choose(names(raw),c("CNT","COUNTRY")); country <- toupper(rc2_chr(raw[[ccvar]]))
  if(any(is.na(country)|!grepl("^[A-Z0-9]{3}$",country)))stop("Invalid source country codes; no rows dropped")
  cc <- sort(unique(country)); if(!"NLD" %in% cc||length(cc)<10L)stop("PISA whole-study country integrity check failed")
  audits <- list(SELECTED_DICTIONARY=rc2_dictionary(raw),VARIABLE_PROFILES=rc2_pisa_profiles(raw,year))
  if(nzchar(src$control)) {
    control_copy <- file.path(outdir,paste0("PISA_",year,"_SOURCE_CONTROL.sas"))
    if(!file.exists(control_copy))file.copy(src$control,control_copy,overwrite=FALSE)
    if(!file.exists(control_copy)||rc2_sha(control_copy)!=rc2_sha(src$control))
      stop("SAS control provenance copy failed")
    rules <- rc2_control_rules(src$control,names(raw))
    audits$SAS_MISSING_RULES <- rc2_bind(lapply(names(rules),function(n)data.frame(variable=n,
      format=rules[[n]]$format,documented_missing_codes=paste(rules[[n]]$missing,collapse=";"),
      documented_array_missing_codes=paste(rules[[n]]$array_missing,collapse=";"))))
    # Retain exact metadata excerpts to diagnose an unrecognised SAS dialect.
    ln <- readLines(src$control,warn=FALSE); k <- grep("ESCS|MISSING",ln,ignore.case=TRUE)
    kk <- sort(unique(unlist(lapply(k,function(i)seq(max(1,i-2),min(length(ln),i+5))))))
    writeLines(paste(kk,ln[kk],sep=": "),file.path(outdir,paste0("PISA_",year,"_SAS_ESCS_EXCERPTS.txt")))
  }
  cp <- rc2_rc1_design_cache(root,year)
  audits$RC1_CACHE_POLICY <- data.frame(year=year,cache_path=cp,
    action="PRESERVED_READ_ONLY; RC2_FROM_ORIGINAL_OFFICIAL_SOURCE",cache_reused=FALSE)
  for(n in names(audits))rc2_csv(audits[[n]],file.path(outdir,paste0("PISA_",year,"_",n,".csv")))
  tasks <- errors <- choices <- list()
  for(code in cc) {
    ans <- tryCatch({
      dd <- rc2_subset_labels(raw,country==code)
      ids <- rc2_pisa_ids(dd,code);choices[[length(choices)+1L]] <- ids$audit
      dd$SCHOOL_ID <- ids$school;dd$STUDENT_ID <- ids$student
      obj <- rc2_canonical(dd,"PISA",year,code)
      attr(obj,"selected_raw") <- NULL
      obj <- rc2_add_demographics(obj,dd,"PISA",year,code,outdir)
      # Validate the design now, before marking a source READY.
      rc2_replicate_design(obj$data,"PISA",year)
      domains <- if(year==2003L)"mathematics" else c("mathematics","science")
      # Reading is a NEW gender supplement only; RC1 reading outcomes are never replaced.
      if(year>=2003L&&length(rc2_pv_names(names(dd),"PISA","reading",year)))domains <- c(domains,"reading")
      for(dom in domains)if(!length(rc2_pv_names(names(dd),"PISA",dom,year)))stop("Missing required ",dom," plausible values")
      obj$meta$source_sha256 <- src$source_sha256;obj$meta$source_member <- src$member
      obj$meta$source_path <- src$source_path;obj$meta$design_source <- "original_official_PUF_V6"
      obj$meta$school_column <- ids$school_column;obj$meta$student_column <- ids$student_column
      obj$meta$identity_rule <- ids$identity_rule
      obj$input_key <- src$input_key
      dest <- file.path(directory,paste0(code,".rds"));rc2_save(obj,dest)
      rc2_bind(lapply(domains,function(dom)data.frame(survey="PISA",year=year,
        source_country_code=code,domain=dom,path=dest,input_key=src$input_key)))
    },error=function(e)e)
    if(inherits(ans,"error")) {
      rc2_log("INPUT HOLD PISA ",year," ",code,": ",conditionMessage(ans))
      errors[[length(errors)+1L]] <- data.frame(survey="PISA",year=year,source_country_code=code,
        status="INPUT_HOLD",reason=conditionMessage(ans))
    } else tasks[[length(tasks)+1L]] <- ans
  }
  audits$ID_CANDIDATES <- rc2_bind(choices)
  rc2_csv(audits$ID_CANDIDATES,file.path(outdir,paste0("PISA_",year,"_ID_CANDIDATES.csv")))
  result <- list(tasks=rc2_bind(tasks),errors=rc2_bind(errors))
  rc2_save(c(list(input_key=src$input_key,audits=audits,canonical_hashes=rc2_file_manifest(unique(result$tasks$path))),result),index_path)
  result
}

rc2_prepare_timss <- function(rec,cache_root,outdir) {
  tasks <- list(); errors <- list()
  for(code in sort(unique(rec$source_country_code))) {
    z <- rec[rec$source_country_code==code,,drop=FALSE]; year <- z$year[1]
    ans <- tryCatch({
      if(any(z$source_conflict))stop("Conflicting source versions; not selected by mtime or extraction order")
      g <- z[z$role=="G",,drop=FALSE]; a <- z[z$role=="A",,drop=FALSE]
      if(nrow(g)!=1L)stop("Exactly one ASG background/main file required")
      ik <- digest::digest(c(sort(z$payload_sha256),RC2_VERSION,rc2_compute_sha),algo="sha256")
      dest <- file.path(cache_root,"TIMSS",paste0(year,"_",code,"_",substr(ik,1,16),".rds"))
      if(!file.exists(dest)) {
        h <- rc2_header(g$path); bv <- rc2_books_var(h)
        keep <- h$upper %in% c("IDCNTRY","IDSCHOOL","IDCLASS","IDSTUD","IDSTUDS","TOTWGT","JKZONE","JKREP",
          "ASDAGE","ASDGAGE","ASBGAGE","AGE","IDGRADE","GRADE","ITSEX","ASBG01",bv) |
          grepl("^(ASMMAT|ASSSCI)0[1-5]$",h$upper)
        raw <- rc2_read_selected(g$path,h$variable[keep])
        missing_pv <- !length(rc2_pv_names(names(raw),"TIMSS","mathematics",year)) ||
          !length(rc2_pv_names(names(raw),"TIMSS","science",year))
        if(missing_pv&&nrow(a)==1L) {
          ha <- rc2_header(a$path); want <- ha$upper %in% c("IDCNTRY","IDSCHOOL","IDCLASS","IDSTUD","IDSTUDS") |
            grepl("^(ASMMAT|ASSSCI)0[1-5]$",ha$upper)
          aa <- rc2_read_selected(a$path,ha$variable[want])
          keys <- intersect(c("IDCNTRY","IDSCHOOL","IDCLASS","IDSTUD","IDSTUDS"),intersect(names(raw),names(aa)))
          if(!any(c("IDSTUD","IDSTUDS") %in% keys))stop("No student-level key for ASG/ASA join")
          makekey <- function(x) {
            xx <- lapply(x[keys],rc2_chr)
            if(any(vapply(xx,function(v)any(is.na(v)|!nzchar(v)),logical(1))))stop("Missing ASG/ASA join keys")
            do.call(paste,c(xx,list(sep="::")))
          }
          kg <- makekey(raw); ka <- makekey(aa)
          if(anyDuplicated(kg)||anyDuplicated(ka))stop("Nonunique ASG/ASA keys")
          mm <- match(kg,ka); if(anyNA(mm)||length(ka)!=length(kg))stop("ASG/ASA join not one-to-one complete")
          for(v in setdiff(names(aa),names(raw)))raw[[v]] <- aa[[v]][mm]
        }
        dictionary <- rc2_dictionary(raw)
        rc2_csv(dictionary,file.path(outdir,paste0("TIMSS_",year,"_",code,"_DICTIONARY.csv")))
        obj <- rc2_canonical(raw,"TIMSS",year,code)
        obj$meta$source_sha256 <- paste(unique(z$source_sha256),collapse=";")
        obj$meta$source_path <- paste(unique(z$source_path),collapse=";")
        obj$meta$source_member <- paste(unique(z$member),collapse=";")
        obj$input_key <- ik; obj$dictionary <- dictionary; rc2_save(obj,dest)
      } else {
        obj <- readRDS(dest)
        if(!identical(obj$input_key,ik))stop("RC2 extract cache identity mismatch")
        rc2_csv(obj$dictionary,file.path(outdir,paste0("TIMSS_",year,"_",code,"_DICTIONARY.csv")))
      }
      rc2_bind(lapply(c("mathematics","science"),function(dom)data.frame(
        survey="TIMSS",year=year,source_country_code=code,domain=dom,path=dest,input_key=ik)))
    },error=function(e)e)
    if(inherits(ans,"error")) errors[[length(errors)+1L]] <- data.frame(survey="TIMSS",year=year,
      source_country_code=code,status="INPUT_HOLD",reason=conditionMessage(ans)) else
      tasks[[length(tasks)+1L]] <- ans
  }
  list(tasks=rc2_bind(tasks),errors=rc2_bind(errors))
}

# =============================================================================
# COUNTRY x WAVE x DOMAIN ESTIMATOR. Inference and all replicate counts retained.
# =============================================================================
rc2_worker <- function(task) {
  tryCatch({
    cp <- task$result_cache; token <- digest::digest(c(task$input_key,task$domain,rc2_compute_sha),algo="sha256")
    if(file.exists(cp)) {
      x <- readRDS(cp)
      if(identical(x$token,token)&&identical(x$status$task_status,"COMPUTED_PENDING_VALIDATION"))return(x)
    }
    obj <- rc2_read_canonical(task$path); d <- obj$data
    if(!is.null(task$mode))d$REPAIR_MODE<-task$mode
    if(!identical(obj$input_key,task$input_key))stop("Extract token mismatch")
    prefix <- switch(task$domain,mathematics="PV_MATH_",science="PV_SCIE_",reading="PV_READ_",stop("Unknown domain"))
    if(!"GENDER" %in% names(d))d$GENDER <- NA_character_
    M <- if(task$survey=="PISA"&&task$year>=2015L)10L else 5L
    pp <- paste0(prefix,seq_len(M))
    if(!all(pp %in% names(d)))stop("Not all required domain PVs are available: ",paste(setdiff(pp,names(d)),collapse=";"))
    if(any(vapply(d[pp],function(x)any(is.finite(x)&(x< -100|x>1200)),logical(1))))
      stop("PV integrity range failed; inspect missing-value coding")
    des <- rc2_replicate_design(d,task$survey,task$year); R <- des$n
    thresholds <- if(task$survey%in%c("TIMSS","PIRLS"))c(baseline=475,ge400=400,ge550=550,top=625) else
      if(task$domain=="mathematics")c(baseline=420.07,top=606.99) else
        if(task$domain=="reading")c(baseline=407.47,top=625.61) else c(baseline=409.54,top=633.33)
    if(task$domain=="reading")d$GENDER_ONLY <- !(task$survey=='PIRLS' && identical(task$mode,'full'))
    rc2_reset_math_cache()
    t0 <- rc2_tails_rank(d$SES,d$W)
    full <- do.call(rbind,lapply(pp,function(p)rc2_pv_stats(d[[p]],d,d$W,t0,thresholds)))
    K <- ncol(full); reps <- array(NA_real_,c(R,M,K))
    social_names <- c("social_rank_school_sorting_share","social_rank_classroom_sorting_share","social_raw_school_sorting_share",
      "social_rank_modal_school_sorting_share","social_raw_modal_school_sorting_share")
    need_social <- is.null(task$mode)||identical(task$mode,"full")
    tm <- if(need_social)rc2_tails_rank(d$SES,d$W*as.numeric(d$MODAL)) else NULL
    sf <- if(need_social)c(rc2_between(t0$rank,d$SCHOOL,d$W),rc2_between(t0$rank,d$CLASS,d$W),rc2_between(d$SES,d$SCHOOL,d$W),
      rc2_between(tm$rank,d$SCHOOL,d$W*as.numeric(d$MODAL)),rc2_between(d$SES,d$SCHOOL,d$W*as.numeric(d$MODAL))) else rep(NA_real_,5L)
    sr <- array(NA_real_,c(R,1,length(social_names)))
    rep_errors <- character(R)
    for(r in seq_len(R)) {
      er <- tryCatch({
        rc2_reset_weight_cache()
        wr <- rc2_repweight(des,r); tr <- rc2_tails_rank(d$SES,wr)
        for(m in seq_len(M))reps[r,m,] <- rc2_pv_stats(d[[pp[m]]],d,wr,tr,thresholds)
        if(need_social) {
        trm <- rc2_tails_rank(d$SES,wr*as.numeric(d$MODAL))
        sr[r,1,] <- c(rc2_between(tr$rank,d$SCHOOL,wr),rc2_between(tr$rank,d$CLASS,wr),rc2_between(d$SES,d$SCHOOL,wr),
          rc2_between(trm$rank,d$SCHOOL,wr*as.numeric(d$MODAL)),rc2_between(d$SES,d$SCHOOL,wr*as.numeric(d$MODAL)))
        }
        ""
      },error=function(e)conditionMessage(e))
      rep_errors[r] <- er
    }
    stats <- rc2_pool(full,reps,des$factor)
    socials <- if(need_social)rc2_pool(matrix(sf,nrow=1,dimnames=list(NULL,social_names)),sr,des$factor) else data.frame()
    stats <- if(!need_social || (task$domain=="reading" && !(task$survey=="PIRLS" && identical(task$mode,"full"))))stats else rc2_bind(list(stats,socials))
    stats$module <- ifelse(grepl("gender",stats$statistic),"gender_ses_supplement","domain_core")
    for(n in c("survey","year","source_country_code","domain"))stats[[n]] <- task[[n]]
    stats$unit <- rc2_stat_unit(stats$statistic)
    stats$population_status <- obj$meta$population_status
    stats$ses_definition <- if(task$survey=="PISA")"national_ESCS_fractional_weighted_quartiles" else
      "student_books5_fractional_weighted_quartiles"
    stats$variance_method <- des$method; stats$source_sha256 <- obj$meta$source_sha256
    stats$source_key <- task$input_key; stats$analysis_version <- RC2_VERSION
    stats$quality_status <- "PENDING_EXTERNAL_AND_POPULATION_REVIEW"
    stats$gender_definition <- "label_verified_source_binary_categories; not a measure of gender identity"
    stats$gender_support_min_n <- 30L
    stats$gender_support_min_effective_n <- 20L
    stats$source_limitation <- ""
    append_limitation <- function(mask,code) {
      stats$source_limitation[mask] <<- ifelse(nzchar(stats$source_limitation[mask]),
        paste(stats$source_limitation[mask],code,sep=";"),code)
    }
    no_school <- all(is.na(d$SCHOOL)|!nzchar(d$SCHOOL))
    no_ses <- !any(is.finite(d$SES)&is.finite(d$W)&d$W>0)
    if(no_school)append_limitation(grepl("school_sorting",stats$statistic),"SCHOOL_IDS_UNAVAILABLE_IN_SOURCE")
    if(no_ses)append_limitation(grepl("^(q1_|q4_|score_gap$|gap_|social_)|gender.*(q1|q4|ses)",stats$statistic),"SES_UNAVAILABLE_IN_SOURCE")
    if(!any(d$GENDER %in% c("girl","boy")))append_limitation(grepl("gender",stats$statistic),"GENDER_LABELS_UNAVAILABLE_OR_CONFLICTING")
    low <- grepl("gender",stats$statistic)&!is.finite(stats$estimate)&!nzchar(stats$source_limitation)
    append_limitation(low,"GENDER_GROUP_SUPPORT_BELOW_30_N_OR_20_NEFF_OR_OUTCOME_UNAVAILABLE")
    limited <- nzchar(stats$source_limitation)
    if(any(is.finite(stats$estimate[limited])|is.finite(stats$se[limited])))
      stop("Source-limited statistic incorrectly has a finite result")
    stats$inference_status[limited] <- "UNAVAILABLE_SOURCE_LIMITATION"
    stats$school_id_status <- if(no_school)"SCHOOL_IDS_UNAVAILABLE_IN_SOURCE" else "SCHOOL_IDS_COMPLETE"
    stats$age_status <- if(any(is.finite(d$AGE)))"AGE_OBSERVED" else "AGE_UNAVAILABLE_IN_SOURCE"
    stats$threshold <- NA_real_
    for(n in names(thresholds))stats$threshold[grepl(paste0("_",n,"$"),stats$statistic)] <- thresholds[n]
    positive <- is.finite(d$W)&d$W>0; validSES <- positive&is.finite(d$SES)
    ageok <- positive&is.finite(d$AGE)&d$AGE>=5&d$AGE<=25
    validSchools <- !is.na(d$SCHOOL)&nzchar(d$SCHOOL)
    diag <- data.frame(survey=task$survey,year=task$year,source_country_code=task$source_country_code,
      domain=task$domain,n_students=nrow(d),n_schools=length(unique(d$SCHOOL[positive&validSchools])),
      n_classes=length(unique(d$CLASS[positive&!is.na(d$CLASS)])),
      weighted_mean_age=rc2_weighted_mean(d$AGE[ageok],d$W[ageok]),
      age_nonmissing_n=sum(ageok),ses_nonmissing_weighted=if(any(positive))sum(d$W[validSES])/sum(d$W[positive]) else NA_real_,
      n_q1_positive=sum(positive&t0$q1>0),n_q4_positive=sum(positive&t0$q4>0),
      q1_fractional_share_among_valid=t0$share1,q4_fractional_share_among_valid=t0$share4,
      expected_pvs=M,expected_replicates=R,single_observed_jkrep_zones=des$single_zones,
      replicate_errors=sum(nzchar(rep_errors)),population_status=obj$meta$population_status,
      population_rule=obj$meta$population_rule,observed_grades=obj$meta$observed_grades,
      n_original=obj$meta$n_original,n_excluded_population=obj$meta$n_excluded_population,
      ses_variable=obj$meta$ses_variable,ses_status=obj$meta$ses_status,
      isced_nonmissing_n=sum(is.finite(d$ISCED)),modal_levels=obj$meta$modal_levels,
      modal_status=obj$meta$modal_status,
      school_id_status=if(no_school)"SCHOOL_IDS_UNAVAILABLE_IN_SOURCE" else "SCHOOL_IDS_COMPLETE",
      age_status=if(any(ageok))"AGE_OBSERVED" else "AGE_UNAVAILABLE_IN_SOURCE",
      modal_weighted_coverage=if(any(positive))sum(d$W[positive&d$MODAL])/sum(d$W[positive]) else NA_real_,
      school_nonmissing_weighted=if(any(positive))sum(d$W[positive&validSchools])/sum(d$W[positive]) else NA_real_,
      source_sha256=obj$meta$source_sha256,
      gender_variable=if(is.null(obj$meta$gender_variable))"" else obj$meta$gender_variable,
      gender_status=if(is.null(obj$meta$gender_status))"UNAVAILABLE" else obj$meta$gender_status,
      gender_map=if(is.null(obj$meta$gender_map))"" else obj$meta$gender_map,
      gender_nonmissing_weighted=sum(d$W[positive & d$GENDER %in% c("girl","boy")])/sum(d$W[positive]),
      stringsAsFactors=FALSE)
    counts <- data.frame(survey=task$survey,year=task$year,source_country_code=task$source_country_code,
      domain=task$domain,statistic=stats$statistic,expected_pvs=stats$expected_pvs,
      finite_full_pvs=stats$finite_full_pvs,expected_replicates=stats$expected_replicates,
      finite_replicates_min=stats$finite_replicates_min,finite_replicates_max=stats$finite_replicates_max,
      complete_replication=stats$complete_replication)
    # Save the small full/replicate statistic matrices for later checks, NOT student-level records.
    replicaudit <- list(full=full,replicate_estimates=reps,social_full=sf,social_replicates=sr,
      variance_factor=des$factor,replicate_errors=rep_errors)
    status <- data.frame(survey=task$survey,year=task$year,source_country_code=task$source_country_code,
      domain=task$domain,task_status="COMPUTED_PENDING_VALIDATION",reason="",stringsAsFactors=FALSE)
    ans <- list(token=token,estimates=stats,diagnostics=diag,counts=counts,status=status,replicate_aggregates=replicaudit,
      gender_support=rc2_gender_support_table(d,pp,task))
    rc2_save(ans,cp)
    message("Completed: ",task$survey," ",task$year," ",task$source_country_code," ",task$domain)
    ans
  },error=function(e)list(estimates=data.frame(),diagnostics=data.frame(),counts=data.frame(),
    status=data.frame(survey=task$survey,year=task$year,source_country_code=task$source_country_code,
      domain=task$domain,task_status="TASK_ERROR",reason=conditionMessage(e),stringsAsFactors=FALSE)))
}
rc2_parallel <- function(tasks,workers,outdir) {
  if(!nrow(tasks))return(list())
  rows <- lapply(seq_len(nrow(tasks)),function(i)as.list(tasks[i,,drop=FALSE]))
  nn <- unique(c(min(workers,nrow(tasks)),4L,2L,1L)); nn <- nn[nn<=nrow(tasks)&nn<=workers]
  exports <- unique(c(ls(envir=.GlobalEnv,pattern="^rc2_"),"RC2_SCRIPT_SHA","RC2_VERSION"))
  for(n in nn) {
    rc2_log("Estimator: ",nrow(tasks)," tasks; trying ",n," worker(s)")
    cl <- NULL
    ans <- tryCatch({
      if(n==1L)lapply(rows,rc2_worker) else {
        cl <- parallel::makePSOCKcluster(n,outfile=file.path(outdir,paste0("workers_",n,".log")))
        parallel::clusterExport(cl,exports,envir=.GlobalEnv)
        parallel::clusterEvalQ(cl,{
          Sys.setenv(OMP_NUM_THREADS="1",OPENBLAS_NUM_THREADS="1",MKL_NUM_THREADS="1")
          if(!requireNamespace("digest",quietly=TRUE))stop("digest unavailable to worker")
          TRUE
        })
        batches <- split(seq_along(rows),ceiling(seq_along(rows)/max(1L,n*4L)))
        result <- vector("list",length(rows))
        for(ix in batches) {
          result[ix] <- parallel::parLapplyLB(cl,rows[ix],rc2_worker)
          rc2_log("Completed or diagnosed: ",max(ix)," / ",length(rows)," tasks; keyed caches saved")
          rc2_csv(rc2_bind(lapply(result[seq_len(max(ix))],`[[`,"status")),file.path(outdir,"TASK_PROGRESS.csv"))
        }
        result
      }
    },error=function(e)e,finally={if(!is.null(cl))try(parallel::stopCluster(cl),silent=TRUE)})
    if(!inherits(ans,"error")){attr(ans,"workers_used")<-n;return(ans)}
    rc2_log("Worker infrastructure failed: ",conditionMessage(ans),". Completed keyed caches are preserved.")
  }
  stop("All parallel/sequential attempts failed")
}

