rc2_identity <- function(survey,year,code) {
  co <- read.csv(text=RC2_COUNTRIES_TEXT,stringsAsFactors=FALSE,na.strings="")
  cm <- read.csv(text=RC2_SOURCE_MAP_TEXT,stringsAsFactors=FALSE,na.strings="")
  ym <- read.csv(text=RC2_YEAR_MAP_TEXT,stringsAsFactors=FALSE,na.strings="")
  # Wave-specific PISA reporting-unit exceptions have precedence over generic aliases.
  y <- ym[ym$survey==survey&ym$year==year&ym$source_country_code==code,,drop=FALSE]
  id <- ""; basis <- ""
  if(nrow(y)==1L){id<-y$country_id;basis<-"RC1_WAVE_SPECIFIC_IDENTITY"}
  if(!nzchar(id)&&survey=="PISA") {
    z <- cm[cm$survey=="PISA"&cm$source_country_code==code &
      (is.na(cm$valid_from)|cm$valid_from<=year)&(is.na(cm$valid_to)|cm$valid_to>=year),,drop=FALSE]
    ids <- unique(z$country_id)
    if(length(ids)==1L){id<-ids;basis<-"RC1_PISA_ALIAS"}
  }
  if(!nzchar(id)) {
    # ISO identity is used only when the frozen registry actually certifies this code.
    z <- co[!is.na(co$iso3)&co$iso3==code&co$country_id==paste0("iso3:",code),,drop=FALSE]
    if(nrow(z)==1L){id<-z$country_id;basis<-"EXISTING_NATIONAL_IDENTITY"}
  }
  if(!nzchar(id)&&survey=="TIMSS") {
    # Explicit stable reporting-system aliases, never aggregate into their parent country.
    alias <- c(ROM="iso3:ROU",TWN="iso3:TWN",AAD="system:ABU",ADU="system:DUB",
      ENG="system:GBR_ENGLAND",SCO="system:GBR_SCOTLAND",NIR="system:GBR_NORTHERN_IRELAND")
    if(code %in% names(alias)){id<-unname(alias[code]);basis<-"EXPLICIT_TIMSS_REPORTING_ALIAS"}
    if(!nzchar(id)) {
      z <- cm[cm$survey=="PIRLS"&cm$source_country_code==code,,drop=FALSE]
      ids <- unique(z$country_id)
      if(length(ids)==1L){id<-ids;basis<-"CROSS_STUDY_REPORTING_ALIAS_REVIEW_REQUIRED"}
    }
  }
  unresolved <- !nzchar(id)
  if(unresolved){id<-paste0("system:UNRESOLVED_",survey,"_",year,"_",code);basis<-"UNRESOLVED_NOT_POOLED"}
  z <- co[co$country_id==id,,drop=FALSE]
  name <- if(nrow(z))z$country_name_en[1] else paste(survey,code)
  type <- if(nrow(z))z$geography_type[1] else "reporting_system_unverified"
  # A comparison key is separate from the unchanged source observation identity.
  compare <- if(id %in% c("iso3:KSV","system:XKX","iso3:XKX"))"system:KOSOVO_COMPARISON" else id
  ready <- !unresolved&&basis!="CROSS_STUDY_REPORTING_ALIAS_REVIEW_REQUIRED"
  data.frame(country_id=id,comparison_id=compare,country_name_en=name,geography_type=type,
    identity_basis=basis,identity_review_pass=ready,stringsAsFactors=FALSE)
}
rc2_add_identity <- function(d) {
  if(!nrow(d))return(d)
  keys <- unique(d[c("survey","year","source_country_code")])
  ids <- rc2_bind(lapply(seq_len(nrow(keys)),function(i)cbind(keys[i,,drop=FALSE],
    rc2_identity(keys$survey[i],keys$year[i],keys$source_country_code[i]))))
  merge(d,ids,by=c("survey","year","source_country_code"),all.x=TRUE,sort=FALSE)
}
rc2_rank <- function(z,smaller=FALSE) {
  N <- length(z); r <- rank(if(smaller)z else -z,ties.method="average",na.last="keep")
  data.frame(rank=r,n=N,fractional_rank=if(N>1)(r-1)/(N-1) else NA_real_)
}
rc2_panels <- function(est,diag,pair_plan) {
  registry <- members <- ranks <- excluded <- changes <- ages <- list()
  if(!nrow(est))return(list(registry=data.frame(),members=data.frame(),ranks=data.frame(),
    excluded=data.frame(),changes=data.frame(),cohorts=data.frame()))
  idcols <- c("survey","year","source_country_code","domain")
  d <- merge(est,diag[c(idcols,"weighted_mean_age","age_nonmissing_n")],by=idcols,all.x=TRUE)
  d$basic_eligible <- is.finite(d$estimate)&d$identity_review_pass&
    d$population_status %in% c("PISA_AGE_TARGET_UNRESTRICTED","G4_EXPLICIT")
  register <- function(pid,z,rule,expected_waves,domain,stat,kind) {
    ids <- sort(unique(z$comparison_id)); N <- length(ids)
    registry[[length(registry)+1L]] <<- data.frame(panel_id=pid,domain=domain,statistic=stat,
      panel_type=kind,n=N,expected_waves=paste(expected_waves,collapse=";"),rule=rule,
      status="CANDIDATE_PENDING_EXTERNAL_VALIDATION",stringsAsFactors=FALSE)
    if(N)members[[length(members)+1L]] <<- data.frame(panel_id=pid,comparison_id=ids,stringsAsFactors=FALSE)
  }
  # Explicit planned timelines. A missing planned wave never silently shortens a panel.
  for(s in c("TIMSS","PISA"))for(dom in c("mathematics","science")) {
    waves <- if(s=="TIMSS")c(1995,2003,2007,2011,2015,2019,2023) else
      if(dom=="mathematics")c(2003,2006,2009,2012,2015,2018,2022,2025) else c(2006,2009,2012,2015,2018,2022,2025)
    stats <- c("overall_mean","overall_baseline","p10","p50","p90","p90_p10",
      "q1_mean","q4_mean","score_gap","q1_baseline","q4_baseline","gap_baseline",
      "academic_school_sorting_share","social_rank_school_sorting_share")
    for(st in stats) {
      z <- d[d$survey==s&d$domain==dom&d$statistic==st&d$basic_eligible,,drop=FALSE]
      sets <- lapply(waves,function(w)unique(z$comparison_id[z$year==w]))
      fixed <- Reduce(intersect,sets); q <- z[z$comparison_id %in% fixed,,drop=FALSE]
      pid <- paste("LONG_FIXED",s,dom,st,sep="_")
      register(pid,q,"Finite outcomes and verified identity/target at every predeclared wave; no inferred membership",waves,dom,st,"longitudinal_fixed")
      for(w in waves) {
        a <- q[q$year==w,,drop=FALSE]
        if(!nrow(a))next
        if(anyDuplicated(a$comparison_id))stop("Duplicate reporting unit in a longitudinal panel")
        small <- grepl("gap|sorting|p90_p10",st)
        ranks[[length(ranks)+1L]] <- cbind(data.frame(panel_id=pid),a,rc2_rank(a$estimate,small))
      }
    }
  }
  sorting_stats <- c("academic_school_sorting_share","social_rank_school_sorting_share")
  for(dom in c("mathematics","science"))for(st in sorting_stats) {
    zz <- list()
    for(i in seq_len(nrow(pair_plan))) {
      p <- pair_plan[i,]; a <- d[d$survey=="TIMSS"&d$year==p$timss_year&d$domain==dom&d$statistic==st&d$basic_eligible,,drop=FALSE]
      b <- d[d$survey=="PISA"&d$year==p$pisa_year&d$domain==dom&d$statistic==st&d$basic_eligible,,drop=FALSE]
      cols <- c("comparison_id","country_id","source_country_code","estimate","se","weighted_mean_age","age_nonmissing_n")
      if(anyDuplicated(a$comparison_id)||anyDuplicated(b$comparison_id))stop("Duplicate system in cross-age candidate")
      q <- merge(a[cols],b[cols],by="comparison_id",suffixes=c("_age10","_age15"))
      pid <- paste("PAIR_MAX_COMMON",dom,st,p$pair_id,sep="_")
      register(pid,q,"Maximum finite verified-target intersection for this domain, statistic and pair; quality still conditional",c(p$timss_year,p$pisa_year),dom,st,"pair_specific")
      if(!nrow(q))next
      q$domain <- dom;q$statistic<-st;q$pair_id<-p$pair_id;q$panel_id<-pid;q$pair_role<-p$role
      q$change_age15_minus_age10 <- q$estimate_age15-q$estimate_age10
      q$change_se_independent_proxy <- sqrt(q$se_age10^2+q$se_age15^2)
      q$birth_cohort_gap_proxy_years <- (p$pisa_year-p$timss_year)-(q$weighted_mean_age_age15-q$weighted_mean_age_age10)
      q$age_match_status <- ifelse(p$role=="current_system_only","NOT_A_COHORT",ifelse(
        !is.finite(q$birth_cohort_gap_proxy_years),"AGE_UNAVAILABLE",ifelse(abs(q$birth_cohort_gap_proxy_years)<=.75,
        "CLOSE_PROXY",ifelse(abs(q$birth_cohort_gap_proxy_years)<=1.5,"ADJACENT_PROXY","WIDE_PROXY"))))
      q <- cbind(q,rc2_rank(q$change_age15_minus_age10,TRUE)); changes[[length(changes)+1L]] <- q
      zz[[p$pair_id]] <- q
    }
    mainids <- pair_plan$pair_id[pair_plan$include_fixed_main]
    fixed <- Reduce(intersect,lapply(mainids,function(p)if(p %in% names(zz))zz[[p]]$comparison_id else character()))
    pid <- paste("CROSS_PAIR_FIXED_MAIN",dom,st,sep="_")
    z <- data.frame(comparison_id=fixed)
    register(pid,z,"Intersection across all predeclared main pairs, not only completed/available pairs",mainids,dom,st,"cross_pair_fixed_main")
    for(p in names(zz)) {
      q <- zz[[p]][zz[[p]]$comparison_id %in% fixed,,drop=FALSE]
      if(!nrow(q))next
      q$panel_id<-pid;q$rank<-NULL;q$n<-NULL;q$fractional_rank<-NULL
      ranks[[length(ranks)+1L]] <- cbind(q,rc2_rank(q$change_age15_minus_age10,TRUE))
    }
  }
  # Latest SES panels are domain/outcome-specific, with both ages using exactly the same systems.
  for(dom in c("mathematics","science"))for(st in c("score_gap","gap_baseline")) {
    a <- d[d$survey=="TIMSS"&d$year==2023&d$domain==dom&d$statistic==st&d$basic_eligible,,drop=FALSE]
    b <- d[d$survey=="PISA"&d$year==2025&d$domain==dom&d$statistic==st&d$basic_eligible,,drop=FALSE]
    common <- intersect(a$comparison_id,b$comparison_id)
    z <- rc2_bind(list(a[a$comparison_id %in% common,,drop=FALSE],b[b$comparison_id %in% common,,drop=FALSE]))
    pid <- paste("LATEST_IDENTICAL",dom,st,"T2023_P2025",sep="_")
    register(pid,z,"Identical reporting systems at both ages; instrument-specific scales and thresholds",c(2023,2025),dom,st,"latest_identical")
    for(s in c("TIMSS","PISA")) {
      q <- z[z$survey==s,,drop=FALSE]
      if(nrow(q))ranks[[length(ranks)+1L]] <- cbind(data.frame(panel_id=pid),q,rc2_rank(q$estimate,TRUE))
    }
    # Store Q1/Q4 levels under exactly the SAME gap-defined membership, never reconstruct them in the UI.
    lv <- if(st=="score_gap")c("q1_mean","q4_mean") else c("q1_baseline","q4_baseline")
    for(s in c("TIMSS","PISA"))for(l in lv) {
      yr <- if(s=="TIMSS")2023 else 2025
      q <- d[d$survey==s&d$year==yr&d$domain==dom&d$statistic==l&
        d$comparison_id %in% common,,drop=FALSE]
      if(nrow(q))ranks[[length(ranks)+1L]] <- cbind(data.frame(panel_id=pid),q,
        data.frame(rank=NA_real_,n=length(common),fractional_rank=NA_real_))
    }
  }
  bad <- d[!d$basic_eligible,c("survey","year","source_country_code","domain","statistic","estimate",
    "country_id","comparison_id","identity_basis","population_status")]
  if(nrow(bad))bad$exclusion_reason <- "Nonfinite outcome OR unadjudicated identity OR unverified/non4 target; source rows retained"
  list(registry=rc2_bind(registry),members=rc2_bind(members),ranks=rc2_bind(ranks),excluded=bad,
    changes=rc2_bind(changes),cohorts=unique(diag[c("survey","year","source_country_code","domain",
      "country_id","comparison_id","weighted_mean_age","age_nonmissing_n","population_status")]))
}

# Only table-like official data from the existing master may be harvested, never arbitrary RDS frames.
rc2_official_harvest <- function(root,outdir) {
  dir.create(outdir,recursive=TRUE,showWarnings=FALSE)
  p <- file.path(root,"PISA_PIRLS_MASTER_ANALYSIS.rds")
  report <- list(); written <- 0L
  if(file.exists(p)) {
    m <- tryCatch(readRDS(p),error=function(e)NULL)
    walk <- function(x,path="master",depth=0L) {
      if(depth>5L)return(invisible(NULL))
      if(is.data.frame(x)) {
        nn <- tolower(names(x))
        iscells <- any(grepl("table.*id|table_id|table_code",nn))&&
          any(grepl("cell|value|header",nn))&&!any(grepl("^pv[0-9]|^w_fst|^cntstuid$|^idstud",nn))
        if(iscells&&nrow(x)>0&&nrow(x)<2000000) {
          written <<- written+1L
          nm <- paste0("OFFICIAL_CELLS_",written,".csv")
          rc2_csv(x,file.path(outdir,nm))
          report[[length(report)+1L]] <<- data.frame(file=nm,object_path=path,n_rows=nrow(x),
            source_sha256=rc2_sha(p),status="RAW_OFFICIAL_CELLS_NOT_YET_COLUMN_ADJUDICATED")
        }
      } else if(is.list(x)&&!is.environment(x)) {
        ns <- names(x); if(is.null(ns))return(invisible(NULL))
        for(n in ns) if(depth>0L||grepl("pisa|oecd|table|cell",n,ignore.case=TRUE))walk(x[[n]],paste(path,n,sep="$"),depth+1L)
      }
      invisible(NULL)
    }
    if(!is.null(m))walk(m)
    rm(m); gc()
  }
  # Exact already-downloaded OECD workbooks are the preferred unambiguous external validation inputs.
  ff <- list.files(file.path(root,"02_raw_oecd"),pattern="\\.xlsx?$",recursive=TRUE,full.names=TRUE,ignore.case=TRUE)
  for(f in ff) {
    if(file.info(f)$size>=30*1024^2) {
      report[[length(report)+1L]] <- data.frame(file=basename(f),object_path=f,n_rows=NA_integer_,
        source_sha256=rc2_sha(f),status="SIZE_LIMIT_NOT_COPIED_ORIGINAL_PRESERVED")
      next
    }
    sha <- rc2_sha(f); nm <- paste0(substr(sha,1,12),"_",basename(f))
    target <- file.path(outdir,nm)
    if(!file.exists(target))file.copy(f,target,overwrite=FALSE)
    if(!file.exists(target)||rc2_sha(target)!=sha)stop("Official workbook copy failed integrity check: ",f)
    report[[length(report)+1L]] <- data.frame(file=nm,object_path="local_OECD_workbook",n_rows=NA_integer_,
      source_sha256=sha,status="ORIGINAL_WORKBOOK_PENDING_EXTERNAL_VALIDATION")
  }
  rc2_bind(report)
}

# =============================================================================
# MAIN: all writes go to 20_rc2_domains; no automatic publication/freeze.
# =============================================================================
rc2_fixture_test <- function() {
  # Synthetic regression tests only. Scratch student rows never enter the handoff.
  td <- tempfile("rc2_selftest_");dir.create(td)
  on.exit(unlink(td,recursive=TRUE),add=TRUE)
  checks <- list()
  # Regression test for the two V1 source-selection bugs.
  zz15 <- data.frame(Name=c("CY6_MS_CMB_STU_QQ2.sav","CY6_MS_CMB_STU_QQQ.sav"),
    Length=c(1600000000,1500000000),stringsAsFactors=FALSE)
  if(basename(rc2_pick_pisa_member(2015L,zz15)$Name)!="CY6_MS_CMB_STU_QQQ.sav")
    stop("PISA 2015 member-selection regression failed")
  zz09 <- data.frame(Name=c("README.txt","INT_STQ09_DEC11.txt"),Length=c(1000,1500000000))
  if(basename(rc2_pick_pisa_member(2009L,zz09)$Name)!="INT_STQ09_DEC11.txt")
    stop("PISA 2009 exact-name regression failed")
  zz03 <- data.frame(Name=c("notes.txt","int_stui_2003.txt"),Length=c(1000,1000000000))
  if(toupper(basename(rc2_pick_pisa_member(2003L,zz03)$Name))!="INT_STUI_2003.TXT")
    stop("PISA 2003 exact-name regression failed")
  idtest <- data.frame(SCHOOL_ID=rep(NA_character_,3),CNTSCHID=c("1","2","3"))
  if(rc2_best_column(idtest,c("SCHOOL_ID","CNTSCHID"))!="CNTSCHID")
    stop("Best-covered ID-column selection regression failed")
  checks[[length(checks)+1L]]<-data.frame(check="pisa_source_and_id_selection_regressions",pass=TRUE)
  for(case in c("TIMSS_2011","TIMSS_2015","PISA_2025")) {
    ss <- strsplit(case,"_",fixed=TRUE)[[1]]; survey<-ss[1];year<-as.integer(ss[2])
    M <- if(survey=="PISA")10L else 5L; N<-120L; y<-400+seq_len(N)
    d <- data.frame(SCHOOL=rep(paste0("s",1:4),each=30),STUDENT=as.character(seq_len(N)),
      W=rep(1,N),AGE=rep(if(survey=="PISA")15.7 else 10.3,N),GRADE=rep(4,N),
      CLASS=rep(paste0("c",1:4),each=30),HAS_BOOKS_CATEGORIES=survey=="TIMSS",
      SES=rep(1:5,length.out=N),ISCED=if(survey=="PISA")2 else NA_real_,MODAL=survey=="PISA",
      stringsAsFactors=FALSE)
    if(survey=="PISA") {
      for(j in 1:80)d[[paste0("RW",j)]]<-rep(1,N)
    } else {
      d$JKZONE<-rep(1:2,each=60);d$JKREP<-rep(rep(0:1,each=30),2)
    }
    for(m in seq_len(M))d[[paste0("PV_MATH_",m)]]<-y+m-1
    meta <- list(survey=survey,year=year,source_country_code="TST",n_original=N,n_selected=N,
      n_excluded_population=0,population_rule="SYNTHETIC_TEST_ONLY",
      population_status=if(survey=="PISA")"PISA_AGE_TARGET_UNRESTRICTED" else "G4_EXPLICIT",
      observed_grades="4",ses_variable="SYNTHETIC_TEST_ONLY",ses_status="SYNTHETIC_TEST_ONLY",
      modal_levels=if(survey=="PISA")"2" else "",modal_status="SYNTHETIC_TEST_ONLY",
      source_sha256="SYNTHETIC_TEST_ONLY",source_member="",source_path="SYNTHETIC_TEST_ONLY")
    src<-file.path(td,paste0(case,"_input.rds")); saveRDS(list(data=d,meta=meta,input_key=case),src)
    task<-list(survey=survey,year=year,source_country_code="TST",domain="mathematics",path=src,
      input_key=case,result_cache=file.path(td,paste0(case,"_result.rds")))
    a<-rc2_worker(task)
    if(a$status$task_status!="COMPUTED_PENDING_VALIDATION")stop("Synthetic worker selftest failed: ",a$status$reason)
    z<-a$estimates[a$estimates$statistic=="overall_mean",,drop=FALSE]
    ok <- nrow(z)==1L&&abs(z$estimate-(mean(y)+mean(seq_len(M)-1)))<1e-10 &&
      z$finite_full_pvs==M&&z$complete_replication&&is.finite(z$se)
    if(!ok)stop("Synthetic full-worker mean/PV/replicate test failed: ",case)
    b<-rc2_worker(task)
    if(!identical(a,b))stop("Source-keyed result cache roundtrip failed: ",case)
    checks[[length(checks)+1L]]<-data.frame(check=paste0("synthetic_full_worker_and_cache_",case),pass=TRUE)
  }
  rc2_bind(checks)
}

rc2_production_gate <- function(preflight,tasks,status=NULL) {
  inputs_complete <- nrow(preflight)>0L&&all(preflight$status=="READY")
  tasks_complete <- !is.null(status)&&nrow(tasks)>0L&&nrow(status)==nrow(tasks)&&
    "task_status" %in% names(status)&&all(status$task_status=="COMPUTED_PENDING_VALIDATION")
  list(run_estimator=nrow(tasks)>0L,inputs_complete=inputs_complete,
    tasks_complete=tasks_complete,panels_allowed=inputs_complete&&tasks_complete)
}
rc2_import_selftest <- function() {
  out <- list();add <- function(n,ok) {
    if(!isTRUE(ok))stop("IMPORT SELFTEST FAILED: ",n)
    out[[length(out)+1L]] <<- data.frame(check=n,pass=TRUE)
  }
  td <- tempfile("rc2_import_test_");dir.create(td)
  on.exit(unlink(td,recursive=TRUE),add=TRUE)
  ctl <- file.path(td,"official_format_fixture.sas")
  writeLines(c("PROC FORMAT;", "VALUE ESCS_F 9999='Missing' 9998='Invalid';",
    "VALUE AGE_F 99='Not applicable';", "RUN;", "FORMAT ESCS ESCS_F. AGE AGE_F.;",
    "IF W_FSTUWT = 999999 THEN W_FSTUWT=.;",
    "IF ISCEDL IN (7,8,9) THEN ISCEDL=.;"),ctl)
  rr <- rc2_control_rules(ctl,c("ESCS","AGE","W_FSTUWT","ISCEDL"))
  add("SAS_formats_bind_variable_to_missing_labels",setequal(rr$ESCS$missing,c(9999,9998)))
  add("SAS_scalar_missing_recode",identical(rr$W_FSTUWT$missing,999999))
  add("SAS_IN_missing_recode",setequal(rr$ISCEDL$missing,c(7,8,9)))
  add("SAS_mixed_explicit_implied_decimal_per_cell",
    isTRUE(all.equal(rc2_decode_field(c("12500","1.2500","-12500",".",""),.0001),c(1.25,1.25,-1.25,NA,NA))))
  add("SAS_missing_codes_after_implied_decimal",
    all(is.na(rc2_decode_field(c("99990000","9999.0000"),.0001,rr$ESCS$missing))))
  add("SAS_unknown_extremes_never_silently_clipped",rc2_decode_field("12345",1,rr$ESCS$missing)==12345)
  labels <- c("NONE OR FEW (0-10)"=1,"ONE SHELF (11-25)"=2,"ONE BOOKCASE (26-100)"=3,
    "TWO BOOKCASES (101-200)"=4,"THREE ORE MORE BOOKCASES (200+)"=5,"OMITTED OR INVALID"=9)
  x <- structure(c(1:5,9),labels=labels)
  add("TIMSS2011_actual_200plus_books_label",identical(rc2_books(x),c(1:5,NA_real_)))
  bad <- x;attr(bad,"labels")[5] <- 5;names(attr(bad,"labels"))[5] <- "Unknown group"
  add("books_unknown_label_still_rejected",inherits(try(rc2_books(bad),silent=TRUE),"try-error"))
  d <- data.frame(SCHOOLID=c("0001","0001","0002","0002"),STIDSTD=c("01","02","01","02"))
  ids <- rc2_pisa_ids(d,"TST")
  add("PISA2006_school_local_student_IDs_allowed",length(unique(paste(ids$school,ids$student)))==4L)
  d$SCHOOL_ID <- NA_character_;d$STUDENT_ID <- NA_character_
  add("empty_canonical_ID_column_not_selected",rc2_pisa_ids(d,"TST")$school_column=="SCHOOLID")
  add("leading_zero_ID_equivalence",identical(rc2_id_normalize(c("0001","1.0","1")),rep("1",3)))
  d$STIDSTD[2] <- "01"
  add("duplicate_school_student_pair_rejected",inherits(try(rc2_pisa_ids(d,"TST"),silent=TRUE),"try-error"))
  d$STIDSTD[2] <- "02";d$SCHOOLID[1] <- NA_character_
  add("missing_ID_rows_not_silently_deleted",inherits(try(rc2_pisa_ids(d,"TST"),silent=TRUE),"try-error"))
  # End-to-end canonical conversion uses the selected IDs, not the stale empty column.
  N <- 120L
  d <- data.frame(CNT="NLD",SCHOOL_ID=NA_character_,STUDENT_ID=NA_character_,
    CNTSCHID=rep(c("0001","0002","0003","0004"),each=30),CNTSTUID=as.character(seq_len(N)),
    ESCS=seq(-2,2,length.out=N),AGE=15.7,W_FSTUWT=1,ISCEDL=2)
  for(j in 1:80)d[[paste0("W_FSTR",j)]] <- 1
  for(j in 1:10){d[[paste0("PV",j,"MATH")]] <- 450+j;d[[paste0("PV",j,"SCIE")]] <- 460+j}
  ids <- rc2_pisa_ids(d,"NLD");d$SCHOOL_ID <- ids$school;d$STUDENT_ID <- ids$student
  z <- rc2_canonical(d,"PISA",2025,"NLD")
  add("PISA2025_raw_ID_to_canonical_path",all(!is.na(z$data$SCHOOL))&&nrow(z$data)==N)
  add("PISA_full_source_design_retains_all_80_replicates",rc2_replicate_design(z$data,"PISA",2025)$n==80L)
  d$ESCS[1] <- 9999
  add("unknown_ESCS_code_keeps_integrity_hold",inherits(try(rc2_canonical(d,"PISA",2025,"NLD"),silent=TRUE),"try-error"))
  rc2_bind(out)
}

rc2_v4_selftest <- function() {
  out <- list(); add <- function(n,ok) {
    if(!isTRUE(ok))stop("V4 SELFTEST FAILED: ",n)
    out[[length(out)+1L]] <<- data.frame(check=n,pass=TRUE)
  }
  td <- tempfile("rc2_v4_test_");dir.create(td)
  on.exit(unlink(td,recursive=TRUE),add=TRUE)
  ctl <- file.path(td,"actual_label_forms.sas")
  # These format labels and ESCS associations were exported from the user's
  # actual 2006/2009 SAS files. No broad rule such as x > 10 => NA is used.
  writeLines(c("PROC FORMAT; VALUE CARINFO 997='N/A' 999='Missing';",
    "VALUE INDF 9997='N/A' 9999='Missing' 9998='Invalid'; RUN;",
    "FORMAT ESCS CARINFO. ESCS09 INDF.;"),ctl)
  z <- rc2_control_rules(ctl,c("ESCS","ESCS09"))
  add("actual_2006_NA_997_documented",setequal(z$ESCS$missing,c(997,999)))
  add("actual_2009_NA_9997_documented",setequal(z$ESCS09$missing,c(9997,9998,9999)))
  add("ESCS_NA_codes_removed_valid_values_preserved",identical(
    rc2_decode_field(c('-2.4','997','1.2'),1,z$ESCS$missing),c(-2.4,NA_real_,1.2)))
  add("NA_matching_not_arbitrary_label_substring",identical(rc2_missing_label(c('N/A','National score','Banana')),c(TRUE,FALSE,FALSE)))
  x <- structure(c(997,-2,1),labels=c('N/A'=997,'valid positive'=1))
  add("labelled_NA_code_removed",identical(as.numeric(rc2_clean_labeled(x)),c(NA_real_,-2,1)))
  d <- data.frame(CNTSCHID=NA_real_,CNTSTUID=c('1','2','3'))
  z <- rc2_pisa_ids(d,'TST')
  add("school_absent_unique_global_student_kept",all(is.na(z$school))&&identical(z$student,c('1','2','3')))
  add("school_absence_explicit_audit",z$school_status=='SCHOOL_IDS_UNAVAILABLE_IN_SOURCE'&&nrow(z$audit)==2L)
  d$CNTSTUID[2] <- '1'
  add("school_absent_duplicate_students_rejected",inherits(try(rc2_pisa_ids(d,'TST'),silent=TRUE),'try-error'))
  d <- data.frame(CNTSCHID=c(1,NA,1),CNTSTUID=c('1','2','3'))
  add("partially_missing_schools_still_hold",inherits(try(rc2_pisa_ids(d,'TST'),silent=TRUE),'try-error'))
  d <- data.frame(SCHOOLID=NA_real_,STIDSTD=c('1','2','3'))
  add("local_student_ID_not_promoted_to_global",inherits(try(rc2_pisa_ids(d,'TST'),silent=TRUE),'try-error'))
  d <- data.frame(CNT='TST',CNTSCHID=NA_real_,CNTSTUID=as.character(1:120),
    AGE=15.7,ESCS=seq(-2,2,length.out=120),W_FSTUWT=1,ISCEDL=2)
  z <- rc2_pisa_ids(d,'TST');d$SCHOOL_ID<-z$school;d$STUDENT_ID<-z$student
  c <- rc2_canonical(d,'PISA',2025,'TST')
  add("canonical_student_only_keeps_all_rows",nrow(c$data)==120L&&all(is.na(c$data$SCHOOL)))
  add("student_only_has_no_modal_school_sample",!any(c$data$MODAL))
  add("unavailable_school_sorting_is_NA",is.na(rc2_between(1:120,c$data$SCHOOL,rep(1,120))))
  d$AGE <- NA_real_;d$ESCS<-NA_real_
  c <- rc2_canonical(d,'PISA',2025,'TST')
  add("missing_age_and_SES_explicit",c$meta$age_status=='AGE_UNAVAILABLE_IN_SOURCE'&&c$meta$ses_status=='ESCS_UNAVAILABLE')
  rc2_bind(out)
}

rc2_v5_selftest <- function() {
  out <- list();add <- function(n,ok) {
    if(!isTRUE(ok))stop("V5 SELFTEST FAILED: ",n)
    out[[length(out)+1L]] <<- data.frame(check=n,pass=TRUE)
  }
  txt <- paste("array miss3 (2) ESCS HOME; do i=1 to 2;",
    "if (miss3{i}=997 or miss3{i}=.) then miss3{i}=.N;",
    "if miss3{i}=998 then miss3{i}=.I; if miss3{i}=999 then miss3{i}=.M; end;")
  a <- rc2_sas_array_rules(txt,c("ESCS","AGE"))
  add("SAS_array_declared_codes_997_998_999",setequal(a$ESCS,c(997,998,999)))
  add("SAS_array_rule_does_not_leak_to_other_variable",length(a$AGE)==0L)
  add("SAS_array_documented_codes_only",identical(rc2_decode_field(c('-2.3','997','998','999','12345'),1,a$ESCS),c(-2.3,NA_real_,NA_real_,NA_real_,12345)))
  bad <- sub('do i=1 to 2','do i=1 to 1',txt,fixed=TRUE)
  add("SAS_partial_array_loop_rejected",inherits(try(rc2_sas_array_rules(bad,'ESCS'),silent=TRUE),'try-error'))
  bad <- sub('miss3{i}=998','miss3{i}=998 and CNT=1',txt,fixed=TRUE)
  add("SAS_conditional_array_recode_rejected",inherits(try(rc2_sas_array_rules(bad,'ESCS'),silent=TRUE),'try-error'))
  bad <- sub('miss3 (2)','miss3 (3)',txt,fixed=TRUE)
  add("SAS_array_dimension_mismatch_rejected",inherits(try(rc2_sas_array_rules(bad,'ESCS'),silent=TRUE),'try-error'))
  pf <- data.frame(status=c('READY','INPUT_HOLD'));tasks <- data.frame(id=1:2)
  status <- data.frame(task_status=rep('COMPUTED_PENDING_VALIDATION',2))
  g <- rc2_production_gate(pf,tasks,status)
  add("partial_sources_run_tasks_but_withhold_panels",g$run_estimator&&!g$panels_allowed&&!g$inputs_complete)
  pf$status <- 'READY'
  add("complete_sources_and_tasks_allow_candidate_panels",rc2_production_gate(pf,tasks,status)$panels_allowed)
  status$task_status[1] <- 'TASK_ERROR'
  add("task_error_blocks_candidate_panels",!rc2_production_gate(pf,tasks,status)$panels_allowed)
  add("no_prepared_tasks_skip_estimator",!rc2_production_gate(pf,data.frame())$run_estimator)
  rc2_bind(out)
}

# =============================================================================
# V6 additions. Source labels are required; no guessed coding or zero-filled groups.
# =============================================================================
rc2_gender_decode <- function(raw,survey,year) {
  candidates <- intersect(if(survey=="PISA")c("ST004D01T","ST04Q01") else c("ITSEX","ASBG01"),names(raw))
  N <- nrow(raw); found <- list(); maps <- character()
  for(v in candidates) {
    x <- raw[[v]]; labs <- attr(x,"labels",exact=TRUE)
    if(is.null(labs)||!length(labs))next
    lab <- tolower(trimws(names(labs)))
    g <- ifelse(grepl("^(female|girl|girls)$",lab),"girl",ifelse(grepl("^(male|boy|boys)$",lab),"boy",NA_character_))
    ok <- !is.na(g)
    if(sum(ok)!=2L||!setequal(g[ok],c("girl","boy"))||anyDuplicated(unname(labs[ok])))next
    mp <- setNames(g[ok],as.character(unname(labs[ok])))
    found[[v]] <- unname(mp[as.character(rc2_num(x))])
    maps[v] <- paste(names(mp),mp,sep="=",collapse=";")
  }
  if(!length(found))return(list(value=rep(NA_character_,N),variable=paste(candidates,collapse=";"),map="",status="LABELS_UNAVAILABLE"))
  selected <- names(found)[which.max(vapply(found,function(x)sum(!is.na(x)),integer(1)))]
  result <- found[[selected]]
  for(x in found)if(any(!is.na(result)&!is.na(x)&result!=x))
    return(list(value=rep(NA_character_,N),variable=paste(names(found),collapse=";"),map=paste(maps,collapse="|"),status="CONFLICTING_LABEL_VERIFIED_COLUMNS"))
  list(value=result,variable=selected,map=unname(maps[selected]),status="SOURCE_VALUE_LABEL_VERIFIED")
}
rc2_gender_stats <- function(y,d,w,tails,thresholds) {
  g <- if("GENDER" %in% names(d))d$GENDER else rep(NA_character_,length(y))
  masks <- list(girl=as.numeric(!is.na(g)&g=="girl"),boy=as.numeric(!is.na(g)&g=="boy"))
  masks$girl_q1 <- masks$girl*tails$q1; masks$boy_q1 <- masks$boy*tails$q1
  masks$girl_q4 <- masks$girl*tails$q4; masks$boy_q4 <- masks$boy*tails$q4
  # Gates fixed by original weights/PV support, not re-selected per replicate.
  fixed_tails <- rc2_tails_rank(d$SES,d$W)
  fixed_masks <- list(girl=masks$girl,boy=masks$boy,
    girl_q1=masks$girl*fixed_tails$q1,boy_q1=masks$boy*fixed_tails$q1,
    girl_q4=masks$girl*fixed_tails$q4,boy_q4=masks$boy*fixed_tails$q4)
  support <- vapply(fixed_masks,function(a) {
    ok <- is.finite(y)&is.finite(d$W)&d$W>0&is.finite(a)&a>0
    ww <- d$W[ok]*a[ok]
    sum(ok)>=30L&&length(ww)>0&&sum(ww)^2/sum(ww^2)>=20
  },logical(1))
  outcomes <- list(mean=y,low=ifelse(is.finite(y),as.numeric(y<thresholds['baseline']),NA_real_),
                   top=ifelse(is.finite(y),as.numeric(y>=thresholds['top']),NA_real_))
  result <- numeric()
  for(st in names(outcomes)) {
    vv <- vapply(names(masks),function(n)if(support[n])rc2_weighted_mean(outcomes[[st]],w*masks[[n]]) else NA_real_,numeric(1))
    names(vv) <- paste0('gender_',names(vv),'_',st);result <- c(result,vv)
    v <- setNames(unname(vv),names(masks))
    con <- c(boy_minus_girl=v['boy']-v['girl'],boy_minus_girl_q1=v['boy_q1']-v['girl_q1'],
      boy_minus_girl_q4=v['boy_q4']-v['girl_q4'],girl_ses_gap=v['girl_q4']-v['girl_q1'],
      boy_ses_gap=v['boy_q4']-v['boy_q1'],ses_interaction=(v['boy_q4']-v['girl_q4'])-(v['boy_q1']-v['girl_q1']))
    names(con) <- paste0('gender_',c('boy_minus_girl','boy_minus_girl_q1','boy_minus_girl_q4','girl_ses_gap','boy_ses_gap','ses_interaction'),'_',st)
    result <- c(result,con)
  }
  result
}
rc2_core_pv_stats <- rc2_pv_stats
rc2_pv_stats <- function(y,d,w,tails,thresholds) {
  gs <- rc2_gender_stats(y,d,w,tails,thresholds)
  if(isTRUE(d$GENDER_ONLY[1]))return(gs)
  c(rc2_core_pv_stats(y,d,w,tails,thresholds),gs)
}
rc2_core_stat_unit <- rc2_stat_unit
rc2_stat_unit <- function(x) {
  z <- rc2_core_stat_unit(x)
  z[grepl('^gender_.*_(low|top)$',x)] <- 'proportion_or_proportion_difference'
  z
}
rc2_find_root <- function() {
  requested <- getOption('pisa.rc2.root',NULL)
  if(!is.null(requested)) {
    if(!dir.exists(requested))stop('Configured project folder does not exist: ',requested)
    return(rc2_norm(requested))
  }
  home <- path.expand('~'); user <- Sys.getenv('USERPROFILE')
  dirs <- unique(c(if(nzchar(RC2_SCRIPT_PATH))dirname(RC2_SCRIPT_PATH),getwd(),home,
    file.path(home,'Downloads'),if(nzchar(user))file.path(user,'Downloads'),file.path(Sys.getenv('USERPROFILE'),'Downloads')))
  candidates <- unique(c(dirs[basename(dirs)=='PISA_PIRLS_MASTER_PIPELINE'],file.path(dirs,'PISA_PIRLS_MASTER_PIPELINE')))
  candidates <- unique(rc2_norm(candidates[dir.exists(candidates)]))
  if(length(candidates)==1L)return(candidates)
  if(!length(candidates))stop('Project folder PISA_PIRLS_MASTER_PIPELINE not found beside this script or in Downloads.')
  stop('Multiple project folders found; refusing to mix: ',paste(candidates,collapse=' | '),'. Set options(pisa.rc2.root="the correct path") once.')
}
