rc2_valid_workbook <- function(p) {
  if(!file.exists(p)||file.info(p)$size<100)return(FALSE)
  z <- try(utils::unzip(p,list=TRUE),silent=TRUE)
  !inherits(z,'try-error')&&'xl/workbook.xml' %in% z$Name
}
rc2_fetch_aggregate <- function(url,path,kind='xlsx') {
  dir.create(dirname(path),recursive=TRUE,showWarnings=FALSE)
  old <- getOption('timeout');on.exit(options(timeout=old),add=TRUE)
  options(timeout=max(60,min(old,180)))
  tmp <- tempfile('aggregate_',tmpdir=dirname(path));on.exit(unlink(tmp),add=TRUE)
  status <- utils::download.file(url,tmp,mode='wb',quiet=TRUE,method='libcurl')
  if(status!=0L||!file.exists(tmp)||file.info(tmp)$size<50)stop('Empty/failed aggregate download')
  if(kind=='xlsx'&&!rc2_valid_workbook(tmp))stop('Response is not an Excel workbook')
  if(kind=='pdf') {
    con <- file(tmp,'rb');h <- rawToChar(readBin(con,'raw',n=5));close(con)
    if(h!='%PDF-')stop('Response is not PDF')
  }
  sha <- rc2_sha(tmp)
  if(file.exists(path)&&rc2_sha(path)!=sha)path <- file.path(dirname(path),paste0(substr(sha,1,12),'_',basename(path)))
  if(!file.exists(path)&&!file.copy(tmp,path))stop('Could not preserve aggregate')
  if(rc2_sha(path)!=sha)stop('Aggregate copy checksum mismatch')
  path
}
rc2_collect_sources <- function(root,out,allow) {
  registry <- rc2_source_registry()
  cache <- file.path(root,'20_rc2_domains','sources','official_v6');dir.create(cache,recursive=TRUE,showWarnings=FALSE)
  target <- file.path(out,'official_sources_v6');dir.create(target,recursive=TRUE,showWarnings=FALSE)
  rows <- list()
  for(i in seq_len(nrow(registry))) {
    r <- registry[i,];cached <- file.path(cache,r$filename)
    ans <- tryCatch({
      # A successful prior V6 download is hash-recorded and reusable on resume.
      if(!rc2_valid_workbook(cached)) {
        if(!allow)stop('Download disabled and no V6 workbook')
        cached <- rc2_fetch_aggregate(r$url,cached,'xlsx')
      }
      nm <- paste0(substr(rc2_sha(cached),1,12),'_',basename(cached));dest <- file.path(target,nm)
      if(!file.exists(dest)&&!file.copy(cached,dest))stop('Copy failed')
      if(rc2_sha(dest)!=rc2_sha(cached))stop('Copy integrity failed')
      data.frame(source_id=r$source_id,url=r$url,file=nm,sha256=rc2_sha(dest),status=if(rc2_sha(dest)==r$expected_sha256)'EXACT_VERIFIED_SOURCE_BYTES' else 'SOURCE_REVISION_REVIEW_REQUIRED',reason=if(rc2_sha(dest)==r$expected_sha256)'' else 'Different bytes than source reviewed on 2026-09-24; do not silently splice')
    },error=function(e)data.frame(source_id=r$source_id,url=r$url,file='',sha256='',status='SOURCE_HOLD',reason=conditionMessage(e)))
    rows[[length(rows)+1L]] <- ans
    rc2_csv(rc2_bind(rows),file.path(out,'OFFICIAL_V6_ACQUISITION.csv'))
  }
  # Existing independently downloaded workbooks: retain, do not silently relabel or overwrite.
  local <- unique(c(list.files(file.path(root,'02_raw_oecd'),pattern='\\.xlsx$',recursive=TRUE,full.names=TRUE,ignore.case=TRUE),
    list.files(file.path(root,'official_xlsx'),pattern='\\.xlsx$',recursive=TRUE,full.names=TRUE,ignore.case=TRUE)))
  for(f in local)if(rc2_valid_workbook(f)&&file.info(f)$size<30*1024^2) {
    sha <- rc2_sha(f);nm <- paste0(substr(sha,1,12),'_',basename(f));dst <- file.path(target,nm)
    if(!file.exists(dst))file.copy(f,dst)
    if(!file.exists(dst)||rc2_sha(dst)!=sha)stop('Local source preservation failed')
    rows[[length(rows)+1L]] <- data.frame(source_id='existing_OECD_workbook',url='',file=nm,sha256=sha,status='LOCAL_ORIGINAL_PRESERVED_PENDING_REVISION_COMPARISON',reason='')
  }
  # Fixed verified source register: no uncontrolled crawl or repeated guessed URLs.
  rc2_csv(rc2_bind(rows),file.path(out,'OFFICIAL_V6_ACQUISITION.csv'))
  # Cell extraction is optional; raw workbooks remain usable if readxl install fails.
  status <- tryCatch({rc2_package('readxl');rc2_workbook_inventory(target,out);'COMPLETE'},error=function(e)conditionMessage(e))
  writeLines(status,file.path(out,'OFFICIAL_CELL_EXTRACTION_STATUS.txt'))
  rc2_bind(rows)
}
rc2_workbook_inventory <- function(target,out) {
  inventory <- list();ff <- list.files(target,pattern='\\.xlsx$',full.names=TRUE)
  for(f in ff) {
    sh <- tryCatch(readxl::excel_sheets(f),error=function(e)character())
    for(s in sh) {
      a <- tryCatch(as.data.frame(readxl::read_excel(f,sheet=s,col_names=FALSE,col_types='text',.name_repair='minimal')),error=function(e)NULL)
      if(is.null(a))next
      names(a)<-paste0('column_',seq_len(ncol(a)));a<-cbind(source_row=seq_len(nrow(a)),a)
      safe <- gsub('[^A-Za-z0-9_.-]','_',s)
      dest <- paste0(tools::file_path_sans_ext(basename(f)),'__',safe,'.csv')
      rc2_csv(a,file.path(out,'official_sheet_grids',dest))
      inventory[[length(inventory)+1L]] <- data.frame(workbook=basename(f),sheet=s,rows=nrow(a),columns=ncol(a)-1L,
        grid=dest,source_sha256=rc2_sha(f),status='RAW_GRID_HEADERS_NOT_ADJUDICATED; Excel origin may have leading empty rows')
    }
  }
  rc2_csv(rc2_bind(inventory),file.path(out,'OFFICIAL_WORKBOOK_SHEET_INVENTORY.csv'))
}
rc2_emergency <- function(e) {
  reason <- conditionMessage(e);if(!nzchar(reason))reason<-'Interrupted by user'
  message('Run interrupted: ',reason,'. Completed keyed caches remain available.')
  out <- if(exists('RC2_ACTIVE_OUTPUT',inherits=TRUE)&&nzchar(RC2_ACTIVE_OUTPUT))RC2_ACTIVE_OUTPUT else {
    p<-if(nzchar(RC2_SCRIPT_PATH))dirname(RC2_SCRIPT_PATH) else getwd()
    file.path(p,paste0('PISA_PIRLS_DIAGNOSTIC_',format(Sys.time(),'%Y%m%d_%H%M%S')))
  }
  dir.create(out,recursive=TRUE,showWarnings=FALSE)
  writeLines(c(reason,'No scientific freeze. Rerun the SAME script to resume completed keyed tasks.'),file.path(out,'RUN_INTERRUPTED.txt'))
  if(nzchar(RC2_SCRIPT_PATH)&&!file.exists(file.path(out,'EXECUTED_RC2_DOMAINS_SCRIPT.R')))
    file.copy(RC2_SCRIPT_PATH,file.path(out,'EXECUTED_RC2_DOMAINS_SCRIPT.R'))
  # Only output directory; canonical pupil extracts live elsewhere and are excluded.
  ff<-list.files(out,recursive=TRUE,full.names=TRUE);ff<-ff[!file.info(ff)$isdir]
  ff<-ff[!grepl('\\.(sav|sas7bdat|dta|dat)$',ff,ignore.case=TRUE)]
  zp<-paste0(out,'_DIAGNOSTIC.zip')
  ok <- tryCatch({
    if(!requireNamespace('zip',quietly=TRUE))stop('zip package unavailable')
    wd<-getwd();on.exit(setwd(wd),add=TRUE);setwd(out)
    zip::zipr(zp,files=substring(rc2_norm(ff),nchar(rc2_norm(out))+2L),recurse=FALSE,include_directories=FALSE,mode='mirror')
    TRUE
  },error=function(x){message('Diagnostic folder: ',out,'; ZIP unavailable: ',conditionMessage(x));FALSE})
  if(ok)cat('\nUPLOAD THIS ZIP:\n',zp,'\n',sep='')
  invisible(list(state='INTERRUPTED_NOT_VALIDATED',zip=if(ok)zp else '',output=out,error=reason))
}
rc2_v6_selftest <- function() {
  checks<-list();add<-function(n,ok){if(!isTRUE(ok))stop('V6 selftest: ',n);checks[[length(checks)+1L]]<<-data.frame(check=n,pass=TRUE)}
  x<-c(2,1,9);attr(x,'labels')<-c(Female=2,Male=1,Missing=9)
  z<-rc2_gender_decode(data.frame(ITSEX=I(x)),'TIMSS',2019)
  add('gender_source_labels_not_assumed_numeric',identical(z$value,c('girl','boy',NA_character_)))
  add('gender_unlabelled_codes_not_guessed',all(is.na(rc2_gender_decode(data.frame(ITSEX=c(1,2)),'TIMSS',2019)$value)))
  N<-800L;d<-data.frame(W=1,SES=rep(1:4,each=200),GENDER=rep(rep(c('girl','boy'),each=100),4))
  y<-400+20*(d$GENDER=='boy')+30*d$SES+10*(d$GENDER=='boy')*(d$SES==4)
  t<-rc2_tails_rank(d$SES,d$W);a<-rc2_gender_stats(y,d,d$W,t,c(baseline=450,top=540))
  add('gender_SES_interaction_exact_10_points',abs(a['gender_ses_interaction_mean']-10)<1e-12)
  add('gender_bottom_gap_exact_20_points',abs(a['gender_boy_minus_girl_q1_mean']-20)<1e-12)
  add('gender_top_gap_exact_30_points',abs(a['gender_boy_minus_girl_q4_mean']-30)<1e-12)
  d$GENDER<-NA_character_;a<-rc2_gender_stats(y,d,d$W,t,c(baseline=450,top=540))
  add('unavailable_gender_all_missing_not_zero',all(is.na(a)))
  add('reading_PV_names_numeric_order',identical(rc2_pv_names(paste0('PV',c(10,1:9),'READ'),'PISA','reading',2025),paste0('PV',1:10,'READ')))
  add('gender_proportions_unit',rc2_stat_unit('gender_ses_interaction_low')=='proportion_or_proportion_difference')
  rc2_bind(checks)
}

