rc2_external_mean_check <- function(est,out) {
  anchors <- rc2_official_mean_anchors()
  rc2_csv(anchors,file.path(out,'OFFICIAL_PISA_MEAN_ANCHORS.csv'))
  z <- est[est$survey=='PISA'&est$statistic=='overall_mean',,drop=FALSE]
  if(!nrow(z))return(invisible(NULL))
  clean <- function(x)tolower(gsub('[^A-Za-z0-9]','',x))
  # No inferred country bridges; only exact normalized official names.
  akey<-paste(clean(anchors$country_label),anchors$domain,anchors$year)
  if(anyDuplicated(akey))stop('Ambiguous official anchor keys')
  if(!'country_name_en' %in% names(z))stop('Missing canonical country labels')
  k<-match(paste(clean(z$country_name_en),z$domain,z$year),akey)
  z$official_estimate<-anchors$estimate[k];z$official_se<-anchors$se[k]
  z$official_table<-anchors$table[k];z$official_value_cell<-anchors$value_cell[k]
  z$official_se_cell<-anchors$se_cell[k];z$official_source_sha256<-anchors$source_sha256[k]
  z$estimate_difference<-z$estimate-z$official_estimate;z$se_difference<-z$se-z$official_se
  z$external_check<-ifelse(!is.finite(z$official_estimate)|!is.finite(z$official_se),'ANCHOR_UNAVAILABLE',
    ifelse(is.finite(z$estimate_difference)&is.finite(z$se_difference)&abs(z$estimate_difference)<=.15&abs(z$se_difference)<=.05,
      'NUMERICALLY_CLOSE_PENDING_SCIENTIFIC_REVIEW','DIFFERENCE_REQUIRES_REVIEW'))
  z$check_rule<-'absolute difference <=0.15 score and <=0.05 SE; diagnostic tolerance, not a significance test or release approval'
  rc2_csv(z,file.path(out,'PISA_EXTERNAL_MEAN_SE_CHECKS.csv'))
  invisible(z)
}
rc2_gender_support_table <- function(d,pp,task) {
  t<-rc2_tails_rank(d$SES,d$W);g<-d$GENDER
  masks<-list(girl=as.numeric(!is.na(g)&g=='girl'),boy=as.numeric(!is.na(g)&g=='boy'))
  masks$girl_q1<-masks$girl*t$q1;masks$boy_q1<-masks$boy*t$q1
  masks$girl_q4<-masks$girl*t$q4;masks$boy_q4<-masks$boy*t$q4
  allpv<-Reduce(`&`,lapply(d[pp],is.finite))
  rc2_bind(lapply(names(masks),function(n) {
    w<-d$W*masks[[n]];ok<-is.finite(w)&w>0&allpv
    data.frame(survey=task$survey,year=task$year,source_country_code=task$source_country_code,domain=task$domain,group=n,
      n_positive_members=sum(ok),effective_n=if(any(ok))sum(w[ok])^2/sum(w[ok]^2) else 0,
      weighted_members=sum(w[ok]),n_schools=length(unique(d$SCHOOL[ok&!is.na(d$SCHOOL)&nzchar(d$SCHOOL)])),
      support_definition='positive fractional weight and all required PVs observed; descriptive common-PV support')
  }))
}


