rc2_subset_labels <- function(d, i) {
  z <- d[i,,drop=FALSE]
  for(n in names(d)) for(a in c('label','labels','na_values','na_range')) {
    v <- attr(d[[n]],a,exact=TRUE); if(!is.null(v))attr(z[[n]],a) <- v
  }
  z
}
rc2_csv <- function(x,p) {
  x <- as.data.frame(x,stringsAsFactors=FALSE); rownames(x)<-NULL
  if(!ncol(x))x <- data.frame(status=character())
  for(n in names(x))if(is.factor(x[[n]]))x[[n]]<-as.character(x[[n]])
  dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE)
  tmp <- tempfile('csv_',tmpdir=dirname(p),fileext='.csv')
  on.exit(if(file.exists(tmp))unlink(tmp),add=TRUE)
  sentinel <- '__R_MISSING_VALUE_7__'
  if(any(vapply(x,function(v)is.character(v)&&any(v==sentinel,na.rm=TRUE),logical(1))))stop('CSV NA sentinel collision')
  write.csv(x,tmp,row.names=FALSE,na=sentinel,fileEncoding='UTF-8')
  y <- read.csv(tmp,check.names=FALSE,stringsAsFactors=FALSE,na.strings=sentinel,
    colClasses=vapply(x,function(v)if(is.logical(v))'logical' else if(is.numeric(v))'numeric' else 'character',character(1)),
    fileEncoding='UTF-8',blank.lines.skip=FALSE)
  if(!identical(dim(x),dim(y))||!identical(names(x),names(y)))stop('CSV dimension/name readback failed: ',p)
  for(n in names(x)) {
    a<-x[[n]]; b<-y[[n]]
    ok<-if(is.numeric(a))isTRUE(all.equal(as.numeric(a),b,tolerance=1e-13,check.attributes=FALSE)) else identical(a,b)
    if(!ok)stop('CSV value readback failed: ',p,' / ',n)
  }
  if(file.exists(p)) {
    prior<-rc2_previous_path(p)
    if(!file.rename(p,prior))stop('Cannot preserve previous CSV: ',p)
  }
  if(!file.rename(tmp,p))stop('Atomic CSV commit failed: ',p)
  invisible(p)
}
rc2_gender_decode <- function(raw,survey,year) {
  dic<-rc2_dictionary(raw)
  known<-if(survey=='PISA')if(year==2003L)'ST03Q01' else if(year<=2012L)'ST04Q01' else 'ST004D01T' else c('ITSEX','ASBG01','ASBGSEX')
  cand<-unique(c(intersect(known,names(raw)),dic$variable[grepl('(SEX|GENDER).*(STUDENT|PUPIL)|STUDENT.*(SEX|GENDER)|^SEX$|^GENDER$',toupper(dic$label))]))
  # ST04Q01 in 2003 is mother living at home: explicitly forbidden as gender.
  if(survey=='PISA'&&year==2003L)cand<-setdiff(cand,'ST04Q01')
  found<-list();maps<-character();basis<-character()
  for(v in cand) {
    x<-raw[[v]];labs<-attr(x,'labels',exact=TRUE);method<-'SOURCE_VALUE_LABEL_VERIFIED'
    # Official OECD EDU/WKP(2022)7, PISA2018 input-variable table.
    if((is.null(labs)||!length(labs))&&survey=='PISA'&&year==2018L&&v=='ST004D01T') {
      labs<-c(Female=1,Male=2);method<-'OFFICIAL_OECD_EDU_WKP_2022_7_MAPPING'
    }
    if(is.null(labs))next
    lab<-tolower(trimws(names(labs)))
    g<-ifelse(grepl('^(female|girl|girls)$',lab),'girl',ifelse(grepl('^(male|boy|boys)$',lab),'boy',NA_character_))
    good<-!is.na(g)
    if(sum(good)!=2L||!setequal(g[good],c('girl','boy'))||anyDuplicated(labs[good]))next
    mp<-setNames(g[good],as.character(unname(labs[good])));found[[v]]<-unname(mp[as.character(rc2_num(x))])
    maps[v]<-paste(names(mp),mp,sep='=',collapse=';');basis[v]<-method
  }
  if(!length(found))return(list(value=rep(NA_character_,nrow(raw)),variable=paste(cand,collapse=';'),map='',status='NO_VERIFIED_GENDER_MAPPING'))
  selected<-names(found)[which.max(vapply(found,function(x)sum(!is.na(x)),integer(1)))];res<-found[[selected]]
  for(x in found)if(any(!is.na(res)&!is.na(x)&res!=x))return(list(value=rep(NA_character_,nrow(raw)),variable=paste(names(found),collapse=';'),map=paste(maps,collapse='|'),status='CONFLICTING_GENDER_COLUMNS'))
  list(value=res,variable=selected,map=unname(maps[selected]),status=if(all(is.na(res)))'VERIFIED_VARIABLE_ALL_MISSING' else unname(basis[selected]))
}
rc2_demo_candidates <- function(h) {
  h$variable[grepl('LANG|IMMIG|BIRTH|BORN|BOOK|SEX|GENDER|ISCED|PROGRAM',toupper(paste(h$variable,h$label)))]
}
rc2_label_group <- function(x, pattern, values) {
  labs<-attr(x,'labels',exact=TRUE);out<-rep(NA_character_,length(x))
  if(is.null(labs))return(out)
  mp<-rep(NA_character_,length(labs));lab<-tolower(trimws(names(labs)))
  for(i in seq_along(pattern))mp[grepl(pattern[i],lab)]<-values[i]
  good<-!is.na(mp)
  if(length(unique(mp[good]))<2L)return(out)
  unname(setNames(mp[good],as.character(labs[good]))[as.character(rc2_num(x))])
}
rc2_add_demographics <- function(obj,raw,survey,year,code,outdir) {
  d<-obj$data;stopifnot(nrow(d)==nrow(raw))
  rc2_gender_candidate_audit(raw,survey,year,code,outdir)
  dic<-rc2_dictionary(raw);logs<-list();d$DEMO_LANGUAGE<-NA_character_;d$DEMO_MIGRATION<-NA_character_;d$TEST_LANGUAGE<-NA_character_
  add<-function(dimension,var,group,definition,judgement) {
    obj$data[[paste0('DEMO_',dimension)]]<<-group
    w<-d$W;good<-is.finite(w)&w>0
    logs[[length(logs)+1L]]<<-data.frame(survey=survey,year=year,source_country_code=code,dimension=dimension,variable=var,
      definition=definition,comparability=judgement,weighted_coverage=if(any(good))sum(w[good&!is.na(group)])/sum(w[good]) else NA_real_,
      category=paste(sort(unique(group[!is.na(group)])),collapse=';'))
  }
  obj$data<-d
  if(survey=='PISA') {
    if('IMMIG'%in%names(raw)) {
      g<-rc2_label_group(raw$IMMIG,c('^native','second.gener','first.gener'),c('native','second_generation','first_generation'))
      add('MIGRATION','IMMIG',g,'OECD native/second/first generation; three groups','PISA_WITHIN_CONSTRUCT; cross-survey requires adjudication')
    }
    if('ST022Q01TA'%in%names(raw)) {
      g<-rc2_label_group(raw$ST022Q01TA,c('same.*(test|assess)|language.*(test|assess).*same','another|other language'),c('same','other'))
      add('LANGUAGE','ST022Q01TA',g,'Home language relative to assessment language','ASSESSMENT_LANGUAGE_CONDITIONING_REQUIRED')
    }
    tv<-intersect(c('LANGTEST_COG','LANGTEST','LANGN','STLANG'),names(raw))
    if(length(tv))obj$data$TEST_LANGUAGE<-rc2_chr(raw[[tv[1]]])
  } else {
    cand<-dic$variable[grepl('SPEAK.*HOME|LANGUAGE.*HOME|HOME.*LANGUAGE',toupper(dic$label))]
    if(length(cand)==1L) {
      v<-cand[1];g<-rc2_label_group(raw[[v]],c('^always','^almost always','^sometimes','^never','^always or almost always'),c('always','almost_always','sometimes','never','always_or_almost_always'))
      add('LANGUAGE',v,g,'Original labelled frequency of speaking assessment language at home; categories kept separate','NO_AUTOMATIC_PISA_BINARY_EQUIVALENCE')
    }
    if('ITLANG'%in%names(raw))obj$data$TEST_LANGUAGE<-rc2_chr(raw$ITLANG)
    # Source-label-verified parent birthplace, including ASBG06A/B in TIMSS2015.
    mv<-dic$variable[grepl('MOTHER.*BORN|BORN.*MOTHER',toupper(dic$label))]
    fv<-dic$variable[grepl('FATHER.*BORN|BORN.*FATHER',toupper(dic$label))]
    if(length(mv)==1L&&length(fv)==1L) {
      a<-rc2_label_group(raw[[mv]],c('^yes','^no'),c('yes','no'));b<-rc2_label_group(raw[[fv]],c('^yes','^no'),c('yes','no'))
      g<-ifelse(a=='yes'|b=='yes','one_or_both_parents_born_here',ifelse(a=='no'&b=='no','both_parents_born_abroad',NA_character_))
      sv<-dic$variable[grepl('BORN IN.*COUNTRY|BORN IN <',toupper(dic$label))&!grepl('MOTHER|FATHER|PARENT|AGE|#',toupper(dic$label))]
      definition<-'Both parents born abroad versus at least one born here';judgement<-'PARENT_NATIVITY; NOT_STUDENT_IMMIGRATION'
      vv<-paste(mv,fv,sep='+')
      if(length(sv)==1L) {
        child<-rc2_label_group(raw[[sv]],c('^yes','^no'),c('yes','no'))
        g<-ifelse(g=='one_or_both_parents_born_here','native',ifelse(g=='both_parents_born_abroad'&child=='yes','second_generation',ifelse(g=='both_parents_born_abroad'&child=='no','first_generation',NA_character_)))
        definition<-'Native: at least one parent born here; second: child born here and both parents abroad; first: child and both parents abroad'
        judgement<-'LABEL_VERIFIED_GENERATIONAL_CONSTRUCT; country-border/test-language review required';vv<-paste(vv,sv,sep='+')
      }
      add('MIGRATION',vv,g,definition,judgement)
    }
  }
  for(dim in c('LANGUAGE','MIGRATION'))if(!any(vapply(logs,function(x)x$dimension==dim,logical(1))))
    add(dim,'',rep(NA_character_,nrow(d)),'No verified comparable variable in inspected source','VARIABLE_MAPPING_HOLD; not proven structurally absent')
  rc2_csv(rc2_bind(logs),file.path(outdir,paste0(survey,'_',year,'_',code,'_DEMOGRAPHIC_HARMONISATION.csv')))
  obj$meta$demographic_definitions<-rc2_bind(logs);obj
}
rc2_theil <- function(g,cl,w) {
  ok<-!is.na(g)&!is.na(cl)&nzchar(cl)&is.finite(w)&w>0
  if(sum(ok)<20L)return(NA_real_)
  g<-as.character(g[ok]);cl<-as.character(cl[ok]);w<-w[ok]
  tab<-xtabs(w~cl+g);p<-colSums(tab)/sum(tab);E<--sum(p[p>0]*log(p[p>0]))
  if(E<=1e-12)return(NA_real_)
  W<-rowSums(tab);P<-tab/W;P[P==0]<-1
  within<-sum(W*(-rowSums((tab/W)*log(P))))/sum(W)
  (E-within)/E
}
rc2_supplement_stats <- function(y,d,w,tails,thresholds) {
  out<-numeric()
  # All distribution and proficiency levels accompany social group gaps.
  for(q in c('q1','q4')) {
    ww<-w*tails[[q]];qt<-rc2_quantile(y,ww,c(.1,.5,.9))
    out[paste0(q,c('_p10','_p50','_p90','_p90_p10'))]<-c(qt,qt[3]-qt[1])
  }
  for(g in c('girl','boy')) {
    mask<-!is.na(d$GENDER)&d$GENDER==g&is.finite(y)&is.finite(d$W)&d$W>0;ww<-w*as.numeric(mask);fw<-d$W[mask]
    enough<-sum(mask)>=30L&&length(fw)>0&&sum(fw)^2/sum(fw^2)>=20
    qt<-if(enough)rc2_quantile(y,ww,c(.1,.5,.9)) else rep(NA_real_,3)
    out[paste0('gender_',g,c('_p10','_p50','_p90','_p90_p10'))]<-c(qt,qt[3]-qt[1])
  }
  for(st in c('p10','p50','p90','p90_p10')) {
    out[paste0('gender_boy_minus_girl_',st)]<-out[paste0('gender_boy_',st)]-out[paste0('gender_girl_',st)]
    out[paste0('ses_q4_minus_q1_',st)]<-out[paste0('q4_',st)]-out[paste0('q1_',st)]
  }
  # Alternative hard cutoffs are diagnostics only; main fractional quartiles unchanged.
  if(any(is.finite(d$SES))) {
    cuts<-rc2_quantile(d$SES,w,c(.25,.75))
    out['ses_hard_cut_q1_mean']<-rc2_weighted_mean(y,w*as.numeric(is.finite(d$SES)&d$SES<=cuts[1]))
    out['ses_hard_cut_q4_mean']<-rc2_weighted_mean(y,w*as.numeric(is.finite(d$SES)&d$SES>cuts[2]))
    out['ses_hard_cut_gap']<-out['ses_hard_cut_q4_mean']-out['ses_hard_cut_q1_mean']
  }
  for(dim in c('LANGUAGE','MIGRATION')) {
    g<-d[[paste0('DEMO_',dim)]];if(is.null(g))next
    lev<-sort(unique(g[!is.na(g)]));prefix<-paste0('demo_',tolower(dim),'_')
    good<-is.finite(d$W)&d$W>0&!is.na(g);den<-sum(d$W[good]);published<-length(lev)>=2L
    for(a in lev) {
      mask<-good&g==a;sch<-unique(d$SCHOOL[mask&!is.na(d$SCHOOL)])
      published<-published&&sum(mask)>=100L&&length(sch)>=20L&&sum(d$W[mask])/den>=.05
    }
    for(a in lev) {
      mask<-as.numeric(!is.na(g)&g==a);ww<-w*mask;qt<-if(published)rc2_quantile(y,ww,c(.1,.5,.9)) else rep(NA_real_,3)
      vals<-c(mean=rc2_weighted_mean(y,ww),low=rc2_weighted_mean(ifelse(is.finite(y),as.numeric(y<thresholds['baseline']),NA_real_),ww),
        p10=qt[1],p50=qt[2],p90=qt[3],share=rc2_weighted_mean(ifelse(!is.na(g),as.numeric(g==a),NA_real_),w))
      if(!published)vals[]<-NA_real_
      out[paste0(prefix,a,'_',names(vals))]<-vals
    }
    if(length(lev)>=2L)for(a in lev[-1])for(st in c('mean','low')) {
      out[paste0(prefix,a,'_minus_',lev[1],'_',st)]<-out[paste0(prefix,a,'_',st)]-out[paste0(prefix,lev[1],'_',st)]
    }
    for(cl in c('SCHOOL','CLASS'))out[paste0(prefix,'theil_H_',tolower(cl))]<-if(published)rc2_theil(g,d[[cl]],w) else NA_real_
    # Conditional language sorting does not identify regional-language minorities as migrants.
    if(dim=='LANGUAGE') {
      tl<-d$TEST_LANGUAGE;valid<-!is.na(tl)&!is.na(g)&w>0
      v<-NA_real_
      if(any(valid)) {
        parts<-split(which(valid),tl[valid]);E<-W<-H<-numeric()
        for(j in seq_along(parts)){ix<-parts[[j]];pg<-tapply(w[ix],g[ix],sum);pg<-pg/sum(pg);E[j]<--sum(pg*log(pg));W[j]<-sum(w[ix]);H[j]<-rc2_theil(g[ix],d$SCHOOL[ix],w[ix])}
        use<-is.finite(H)&E>0;if(any(use)&&all(is.finite(H[E>0])))v<-sum(W[use]*E[use]*H[use])/sum(W[use]*E[use])
      }
      out[paste0(prefix,'theil_H_school_within_assessment_language')]<-if(published)v else NA_real_
    }
  }
  out
}
# Reuse inherited survey estimators; add missing families, avoid rerunning core.
rc2_pv_stats <- function(y,d,w,tails,thresholds) {
  mode<-if('REPAIR_MODE'%in%names(d))d$REPAIR_MODE[1] else 'full'
  core<-if(mode=='full'&&!isTRUE(d$GENDER_ONLY[1]))rc2_core_pv_stats(y,d,w,tails,thresholds) else numeric()
  gender<-if(mode%in%c('full','gender_supplement','pirls_supplement'))rc2_gender_stats(y,d,w,tails,thresholds) else numeric()
  c(core,gender,rc2_supplement_stats(y,d,w,tails,thresholds))
}
# Input tasks are separately canonicalised; this wrapper only decorates private
# canonical copies. It never modifies V6 extracts/caches.
rc2_worker_v6 <- rc2_worker
rc2_worker <- function(task) {
  result<-rc2_worker_v6(task)
  if(!nrow(result$estimates))return(result)
  e<-result$estimates
  if(task$mode!='full')e<-e[grepl('^gender_|^demo_|^q[14]_p|^ses_',e$statistic),,drop=FALSE]
  if(task$mode=='supplement')e<-e[!grepl('^gender_.*_(mean|low|top)$',e$statistic),,drop=FALSE]
  e$module[grepl('^demo_',e$statistic)]<-'demographic_supplement'
  e$module[grepl('^q[14]_p',e$statistic)]<-'ses_distribution_supplement'
  e$quality_status<-'PENDING_GROUP_SUPPORT_POPULATION_AND_EXTERNAL_REVIEW'
  e$unit[grepl('theil_H|_share$|_low$',e$statistic)]<-'proportion_or_proportion_difference'
  e$source_limitation[grepl('^gender_.*_p',e$statistic)&!is.finite(e$estimate)]<-'GENDER_SOURCE_OR_SUPPORT_UNAVAILABLE'
  # PIRLS baseline is Intermediate 475 and top Advanced 625; corrected below in estimator.
  result$estimates<-e
  a<-result$replicate_aggregates
  if(task$mode=='full'&&!is.null(a)&&'overall_mean'%in%colnames(a$full)) {
    k<-match('overall_mean',colnames(a$full));theta<-a$full[,k];U<-vapply(seq_along(theta),function(m)a$variance_factor*sum((a$replicate_estimates[,m,k]-theta[m])^2),numeric(1))
    B<-(1+1/length(theta))*var(theta)
    result$variance_sensitivity<-data.frame(survey=task$survey,year=task$year,source_country_code=task$source_country_code,domain=task$domain,main_all_PV_SE=sqrt(mean(U)+B),diagnostic_first_PV_sampling_SE=sqrt(U[1]+B),rule='DIAGNOSTIC_ONLY; all PV sampling remains main')
  }
  result
}
rc2_pv_names_v6<-rc2_pv_names
rc2_pv_names<-function(n,survey,domain,year) {
  if(survey!='PIRLS')return(rc2_pv_names_v6(n,survey,domain,year))
  z<-grep('^ASRREA0[1-5]$',n,value=TRUE);if(length(z)==5L)sort(z) else character()
}
rc2_canonical_v6<-rc2_canonical
rc2_canonical<-function(raw,survey,year,code) {
  original<-nrow(raw);rule<-'entire_source_reporting_unit'
  if(survey=='TIMSS'&&year==1995L) {
    if(!'IDGRADER'%in%names(raw))stop('1995 relative-grade IDGRADER missing; national grade must not be guessed')
    keep<-if(code=='AUS')rc2_num(raw$IDGRADE)==4 else rc2_num(raw$IDGRADER)==2
    if(anyNA(keep)||!any(keep))stop('1995 target-grade identification failed')
    raw<-rc2_subset_labels(raw,keep);rule<-if(code=='AUS')'1995_AUS_grade4_trend_target; original upper target retained in audit' else '1995_IDGRADER_2_upper_target'
  }
  # Bypass obsolete grade==4 heuristic by its temporary year argument; restore metadata.
  obj<-rc2_canonical_v6(raw,if(survey=='PIRLS')'TIMSS' else survey,if(year==1995L)1996L else year,code)
  obj$meta$survey<-survey;obj$meta$year<-year;obj$meta$n_original<-original
  obj$meta$n_excluded_population<-original-nrow(raw);obj$meta$population_rule<-rule
  if(survey=='TIMSS'&&year==1995L)obj$meta$population_status<-'G4_TARGET_RELATIVE_GRADE_VERIFIED; TREND_SCALE_3PL'
  if(survey=='PIRLS') {
    pp<-rc2_pv_names(names(raw),'PIRLS','reading',year)
    if(length(pp)!=5L)stop('PIRLS five reading PVs required')
    for(j in 1:5)obj$data[[paste0('PV_READ_',j)]]<-rc2_num(raw[[pp[j]]])
    obj$data$GENDER_ONLY<-TRUE;obj$meta$population_status<-'PIRLS_EXISTING_MAIN_TARGET_REGISTRY'
  }
  attr(obj,'selected_raw')<-raw;obj
}
rc2_attach_and_drop <- function(obj,survey,year,code,outdir) {
  raw<-attr(obj,'selected_raw');attr(obj,'selected_raw')<-NULL
  rc2_add_demographics(obj,raw,survey,year,code,outdir)
}
rc2_fetch_verified <- function(url,path,sha='') {
  pins<-rc2_source_pins();if(!nzchar(sha)&&basename(path)%in%names(pins))sha<-unname(pins[basename(path)])
  if(file.exists(path)&&file.info(path)$size>0) {
    if(nzchar(sha)&&rc2_sha(path)!=sha)stop('Cached official payload hash differs: ',path)
    return(path)
  }
  if(!isTRUE(getOption('pisa.rc2.download',TRUE)))stop('Official source absent; download disabled: ',url)
  dir.create(dirname(path),recursive=TRUE,showWarnings=FALSE);tmp<-paste0(path,'.partial')
  on.exit(if(file.exists(tmp))unlink(tmp),add=TRUE)
  utils::download.file(url,tmp,mode='wb',quiet=TRUE)
  if(!file.exists(tmp)||file.info(tmp)$size==0)stop('Empty official download')
  if(nzchar(sha)&&rc2_sha(tmp)!=sha)stop('Official source changed versus audited SHA256; retained HOLD')
  if(grepl('\\.zip$',path,ignore.case=TRUE))rc2_zip_index(tmp)
  if(!file.rename(tmp,path))stop('Download commit failed');path
}
rc2_rescale1995 <- function(raw,code,sources) {
  oldcode<-switch(code,CZE='CSK',ENG='GBR',code)
  nm<-paste0('ASV',oldcode,'1.zip');url<-paste0('https://timss.bc.edu/timss1995i/newscale/pop1/',nm)
  zp<-rc2_fetch_verified(url,file.path(sources,nm));zi<-rc2_zip_index(zp)
  hit<-which(toupper(basename(zi$Name))==paste0('ASV',oldcode,'1.DAT'))
  if(length(hit)!=1L)stop('1995 newscale member ambiguous')
  f<-rc2_extract(zp,zi$Name[hit],file.path(sources,'private_newscale'),zi$Length[hit])
  ln<-readLines(f,warn=FALSE);starts<-c(1,6,seq(21,49,7),seq(201,229,7));ends<-c(5,15,seq(27,55,7),seq(207,235,7))
  a<-as.data.frame(lapply(seq_along(starts),function(j)suppressWarnings(as.numeric(trimws(substr(ln,starts[j],ends[j]))))))
  names(a)<-c('IDCNTRY','IDSTUD',paste0('ASMMAT0',1:5),paste0('ASSSCI0',1:5))
  # Exact country-ID changes observed between official 1995 newscale and IEA SAV release.
  oldids<-c(CZE=200,ENG=826,SCO=827,SVN=890);newids<-c(CZE=203,ENG=926,SCO=927,SVN=705)
  if(code%in%names(oldids)) {
    if(!identical(unique(a$IDCNTRY),unname(oldids[code]))||!identical(unique(rc2_num(raw$IDCNTRY)),unname(newids[code])))stop('1995 documented country-ID bridge does not match actual sources')
    a$IDCNTRY[]<-unname(newids[code])
  }
  key<-function(d)paste(rc2_num(d$IDCNTRY),rc2_num(d$IDSTUD),sep=':')
  ka<-key(a);kr<-key(raw);if(anyDuplicated(ka)||anyDuplicated(kr))stop('1995 rescale duplicate student keys')
  ix<-match(kr,ka);if(anyNA(ix)||length(ka)!=length(kr))stop('1995 rescale join not one-to-one complete')
  for(v in names(a)[-(1:2)])raw[[v]]<-a[[v]][ix]
  if(!'JKREP'%in%names(raw)&&'JKINDIC'%in%names(raw))raw$JKREP<-raw$JKINDIC
  attr(raw,'newscale_sha256')<-rc2_sha(zp);attr(raw,'newscale_url')<-url;raw
}
rc2_prepare_iea <- function(rec,cache_root,outdir,sources,numeracy=NULL) {
  tasks<-errors<-list()
  for(code in sort(unique(rec$source_country_code))) {
    z<-rec[rec$source_country_code==code,,drop=FALSE];year<-z$year[1]
    ans<-tryCatch({
      if(any(z$source_conflict))stop('Conflicting official source payloads')
      g<-z[z$role=='G',,drop=FALSE];if(nrow(g)!=1L)stop('Exactly one ASG main file required')
      h<-rc2_header(g$path);bv<-rc2_books_var(h)
      keep<-h$upper%in%c('IDCNTRY','IDSCHOOL','IDCLASS','IDSTUD','IDSTUDS','TOTWGT','JKZONE','JKREP','JKINDIC','ASDAGE','ASDGAGE','ASBGAGE','AGE','IDGRADE','IDGRADER','GRADE','ITSEX','ASBG01',bv)|grepl('^(ASMMAT|ASSSCI)0[1-5]$',h$upper)|h$variable%in%rc2_demo_candidates(h)
      raw<-rc2_read_selected(g$path,h$variable[keep]);raw<-as.data.frame(lapply(raw,rc2_clean_labeled))
      extra_sha<-''
      if(year==1995L){raw<-rc2_rescale1995(raw,code,sources);extra_sha<-attr(raw,'newscale_sha256')}
      dic<-rc2_dictionary(raw);rc2_csv(dic,file.path(outdir,paste0('TIMSS_',year,'_',code,'_DICTIONARY.csv')))
      for(dom in if(grepl('N1\\.SAV$',toupper(g$path)))'mathematics' else c('mathematics','science')) {
        rd<-raw
        if(year==2015L&&dom=='mathematics'&&code%in%c('BHR','IDN','IRN','KWT','MAR','ABA')&&!grepl('N1\\.SAV$',toupper(g$path))) {
          if(is.null(numeracy)||!code%in%names(numeracy)) {
            errors[[length(errors)+1L]]<-data.frame(survey='TIMSS',year=year,source_country_code=code,domain=dom,status='INPUT_HOLD',reason='Numeracy companion missing; combined mathematics withheld; independent science continues')
            next
          }
          nr<-rc2_read_selected(numeracy[[code]],names(raw));nr<-as.data.frame(lapply(nr,rc2_clean_labeled))
          rd<-rc2_bind(list(raw,nr));for(v in names(raw))for(a in c('label','labels'))attr(rd[[v]],a)<-attr(raw[[v]],a)
          extra_sha<-rc2_sha(numeracy[[code]])
        }
        obj<-rc2_canonical(rd,'TIMSS',year,code);obj<-rc2_attach_and_drop(obj,'TIMSS',year,code,outdir)
        mode<-if(grepl('N1\\.SAV$',toupper(g$path))||year==1995L||(year==2015L&&dom=='mathematics'&&code%in%c('BHR','IDN','IRN','KWT','MAR','ABA')))'full' else 'supplement'
        obj$data$REPAIR_MODE<-mode
        ik<-digest::digest(c(sort(z$payload_sha256),extra_sha,dom,RC2_REPAIR_SCHEMA),algo='sha256')
        obj$input_key<-ik;obj$meta$source_sha256<-paste(c(unique(z$source_sha256),extra_sha),collapse=';')
        obj$meta$source_path<-paste(unique(z$source_path),collapse=';');obj$meta$source_member<-paste(z$member,collapse=';')
        dest<-file.path(cache_root,paste0('TIMSS_',year,'_',code,'_',dom,'_',substr(ik,1,16),'.rds'))
        if(!file.exists(dest))rc2_save(obj,dest) else if(!identical(readRDS(dest),obj))stop('Canonical cache content differs for same key')
        tasks[[length(tasks)+1L]]<-data.frame(survey='TIMSS',year=year,source_country_code=code,domain=dom,path=dest,input_key=ik,mode=mode)
      }
      TRUE
    },error=function(e)e)
    if(inherits(ans,'error'))errors[[length(errors)+1L]]<-data.frame(survey='TIMSS',year=year,source_country_code=code,status='INPUT_HOLD',reason=conditionMessage(ans))
  }
  list(tasks=rc2_bind(tasks),errors=rc2_bind(errors))
}
rc2_numeracy_sources <- function(inv,sources) {
  zp<-rc2_pick_file(inv,'^(TN15_SPSSData|TIMSS2015.*NUMERACY.*SPSS).*\\.zip$')
  if(!nzchar(zp))zp<-rc2_fetch_verified('https://timssandpirls.bc.edu/timss2015/international-database/downloads/TN15_SPSSData.zip',file.path(sources,'TN15_SPSSData.zip'))
  zi<-rc2_zip_index(zp);zi<-zi[grepl('^ASG[A-Z0-9]{3}N1\\.SAV$',toupper(basename(zi$Name))),,drop=FALSE]
  ans<-list();for(i in seq_len(nrow(zi))) {
    code<-substr(toupper(basename(zi$Name[i])),4,6)
    ans[[code]]<-rc2_extract(zp,zi$Name[i],file.path(sources,'private_numeracy'),zi$Length[i])
  };ans
}
rc2_relocate <- function(path,root) {
  if(file.exists(path))return(rc2_norm(path))
  tail<-sub('^.*PISA_PIRLS_MASTER_PIPELINE[/\\\\]','',path)
  p<-file.path(root,gsub('\\\\','/',tail));if(file.exists(p))return(rc2_norm(p))
  hits<-list.files(root,pattern=paste0('^',gsub('([.()+])','\\\\\\1',basename(path)),'$'),recursive=TRUE,full.names=TRUE)
  if(length(hits)==1L)return(rc2_norm(hits))
  if(length(hits)>1L&&length(unique(vapply(hits,rc2_sha,character(1))))==1L)return(rc2_norm(hits[1]))
  stop('Source path cannot be resolved uniquely from existing project: ',basename(path))
}
rc2_prepare_pirls <- function(root,cache,outdir) {
  files<-list.files(root,pattern='^PIRLS_dashboard_target_population_audit\\.csv$',recursive=TRUE,full.names=TRUE)
  if(!length(files))stop('Existing PIRLS target-population registry absent')
  frames<-lapply(files,function(f)read.csv(f,check.names=FALSE,stringsAsFactors=FALSE))
  for(a in frames)if(!all(c('year','local_path','exclude_dashboard')%in%names(a)))stop('PIRLS target registry schema mismatch')
  # Compare scientifically relevant registry rows, not timestamps.
  keys<-vapply(frames,function(a)digest::digest(a[c('year','local_path','exclude_dashboard')],algo='sha256'),character(1))
  if(length(unique(keys))>1L)stop('Conflicting PIRLS target registries; no latest-file-wins selection')
  a<-frames[[1]];excluded<-toupper(as.character(a$exclude_dashboard))%in%c('TRUE','T','1','YES')
  rc2_csv(a,file.path(outdir,'PIRLS_TARGET_REGISTRY_PRESERVED.csv'));a<-a[!excluded,,drop=FALSE]
  if(!'source_country_code'%in%names(a))a$source_country_code<-substr(toupper(basename(a$local_path)),4,6)
  tasks<-errors<-list()
  for(i in seq_len(nrow(a))) {
    year<-as.integer(a$year[i]);code<-toupper(a$source_country_code[i])
    ans<-tryCatch({
      p<-rc2_relocate(a$local_path[i],root)
      if(!grepl('R[1-5]\\.SAV$',toupper(p)))stop('PIRLS source is not the approved R1-R5 main-study file')
      h<-rc2_header(p);bv<-rc2_books_var(h)
      keep<-h$upper%in%c('IDCNTRY','IDSCHOOL','IDCLASS','IDSTUD','IDSTUDS','TOTWGT','JKZONE','JKREP','ASDAGE','ASDGAGE','ASBGAGE','AGE','IDGRADE','ITSEX','ASBG01','ASBGSEX',bv)|grepl('^ASRREA0[1-5]$',h$upper)|h$variable%in%rc2_demo_candidates(h)
      raw<-rc2_read_selected(p,h$variable[keep]);raw<-as.data.frame(lapply(raw,rc2_clean_labeled))
      rc2_csv(rc2_dictionary(raw),file.path(outdir,paste0('PIRLS_',year,'_',code,'_DICTIONARY.csv')))
      obj<-rc2_canonical(raw,'PIRLS',year,code);obj<-rc2_attach_and_drop(obj,'PIRLS',year,code,outdir)
      obj$data$REPAIR_MODE<-if(year<2016L)'full' else 'pirls_supplement';sha<-rc2_sha(p);ik<-digest::digest(c(sha,RC2_REPAIR_SCHEMA),algo='sha256')
      obj$input_key<-ik;obj$meta$source_sha256<-sha;obj$meta$source_path<-p
      dest<-file.path(cache,paste0('PIRLS_',year,'_',code,'_',substr(ik,1,16),'.rds'))
      if(!file.exists(dest))rc2_save(obj,dest) else if(!identical(readRDS(dest),obj))stop('PIRLS canonical cache differs')
      rc2_replicate_design(obj$data,'PIRLS',year)
      data.frame(survey='PIRLS',year=year,source_country_code=code,domain='reading',path=dest,input_key=ik,mode=if(year<2016L)'full' else 'pirls_supplement')
    },error=function(e)e)
    if(inherits(ans,'error'))errors[[length(errors)+1L]]<-data.frame(survey='PIRLS',year=year,source_country_code=code,status='INPUT_HOLD',reason=conditionMessage(ans)) else tasks[[length(tasks)+1L]]<-ans
  }
  list(tasks=rc2_bind(tasks),errors=rc2_bind(errors))
}
rc2_design_original<-rc2_replicate_design
rc2_replicate_design<-function(d,survey,year) {
  x<-rc2_design_original(d,survey,year)
  if(survey=='PIRLS')x$method<-if(year<2016L)'PIRLS_JRR_ONE_PER_ZONE' else 'PIRLS_JRR_TWO_PER_ZONE'
  x
}
rc2_locate_baseline <- function(root) {
  ff<-list.files(file.path(root,'20_rc2_domains','runs'),pattern='^RC2_AGGREGATE_OUTPUT_MASTER\\.rds$',recursive=TRUE,full.names=TRUE)
  if(!length(ff))stop('No existing V6 aggregate master found in project; input not silently reconstructed from truncated CSV')
  candidates<-list()
  for(f in ff) {
    x<-tryCatch(readRDS(f),error=function(e)NULL)
    if(is.null(x)||!identical(x$metadata$script_sha256,RC2_BASELINE_SHA))next
    if(!is.data.frame(x$estimates)||nrow(x$estimates)!=127471L||!is.data.frame(x$task_status)||nrow(x$task_status)!=2078L)next
    candidates[[f]]<-x
  }
  if(!length(candidates))stop('No baseline matches the audited V6 script, 127471 estimates and 2078 tasks')
  signatures<-vapply(candidates,function(x)digest::digest(x$estimates,algo='sha256'),character(1))
  if(length(unique(signatures))>1L)stop('Conflicting baseline V6 masters; explicit reconciliation needed')
  p<-names(candidates)[1];x<-candidates[[1]]
  script<-file.path(dirname(p),'EXECUTED_RC2_DOMAINS_SCRIPT.R')
  if(!file.exists(script)||rc2_sha(script)!=RC2_BASELINE_SHA)stop('Baseline executed script provenance mismatch')
  k<-with(x$estimates,paste(survey,year,source_country_code,domain,statistic,sep='|'))
  if(anyDuplicated(k))stop('Baseline result keys duplicated')
  list(path=p,master=x,sha=rc2_sha(p),directory=dirname(p))
}
rc2_merge_repaired <- function(old,new) {
  key<-function(x)with(x,paste(survey,year,source_country_code,domain,statistic,sep='|'))
  ko<-key(old);kn<-key(new)
  if(anyDuplicated(kn))stop('Duplicate repair output keys')
  old$lineage<-'V6_PRESERVED';new$lineage<-'V8_REPAIRED_OR_ADDED'
  out<-rc2_bind(list(old[!ko%in%kn,,drop=FALSE],new))
  change<-merge(old,new,by=c('survey','year','source_country_code','domain','statistic'),suffixes=c('_v6','_v7'))
  if(nrow(change)){change$estimate_change<-change$estimate_v7-change$estimate_v6;change$se_change<-change$se_v7-change$se_v6}
  preserved<-out[out$lineage=='V6_PRESERVED',names(old),drop=FALSE]
  expected<-old[!ko%in%kn,,drop=FALSE];rownames(preserved)<-rownames(expected)<-NULL
  if(!identical(preserved,expected))stop('Loss gate: untouched V6 cells changed')
  list(estimates=out,changes=change,preserved=nrow(preserved),replaced=sum(ko%in%kn),added=sum(!kn%in%ko))
}
rc2_known_unavailable <- function()data.frame(survey=c('PISA','PISA','PISA'),year=c(2018L,2018L,2025L),
  source_country_code=c('VNM','VNM','UZB'),domain=c('mathematics','science','mathematics'),
  reason=c('OECD performance not internationally comparable in PISA2018','OECD performance not internationally comparable in PISA2018','OECD withheld mathematics due comparability inconsistencies in PISA2025'),
  evidence=c('https://www.oecd.org/en/publications/pisa-2018-results-volume-i_5f07c754-en.html','https://www.oecd.org/en/publications/pisa-2018-results-volume-i_5f07c754-en.html','https://www.oecd.org/en/publications/pisa-2025-results-volume-i_73451bc5-en/full-report/reader-s-guide_0364240f.html'))
rc2_semantic_checks <- function(e) {
  checks<-list();add<-function(n,pass,detail='')checks[[length(checks)+1L]]<<-data.frame(check=n,pass=isTRUE(pass),detail=as.character(detail))
  k<-with(e,paste(survey,year,source_country_code,domain,statistic,sep='|'))
  add('unique_estimate_keys',!anyDuplicated(k),nrow(e))
  good<-is.finite(e$estimate);add('finite_estimates_have_complete_replication',all(e$complete_replication[good]&is.finite(e$se[good])))
  j<-is.finite(e$se)&is.finite(e$total_variance);add('SE_squared_equals_total_variance',all(abs(e$se[j]^2-e$total_variance[j])<1e-8))
  bounded<-grepl('sorting_share',e$statistic)&good;add('variance_shares_0_100',all(e$estimate[bounded]>=-1e-8&e$estimate[bounded]<=100+1e-8))
  prop<-grepl('^overall_(baseline|top|ge[0-9]+)$|theil_H',e$statistic)&good;add('proportions_0_1',all(e$estimate[prop]>=-1e-8&e$estimate[prop]<=1+1e-8))
  ids<-unique(e[c('survey','year','source_country_code','domain')]);keys<-with(ids,paste(survey,year,source_country_code,domain,sep='|'))
  ek<-with(e,paste(survey,year,source_country_code,domain,sep='|'))
  failures<-list()
  for(i in seq_along(keys)) {
    z<-e[ek==keys[i],,drop=FALSE];v<-setNames(z$estimate,z$statistic)
    if(all(c('q4_mean','q1_mean','score_gap')%in%names(v))&&all(is.finite(v[c('q4_mean','q1_mean','score_gap')]))&&abs(v['q4_mean']-v['q1_mean']-v['score_gap'])>1e-8)failures[[length(failures)+1L]]<-data.frame(key=keys[i],identity='SES level-gap identity')
    if(all(c('p10','p50','p90')%in%names(v))&&all(is.finite(v[c('p10','p50','p90')]))&&any(diff(v[c('p10','p50','p90')])<0))failures[[length(failures)+1L]]<-data.frame(key=keys[i],identity='quantile monotonicity')
  }
  add('group_level_gap_and_quantile_identities',!length(failures),length(failures))
  oo<-e[e$statistic=='overall_mean',,drop=FALSE];ku<-rc2_known_unavailable()
  kk<-function(z)with(z,paste(survey,year,source_country_code,domain,sep='|'))
  unexpected<-oo[!is.finite(oo$estimate)&!kk(oo)%in%kk(ku),,drop=FALSE]
  add('no_unexplained_missing_overall_means',nrow(unexpected)==0L,nrow(unexpected))
  list(checks=rc2_bind(checks),identity_failures=rc2_bind(failures),unexpected_missing=unexpected)
}
rc2_output_zip <- function(out,zipfile) {
  ff<-rc2_output_files(out)
  rel<-substring(rc2_norm(ff),nchar(rc2_norm(out))+2L)
  if(any(grepl('(^|/)(cache|extracts|private)|\\.(sav|zsav|sas7bdat|dat|dta)$',rel,ignore.case=TRUE)))stop('Microdata type/private directory in handoff')
  rds<-ff[grepl('\\.rds$',ff,ignore.case=TRUE)]
  for(f in rds){a<-readRDS(f);if(basename(f)=='COMPLETION_AGGREGATE_MASTER.rds'){if(!is.list(a)||!all(c('metadata','estimates','task_status')%in%names(a)))stop('Invalid aggregate master')} else {if(!grepl('/aggregate_replicates/',rc2_norm(f),fixed=TRUE))stop('Unapproved RDS path');rc2_assert_aggregate_cache(a)}}
  manifest<-data.frame(file=rel,bytes=as.numeric(file.info(ff)$size),sha256=vapply(ff,rc2_sha,character(1)))
  rc2_csv(manifest,file.path(out,'MANIFEST_SHA256.csv'))
  ff<-c(ff,file.path(out,'MANIFEST_SHA256.csv'));rel<-c(rel,'MANIFEST_SHA256.csv')
  dir.create(dirname(zipfile),recursive=TRUE,showWarnings=FALSE)
  wd<-getwd();on.exit(setwd(wd),add=TRUE);setwd(out)
  zip::zipr(zipfile,rel,recurse=FALSE,include_directories=FALSE,mode='mirror');setwd(wd)
  zl<-rc2_zip_index(zipfile);if(!setequal(zl$Name,rel)||sum(zl$Length)!=sum(file.info(ff)$size))stop('ZIP inventory verification failed')
  tmp<-tempfile('zip_verify_');dir.create(tmp);on.exit(unlink(tmp,recursive=TRUE),add=TRUE)
  utils::unzip(zipfile,exdir=tmp)
  if(!identical(unname(vapply(file.path(tmp,manifest$file),rc2_sha,character(1))),unname(manifest$sha256)))stop('ZIP readback SHA256 mismatch')
  zipfile
}
rc2_compare_expanded <- function(e,out) {
  a<-rc2_expanded_anchors();rc2_csv(a,file.path(out,'OFFICIAL_EXPANDED_ANCHORS.csv'))
  alias<-c('Korea, Rep. of'='Korea','Korea, Republic of'='Korea','Russian Federation'='Russia','Hong Kong SAR'='Hong Kong (China)',
    'Iran, Islamic Rep. of'='Iran','Slovak Republic'='Slovakia','Czech Republic'='Czechia')
  clean<-function(x){x<-trimws(x);j<-x%in%names(alias);x[j]<-unname(alias[x[j]]);x}
  a$name_match<-clean(a$country_label);e$name_match<-clean(e$country_name_en)
  z<-merge(e,a,by=c('survey','year','domain','statistic','name_match'),suffixes=c('','_anchor'))
  z$estimate_difference<-z$estimate-z$official_estimate;z$se_difference<-z$se-z$official_se
  z$check_status<-ifelse(!is.finite(z$estimate),'MICRODATA_UNAVAILABLE_OFFICIAL_AGGREGATE_AVAILABLE',
    ifelse(abs(z$estimate_difference)<=z$estimate_tolerance&abs(z$se_difference)<=z$se_tolerance,'NUMERICALLY_CLOSE','REVIEW_REQUIRED'))
  z$check_status[z$kind=='OECD_QUARTILES_VS_PROJECT_FRACTIONAL_QUARTILES_DIAGNOSTIC'&z$check_status=='REVIEW_REQUIRED']<-'ESTIMAND_DIAGNOSTIC_REVIEW; FRACTIONAL_VS_OECD_QUARTILES'
  z$check_status[z$kind=='MULTILEVEL_VS_DESCRIPTIVE_VARIANCE_ESTIMAND_DIAGNOSTIC']<-'DIFFERENT_ESTIMATORS_REPORTED; NOT_AN_EXACT_REPLICATION_TEST'
  rc2_csv(z,file.path(out,'EXPANDED_EXTERNAL_CHECKS.csv'));z
}
rc2_baseline_cache_audit <- function(root,baseline,out) {
  p<-file.path(baseline$directory,'TASK_MANIFEST.csv')
  if(!file.exists(p))return(data.frame(status='V6_TASK_MANIFEST_MISSING; master preserved, private caches not reused'))
  t<-read.csv(p,stringsAsFactors=FALSE);status<-list()
  m<-baseline$master$estimates;mk<-with(m,paste(survey,year,source_country_code,domain,sep='|'));mi<-split(seq_len(nrow(m)),mk)
  for(i in seq_len(nrow(t))) {
    ans<-tryCatch({
      f<-rc2_relocate(t$result_cache[i],root);x<-readRDS(f)
      token<-digest::digest(c(t$input_key[i],t$domain[i],RC2_BASELINE_SHA),algo='sha256')
      if(!identical(x$token,token))stop('V6 cache token mismatch')
      # Numeric cache-vs-master comparison; no filename-only trust.
      z<-m[mi[[paste(t$survey[i],t$year[i],t$source_country_code[i],t$domain[i],sep='|')]],,drop=FALSE]
      a<-x$estimates;ix<-match(a$statistic,z$statistic)
      if(anyNA(ix)||!isTRUE(all.equal(a$estimate,z$estimate[ix],tolerance=0))||!isTRUE(all.equal(a$se,z$se[ix],tolerance=0)))stop('V6 cache differs from audited master')
      'TOKEN_AND_AGGREGATE_VALUES_VERIFIED'
    },error=function(e)paste0('CACHE_NOT_REUSED: ',conditionMessage(e)))
    status[[i]]<-data.frame(survey=t$survey[i],year=t$year[i],source_country_code=t$source_country_code[i],domain=t$domain[i],status=ans)
  }
  z<-rc2_bind(status);rc2_csv(z,file.path(out,'V6_RESULT_CACHE_AUDIT.csv'));z
}
rc2_scope_status <- function()data.frame(
  component=c('Reading core PIRLS/PISA','Math/science core both ages','SES levels/gaps/distribution','Gender levels/gaps/gender x SES','Language/migration group outcomes and sorting','School and classroom sorting','International ESCS','International panels/ranks/uncertainty','Age/cohort timing','Quality/participation','Institutional tracking context','Products and user slide edits'),
  existing=c('RC1 retained with explicit demographic JRR correction','V6 full international estimates; 27 NL means externally checked','V6 national ESCS/books tails, levels and gaps','V6 incomplete due importer; PIRLS missing','RC1 partial; domain extension absent','V6 both PISA specs and IEA classroom estimates','Official OECD tables available','V6 candidate panels; scientific eligibility review outstanding','Separate TIMSS candidate plan exists','RC1 conditional; official TIMSS/PISA sources collected','Hypothesis/required fields locked; complete registry not proven','User products authoritative; preserved byte for byte'),
  this_run=c('No replacement; missing reading supplements only','Repair TIMSS1995, TIMSS2015 combined sample; review remaining SE','Add Q1/Q4 distributions; retained core compared to official groups','Repair source mappings; add historical PISA and PIRLS plus gender distributions','Label-verified group levels, gaps, distributions, multigroup Theil-H; explicit mapping holds','Retain both; mathematical checks; no unapproved main reclassification','Export traceable official anchors, not substitute national tails','Export aggregates for later eligibility/rank inference; existing panels not silently updated','Export existing candidate plan and weighted-age diagnostics','Source and target audits; publication remains conditional','No invented selection-age values; remaining non-R source synthesis recorded','No slide/dashboard modifications in step1'),
  remaining=c('Final cross-product integration step2/3','Full local run and external review','Scientific group support and sensitivity review','Local microdata run; official fallback where source suppressed','Cross-survey equivalence/multilingual adjudication','Unresolved main-spec approval and estimator-vs-OECD distinction','International-group panel integration step2','Freeze memberships and calculate/display uncertainty step2','Pre-result timing adjudication, no raw cross-test differences','All-country quality registry completion','Complete wave-specific selection/tracking registry; association only','Integrate after repaired results validated'),stringsAsFactors=FALSE)
rc2_main <- function() {
  oldopt<-options(stringsAsFactors=FALSE,digits=17,timeout=max(600,getOption('timeout',60)))
  on.exit(options(oldopt),add=TRUE)
  Sys.setenv(OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1',VECLIB_MAXIMUM_THREADS='1')
  RNGkind("L'Ecuyer-CMRG");set.seed(20260925)
  for(p in c('digest','haven','tidyselect','zip'))rc2_package(p)
  if(!nzchar(RC2_SCRIPT_PATH))stop('Run with source(file.choose()) so the executed file is identifiable')
  rc2_verify_execution()
  RC2_SCRIPT_SHA<<-rc2_sha(RC2_SCRIPT_PATH)
  root<-rc2_find_root();baseline<-rc2_locate_baseline(root)
  base<-file.path(root,'22_completion_final_v8');stamp<-format(Sys.time(),'%Y%m%d_%H%M%S')
  out<-file.path(base,'runs',paste0('run_',stamp));if(dir.exists(out))stop('Run already exists; no overwrite')
  cache<-file.path(base,'cache',substr(rc2_compute_sha,1,16));sources<-file.path(base,'sources')
  for(d in c(out,cache,sources,file.path(out,'dictionaries')))dir.create(d,recursive=TRUE,showWarnings=FALSE)
  RC2_LOG<<-file.path(out,'RUN_LOG.txt');RC2_ACTIVE_OUTPUT<<-out;RC2_ACTIVE_ROOT<<-root
  rc2_log('Final V8; validated existing estimates retained; independent tasks continue after holds')
  rc2_log('Source script SHA256: ',RC2_SCRIPT_SHA)
  rc2_init_run(base,out)
  dict<-file.path(out,'dictionaries')
  rc2_csv(rc2_scope_status(),file.path(out,'REMAINING_SCOPE_STATUS.csv'))
  rc2_csv(rc2_pair_plan(),file.path(out,'TIMSS_PAIR_PLAN_UNCHANGED_CANDIDATES.csv'))
  rc2_csv(rc2_known_unavailable(),file.path(out,'DOCUMENTED_UNAVAILABLE_MEANS.csv'))
  writeLines(c('SORTING_MAIN_DECISION_UNRESOLVED_APPROVAL_TRACE',
    'Canonical lock v1.2 E0: modal-ISCED main. Later RC1-SORT-001 change register: all-target main.',
    'No explicit user approval of this specific lock change located. Compute and preserve both.',
    'No PIRLS year pairs substituted for TIMSS; candidate plan requires empirical timing review.',
    'RC1 milestone immutable; PIRLS 2001/2006/2011 core is separately re-estimated with cycle-aware JRR; new supplements for all waves.'),file.path(out,'SCIENTIFIC_DECISION_REGISTER.txt'))
  rc2_csv(data.frame(file=baseline$path,sha256=baseline$sha,script_sha256=RC2_BASELINE_SHA,rows=nrow(baseline$master$estimates)),file.path(out,'BASELINE_PROVENANCE.csv'))
  cacheaudit<-rc2_baseline_cache_audit(root,baseline,out)
  downloads<-getOption('pisa.rc2.downloads',dirname(root));inv<-rc2_inventory(downloads,root)
  inv<-inv[!grepl('/22_completion_final_v8/(cache|runs|extracts)/',inv$path),,drop=FALSE]
  rc2_csv(inv,file.path(out,'LOCAL_SOURCE_INVENTORY.csv'))
  prepared<-rc2_restore_preparation(base,out)
  if(is.null(prepared)) {
  parts<-holds<-list();addhold<-function(s,y,c,e){holds[[length(holds)+1L]]<<-data.frame(survey=s,year=y,source_country_code=c,status='INPUT_HOLD',reason=conditionMessage(e));rc2_log(s,' ',y,' ',c,': ',conditionMessage(e))}
  for(year in c(2003L,2006L,2009L,2012L,2015L,2018L,2022L,2025L)) {
    rc2_log('Preparing PISA ',year,' source, variable labels and supplements')
    ans<-tryCatch({
      src<-rc2_pisa_source(year,inv,file.path(base,'extracts'))
      prep<-rc2_prepare_pisa(year,src,file.path(cache,'pisa'),dict,root)
      if(nrow(prep$tasks)) {
        mode<-if(year%in%c(2003L,2006L,2009L,2012L,2018L,2025L))'gender_supplement' else 'supplement'
        prep$tasks$mode<-mode

      };prep
    },error=function(e)e)
    if(inherits(ans,'error'))addhold('PISA',year,'ALL',ans) else {parts[[length(parts)+1L]]<-ans$tasks;holds[[length(holds)+1L]]<-ans$errors}
    rc2_csv(rc2_bind(holds),file.path(out,'SOURCE_TASK_HOLDS.csv'))
  }
  numeracy<-tryCatch(rc2_numeracy_sources(inv,sources),error=function(e){addhold('TIMSS',2015,'NUMERACY',e);NULL})
  for(year in c(1995L,2003L,2007L,2011L,2015L,2019L,2023L)) {
    rc2_log('Preparing TIMSS ',year,'; validated main sources and required companion samples')
    ans<-tryCatch({
      rec<-rc2_timss_sources(year,inv,sources,file.path(base,'extracts'),isTRUE(getOption('pisa.rc2.download',TRUE)))
      if(year==2015L&&!is.null(numeracy))for(code in setdiff(names(numeracy),unique(rec$source_country_code))) {
        p<-numeracy[[code]];rec<-rc2_bind(list(rec,data.frame(year=2015L,source_country_code=code,role='G',path=p,source_path=p,member=basename(p),source_sha256=rc2_sha(p),payload_sha256=rc2_sha(p),source_conflict=FALSE)))
      }
      rc2_csv(rec,file.path(out,paste0('TIMSS_',year,'_SOURCE_MEMBERS.csv')))
      rc2_prepare_iea(rec,cache,dict,sources,numeracy)
    },error=function(e)e)
    if(inherits(ans,'error'))addhold('TIMSS',year,'ALL',ans) else {parts[[length(parts)+1L]]<-ans$tasks;holds[[length(holds)+1L]]<-ans$errors}
    rc2_csv(rc2_bind(holds),file.path(out,'SOURCE_TASK_HOLDS.csv'))
  }
  ans<-tryCatch(rc2_prepare_pirls(root,cache,dict),error=function(e)e)
  if(inherits(ans,'error'))addhold('PIRLS',NA,'ALL',ans) else {parts[[length(parts)+1L]]<-ans$tasks;holds[[length(holds)+1L]]<-ans$errors}
  tasks<-rc2_bind(parts);holds<-rc2_bind(holds)
  rc2_commit_preparation(base,out,tasks,holds)
  } else {tasks<-prepared$tasks;holds<-prepared$holds}
  rc2_csv(holds,file.path(out,'SOURCE_TASK_HOLDS.csv'))
  if(nrow(tasks)) {
    key<-with(tasks,paste(survey,year,source_country_code,domain,sep='_'))
    if(anyDuplicated(key))stop('Duplicate repair task keys')
    tasks$result_cache<-file.path(cache,'results',paste0(key,'_',substr(tasks$input_key,1,16),'.rds'))
  }
  rc2_csv(tasks,file.path(out,'REPAIR_TASK_MANIFEST.csv'))
  rc2_plan_tasks(tasks,baseline$master$estimates,out)
  phy<-suppressWarnings(parallel::detectCores(logical=FALSE));if(!is.finite(phy))phy<-4L
  workers<-as.integer(getOption('pisa.rc2.workers',max(1L,min(6L,phy-2L))));workers<-max(1L,min(8L,workers))
  rc2_log('Tasks: ',nrow(tasks),'; PSOCK cap 8, default <=6; one BLAS thread per worker')
  results<-if(nrow(tasks))rc2_parallel(tasks,workers,out) else list()
  rc2_write_optimization_audit(tasks,results,out)
  new<-rc2_add_identity(rc2_bind(lapply(results,`[[`,'estimates')))
  task_status<-rc2_bind(lapply(results,`[[`,'status'))
  # Never silently relabel an unrecognised reporting system as its parent country.
  merged<-if(nrow(new))rc2_merge_repaired(baseline$master$estimates,new) else list(estimates=baseline$master$estimates,changes=data.frame(),preserved=nrow(baseline$master$estimates),replaced=0L,added=0L)
  e<-merged$estimates
  # Retain invalidated old rows for loss accounting but flag, never publish them as repaired.
  e$repair_state<-ifelse(e$analysis_version==RC2_VERSION,'RECOMPUTED_PENDING_VALIDATION','PRESERVED_V6')
  invalidated<-e$analysis_version!=RC2_VERSION&((e$survey=='TIMSS'&e$year==1995L)|
    (e$survey=='TIMSS'&e$year==2015L&e$domain=='mathematics'&e$source_country_code%in%c('BHR','IDN','IRN','KWT','MAR','ABA'))|
    (e$survey=='PISA'&e$year%in%c(2003L,2006L,2009L,2012L,2018L,2025L)&grepl('^gender_',e$statistic)))
  e$repair_state[invalidated]<-'INVALIDATED_V6_AWAITING_SUCCESSFUL_REPAIR'
  checks<-rc2_semantic_checks(e)
  checks$checks<-rc2_bind(list(checks$checks,data.frame(check='baseline_master_byte_unchanged',pass=identical(rc2_sha(baseline$path),baseline$sha),detail=baseline$path)))
  diagnostics<-rc2_bind(lapply(results,`[[`,'diagnostics'))
  status<-if(nrow(holds)||any(task_status$task_status=='TASK_ERROR')||any(invalidated)||!all(checks$checks$pass))'PARTIAL_WITH_EXPLICIT_HOLDS' else 'REPAIRS_COMPUTED_PENDING_SCIENTIFIC_VALIDATION'
  master<-list(metadata=list(version=RC2_VERSION,execution_version='optimized_20260927',compute_compatibility_sha256=rc2_compute_sha,script_sha256=RC2_SCRIPT_SHA,baseline_sha256=baseline$sha,created_at=as.character(Sys.time()),state=status,scientific_freeze=FALSE),
    estimates=e,diagnostics=diagnostics,task_status=task_status,source_holds=holds,validation=checks$checks,scope=rc2_scope_status())
  rc2_save(master,file.path(out,'COMPLETION_AGGREGATE_MASTER.rds'))
  # CSV derives from the freshly read R master, not an in-memory partial object.
  master<-readRDS(file.path(out,'COMPLETION_AGGREGATE_MASTER.rds'))
  rc2_csv(master$estimates,file.path(out,'COMPLETION_ESTIMATES.csv'))
  rc2_csv(merged$changes,file.path(out,'BASELINE_TO_FINAL_CHANGE_REGISTER.csv'))
  rc2_csv(task_status,file.path(out,'REPAIR_TASK_STATUS.csv'))
  rc2_csv(diagnostics,file.path(out,'REPAIR_COUNTRY_DIAGNOSTICS.csv'))
  rc2_csv(rc2_bind(lapply(results,`[[`,'variance_sensitivity')),file.path(out,'HISTORICAL_SE_METHOD_DIAGNOSTIC.csv'))
  rc2_csv(rc2_bind(lapply(results,`[[`,'counts')),file.path(out,'REPLICATE_COMPLETENESS.csv'))
  rc2_csv(rc2_bind(lapply(results,`[[`,'gender_support')),file.path(out,'GENDER_GROUP_SUPPORT.csv'))
  rc2_csv(checks$checks,file.path(out,'TECHNICAL_VALIDATION.csv'))
  rc2_csv(checks$identity_failures,file.path(out,'GROUP_IDENTITY_FAILURES.csv'))
  rc2_csv(checks$unexpected_missing,file.path(out,'UNEXPLAINED_MISSING_MEANS.csv'))
  tryCatch({pcheck<-rc2_external_mean_check(e,out);if(!is.null(pcheck)){
    k<-pcheck$source_country_code=='PSE'&pcheck$year==2022L
    pcheck$external_check[k]<-'UNRESOLVED_SOURCE_EDITION_OR_POPULATION_DIFFERENCE; NOT_ADJUDICATED'
    rc2_csv(pcheck,file.path(out,'PISA_CHECKS_ADJUDICATED.csv'))
  }},error=function(x)writeLines(conditionMessage(x),file.path(out,'PISA_EXTERNAL_HOLD.txt')))
  tryCatch(rc2_compare_expanded(e,out),error=function(x)writeLines(conditionMessage(x),file.path(out,'EXPANDED_EXTERNAL_HOLD.txt')))
  rc2_csv(data.frame(item=c('V6 aggregate master','Untouched V6 cells','Replaced V6 cells','Added cells','RC1 and user products','Original sources'),
    action=c('SHA256 unchanged',paste(merged$preserved,'preserved exactly'),paste(merged$replaced,'preserved in change register'),paste(merged$added,'new result rows'),'Read-only; no product integration in step1','Read-only; new downloads separately cached'),loss=c('none','none','none','none','none','none')),
    file.path(out,'LOSS_REGISTER.csv'))
  file.copy(RC2_SCRIPT_PATH,file.path(out,'EXECUTED_COMPLETION_SCRIPT.R'))
  writeLines(capture.output(sessionInfo()),file.path(out,'SESSION_INFO.txt'))
  writeLines(c(paste('Status:',status),paste('Tasks:',nrow(tasks),'Source holds:',nrow(holds)),paste('V6 cells preserved:',merged$preserved,'replaced:',merged$replaced,'added:',merged$added),
    'No microdata in this ZIP. Student inputs and resumable caches remain local.',
    'No scientific freeze; no main-specification change; no product deployment.',
    'RC1 original retained; historical PIRLS core uncertainty repaired in a separate output; no automatic product overwrite.',
    'All output CSVs are written atomically and read back against the R master.',
    'Unresolved source tasks are listed individually; continue independent tasks; repeat same script to resume.'),file.path(out,'00_README.txt'))
  rc2_export_aggregate_caches(root,baseline,tasks,results,out)
  rc2_csv(rc2_bind(lapply(results,`[[`,'extended_group_support')),file.path(out,'EXTENDED_GROUP_SUPPORT.csv'))
  rc2_csv(RC2_REPAIR_TESTS,file.path(out,'SELFTEST_RESULTS.csv'))
  # Close logs before manifest; no output file may be mutated after this point.
  rc2_log('All aggregate exports complete. Creating and checksum-verifying output ZIP.')
  RC2_LOG<<-''
  zp<-rc2_output_zip(out,file.path(root,'RUNNER','handoffs',paste0('PISA_PIRLS_FINAL_OUTPUT_',stamp,'.zip')))
  cat('\nKLAAR: ',status,'\nUpload deze ZIP:\n',rc2_norm(zp),'\nSHA256: ',rc2_sha(zp),'\n',sep='')
  invisible(list(zip=zp,output=out,state=status))
}
