rc2_gender_candidate_audit <- function(raw,survey,year,code,outdir) {
  dic<-rc2_dictionary(raw);cand<-dic$variable[grepl('^ST004|^ST04Q01$|^ST03Q01$|^ITSEX$|SEX|GENDER',toupper(paste(dic$variable,dic$label)))]
  wv<-intersect(c('W_FSTUWT','TOTWGT'),names(raw));w<-if(length(wv))rc2_num(raw[[wv[1]]]) else rep(NA_real_,nrow(raw));good<-is.finite(w)&w>0
  chosen<-rc2_gender_decode(raw,survey,year);rows<-list()
  for(v in cand) {
    x<-rc2_chr(raw[[v]]);x[is.na(x)]<-'MISSING';labs<-attr(raw[[v]],'labels',exact=TRUE)
    for(a in unique(x))rows[[length(rows)+1L]]<-data.frame(survey=survey,year=year,source_country_code=code,variable=v,
      label=dic$label[match(v,dic$variable)],value=a,value_label=if(a=='MISSING')'missing' else paste(names(labs)[as.character(unname(labs))==a],collapse='|'),
      n=sum(x==a),weighted_share=if(any(good))sum(w[good&x==a])/sum(w[good]) else NA_real_,selected=v==chosen$variable,
      decision=if(survey=='PISA'&&year==2003L&&v=='ST04Q01')'REJECTED_MOTHER_LIVING_AT_HOME' else chosen$status)
  }
  rc2_csv(rc2_bind(rows),file.path(outdir,paste0(survey,'_',year,'_',code,'_GENDER_CANDIDATES.csv')))
}

